Object.assign(window.TEM8_DICTIONARY, {"threaten":{"oxford":{"phon":"ˈθretn","pos":"verb","senses":[{"en":"to say that you will cause trouble, hurt somebody, etc. if you do not get what you want","cn":"扬言要；威胁；恐吓","g":"[transitive]","ex":{"en":"They broke my windows and threatened me.","cn":"他们砸碎我的窗子并威胁我。"}},{"en":"to seem likely to happen or cause something unpleasant","cn":"预示凶兆；有…危险","g":"[intransitive, transitive]","ex":{"en":"A storm was threatening.","cn":"暴风雨即将来临。"}},{"en":"to be a danger to something","cn":"危及；对…构成威胁","g":"[transitive]","ex":{"en":"Pollution is threatening marine life.","cn":"污染正危及海洋生物。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"威胁;恐吓","en":"If a person threatens to do something unpleasant to you, or if they threaten you, they say or imply that they will do something unpleasant to you, especially if you do not do what they want.","ex":{"en":"He said army officers had threatened to destroy the town","cn":"他说陆军军官们曾威胁要摧毁那座小镇。"}},{"pos":"VERB 动词","cn":"危害到;威胁到","en":"If something or someone threatens a person or thing, they are likely to harm that person or thing.","ex":{"en":"The newcomers directly threaten the livelihood of the established workers","cn":"新来的工人直接威胁到老工人的饭碗。"}},{"pos":"VERB 动词","cn":"(坏事)可能发生，将要发生","en":"If something unpleasant threatens to happen, it seems likely to happen.","ex":{"en":"The fighting is threatening to turn into full-scale war","cn":"这场战斗有可能会演变为全面的战争。"}}]},"media":{"uk":"media/uk/threaten__gb_1.mp3","us":"media/us/threaten__us_1.mp3"},"examples":[{"en":"The hijackers threatened to kill one passenger every hour if their demands were not met.","cn":"劫机者要挟说，如果他们的要求得不到满足，他们每过一小时就杀死一名乘客。"},{"en":"He was threatened with dismissal if he continued to turn up late for work.","cn":"他受到警告，如果继续上班迟到，就被辞退。"}]},"thumb":{"media":{"uk":"media/uk/thumb__gb_1.mp3","us":"media/us/thumb__us_1.mp3","img":["media/ldoce/img/hand.jpg"]},"oxford":{"phon":"θʌm","pos":"noun","senses":[{"en":"the short, thick finger at the side of the hand, slightly apart from the other four","cn":"拇指","ex":{"en":"She still sucks her thumb when she's worried.","cn":"她在忧虑时仍然会吸吮大拇指。"}},{"en":"the part of a glove that covers the thumb","cn":"（手套的）拇指部分","ex":{"en":"There's a hole in the thumb.","cn":"手套的拇指上有个窟窿。"}},{"en":"to make a signal with your thumb to passing drivers to ask them to stop and take you somewhere","cn":"跷起拇指请求搭乘（过路汽车）；示意请求搭便车","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"He had thumbed all across Europe.","cn":"他搭乘便车游遍了欧洲。"},"pos":"verb"},{"en":"to touch or move something with your thumb","cn":"用拇指摸；用拇指捋","g":"[transitive]","ex":{"en":"She thumbed off the safety catch of her pistol.","cn":"她用拇指打开了手枪的保险栓。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(大)拇指","en":"Your thumb is the short thick part on the side of your hand next to your four fingers.","ex":{"en":"She bit the tip of her left thumb, not looking at me.","cn":"她咬着左手的拇指尖，眼睛也不看我。"}},{"pos":"N-COUNT 可数名词","cn":"(手套的)拇指部分","en":"The thumb of a glove is the part which a person's thumb fits into."},{"pos":"VERB 动词","cn":"(站在路边，伸出手，拇指向上)请求搭便车，拦车","en":"If you thumb a lift or thumb a ride, you stand by the side of the road holding out your thumb until a driver stops and gives you a lift.","ex":{"en":"It may interest you to know that a boy answering Rory's description thumbed a ride to Howth","cn":"你或许会对这个消息感兴趣，有个和罗里描述的一模一样的小男孩搭便车到了霍斯。"}},{"pos":"PHRASE 短语","cn":"扎眼;碍眼","en":"If you say that someone or something sticks out like a sore thumb or stands out like a sore thumb, you are emphasizing that they are very noticeable, usually because they are unusual or inappropriate.","ex":{"en":"Does the new housing stick out like a sore thumb or blend into its surroundings?","cn":"这个新住宅区是显得有点扎眼，还是和环境融为一体？"}},{"pos":"PHRASE 短语","cn":"无所事事;闲着无聊","en":"If you say that someone is twiddling their thumbs, you mean that they do not have anything to do and are waiting for something to happen.","ex":{"en":"The prospect of waiting around just twiddling his thumbs was appalling","cn":"想到将要无所事事，他就非常害怕。"}},{"pos":"PHRASE 短语","cn":"在…控制下;深受…影响","en":"If you are under someone's thumb, you are under their control, or very heavily influenced by them.","ex":{"en":"I cannot tell you what pain I feel when I see how much my mother is under my father's thumb","cn":"看见我母亲完完全全受我父亲的控制，我心里别提有多难受。"}},{"pos":"","cn":"","en":"green thumb→see: ; to thumb your nose at someone→see: ; rule of thumb→see: ;"},{"pos":"","cn":"","en":"相关词组：thumb through"}]},"examples":[{"en":"We managed to thumb a lift with a lorry driver.","cn":"我们竖起拇指招呼过路的卡车司机让我们搭便车。"},{"en":"We managed to thumb a ride with a truck driver.","cn":"我们竖起拇指招呼过路的卡车司机让我们搭便车。"}]},"thoughts":{"lemma":"thought","media":{"uk":"media/uk/thought__gb_2.mp3","us":"media/us/thought__us_2.mp3"}},"their":{"media":{"uk":"media/uk/their__gb_1.mp3","us":"media/us/their__us_1.mp3"},"oxford":{"phon":"ðeə(r)","pos":"determiner","senses":[{"en":"of or belonging to people, animals or things that have already been mentioned or are easily identified","cn":"他们的；她们的；它们的","ex":{"en":"Their parties are always fun.","cn":"他们的聚会总是乐趣横生。"}},{"en":"used instead of his or her to refer to a person whose sex is not mentioned or not known","cn":"（在提及性别不详的人时，用以代替 his 或 her）","lab":"British English","ex":{"en":"If anyone calls, ask for their number so I can call them back.","cn":"如有人打电话来，问问他们的电话号码，这样我可以回电话。"}}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"他们的;她们的;它们的","en":"You use their to indicate that something belongs or relates to the group of people, animals, or things that you are talking about.","ex":{"en":"Janis and Kurt have announced their engagement","cn":"贾尼斯和库尔特已宣布订婚。"}},{"pos":"DET-POSS 所有格限定词","cn":"(代替 his or her，而不指明是男是女;有人认为这种用法不对)","en":"You use their instead of 'his or her' to indicate that something belongs or relates to a person without saying whether that person is a man or a woman. Some people think this use is incorrect.","ex":{"en":"Every member will receive their own 'Welcome to Labour' brochure.","cn":"每个党员都将收到一本名为《欢迎加入工党》的小册子。"}}]},"examples":[{"en":"If anyone calls, ask for their number so I can call them back.","cn":"如有人打电话来，问问他们的电话号码，这样我可以回电话。"},{"en":"Their parties are always fun.","cn":"他们的聚会总是乐趣横生。"}]},"theatre":{"oxford":{"phon":"ˈθɪətə(r)","pos":"noun","senses":[{"en":"a building or an outdoor area where plays and similar types of entertainment are performed","cn":"戏院；剧场；露天剧场","g":"[countable]","ex":{"en":"Broadway theatres","cn":"百老汇的剧院"}},{"en":"a building in which films are shown","cn":"电影院","g":"[countable]","lab":"both North American English","ex":{"en":"They arrived at the movie theater a few minutes later.","cn":"他们几分钟后到了电影院。"}},{"en":"plays considered as entertainment","cn":"戏剧","g":"[uncountable]","lab":"British English","ex":{"en":"an evening of live music and theatre","cn":"现场演奏音乐戏剧晚会"}},{"en":"the work of writing, producing and acting in plays","cn":"戏剧工作；剧作；演出；上演","g":"[uncountable]","ex":{"en":"I want to work in theatre.","cn":"我想从事戏剧工作。"}},{"en":"a room in a hospital used for medical operations","cn":"手术室","g":"[countable, uncountable]","lab":"both British English","ex":{"en":"a theatre sister (= a nurse who helps during operations)","cn":"手术室护士"}},{"en":"the place in which a war or fighting takes place","cn":"战场；战区","g":"[countable, usually singular]","lab":"formal","ex":{"en":"an intelligence officer in the Pacific theatre","cn":"太平洋战区的一名情报官员"}}]},"collins":{"senses":[{"pos":"N-COUNT; N-IN-NAMES 名称名词；名称名词","cn":"剧场;戏院","en":"A theatre is a building with a stage in it, on which plays, shows, and other performances take place.","ex":{"en":"If we went to the theatre it was a very big event","cn":"我们要是去看场戏，那可是件大事。"}},{"pos":"N-SING 单数名词","cn":"戏剧工作;舞台表演;戏剧创作","en":"You can refer to work in the theatre such as acting or writing plays as the theatre .","ex":{"en":"You can move up to work in films and the theatre","cn":"你可以转行从事影视戏剧业。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"演戏;戏剧表演","en":"Theatre is entertainment that involves the performance of plays.","ex":{"en":"Companies across the country are beginning to show a healthy interest in theatre for children.","cn":"全国有多家公司都开始对儿童戏剧表现出极大的兴趣。"}},{"pos":"N-COUNT 可数名词","cn":"电影院;剧院","en":"A theater or a movie theater is a place where people go to watch films for entertainment."},{"pos":"N-COUNT 可数名词","cn":"(医院的)手术室","en":"In a hospital, a theatre is a special room where surgeons carry out medical operations.","ex":{"en":"She is back from theatre and her condition is comfortable.","cn":"她从手术室出来了，身体状况良好。"}},{"pos":"N-COUNT 可数名词","cn":"战区;战场;冲突地区","en":"A theatre of war or other conflict is the area or region in which the war or conflict is happening.","ex":{"en":"The Middle East has often been a theatre of war.","cn":"中东这一地区一直战乱频仍。"}}]},"media":{"uk":"media/uk/theatre__gb_1.mp3","us":"media/us/theatre__us_1.mp3"},"examples":[{"en":"( BrE ) I like music, theatre and cinema.","cn":"我喜欢音乐、戏剧和电影。"},{"en":"current ideas about what makes good theatre (= what makes good entertainment when performed)","cn":"对何谓好戏剧的普遍看法"}]},"thanked":{"lemma":"thank","media":{"uk":"media/uk/thank__gb_1.mp3","us":"media/us/thank__us_1.mp3"}},"threatened":{"lemma":"threaten"},"thread":{"oxford":{"phon":"θred","pos":"noun","senses":[{"en":"a thin string of cotton, wool, silk, etc. used for sewing or making cloth","cn":"（棉、毛、丝等的）线","g":"[uncountable, countable]","ex":{"en":"a needle and thread","cn":"针线"}},{"en":"an idea or a feature that is part of something greater; an idea that connects the different parts of something","cn":"线索；脉络；思路；贯穿的主线","g":"[countable]","ex":{"en":"A common thread runs through these discussions.","cn":"这些讨论都贯穿着一条共同的主线。"}},{"en":"a long, thin line of something","cn":"线状物；细细的一条","g":"[countable]","ex":{"en":"A thread of light emerged from the keyhole.","cn":"从锁眼里透出一丝光亮。"}},{"en":"a series of connected messages on email, social media, etc. that have been sent by different people","cn":"（电子邮件、社交媒体等的）系列相关信息，链式消息","g":"[countable]","lab":"computing"},{"en":"the raised line that runs around the length of a screw and that allows it to be fixed in place by twisting","cn":"螺纹","g":"[countable]"},{"en":"clothes","cn":"衣服","g":"[plural]","lab":"North American English, old-fashioned, informal，，，，"},{"en":"to pass something long and thin, especially thread, through a narrow opening or hole","cn":"穿（针）；纫（针）；穿过","g":"[transitive]","ex":{"en":"to thread a needle (with cotton)","cn":"（用棉线）纫针"},"pos":"verb"},{"en":"to move or make something move through a narrow space, avoiding things that are in the way","cn":"（使）穿过；通过；穿行","g":"[intransitive, transitive]","ex":{"en":"The waiters threaded between the crowded tables.","cn":"服务员穿行在拥挤的餐桌之间。"},"pos":"verb"},{"en":"to join two or more objects together by passing something long and thin through them","cn":"穿成串；串在一起","g":"[transitive]","ex":{"en":"to thread beads (onto a string)","cn":"（在绳子上）把珠子串起来"},"pos":"verb"},{"en":"to pass film, tape, string, etc. through parts of a piece of equipment so that it is ready to use","cn":"给…装入（胶片、磁带、丝弦等）","g":"[transitive]","pos":"verb"},{"en":"to sew or twist a particular type of thread into something","cn":"用…线缝；把…线绞入","g":"[transitive, usually passive]","ex":{"en":"a robe threaded with gold and silver","cn":"用金银线缝的长袍"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"(尤指用于缝纫的)细线，细丝","en":"Thread or a thread is a long very thin piece of a material such as cotton, nylon, or silk, especially one that is used in sewing.","ex":{"en":"This time I'll do it properly with a needle and thread.","cn":"这次，我要用针线将它缝好。"}},{"pos":"N-COUNT 可数名词","cn":"主线;思路;脉络","en":"The thread of an argument, a story, or a situation is an aspect of it that connects all the different parts together.","ex":{"en":"The thread running through many of these proposals was the theme of individual power and opportunity","cn":"贯穿这许多提案的主线是个人权力和机遇这一主题。"}},{"pos":"N-COUNT 可数名词","cn":"线状物;一线","en":"A thread of something such as liquid, light, or colour is a long thin line or piece of it.","ex":{"en":"A thin, glistening thread of moisture ran along the rough concrete sill.","cn":"在粗糙不平的水泥窗台上有一条细细的发光水印。"}},{"pos":"N-PLURAL 复数名词","cn":"衣服","en":"You can refer to clothes as threads .","ex":{"en":"...a cheap place to pick up natty threads.","cn":"能买到既整洁时髦而又便宜的衣服的去处"}},{"pos":"N-COUNT 可数名词","cn":"螺纹","en":"The thread on a screw, or on something such as a lid or a pipe, is the raised spiral line of metal or plastic around it which allows it to be fixed in place by twisting.","ex":{"en":"The screw threads will be able to get a good grip.","cn":"螺纹能牢牢地咬合卡紧。"}},{"pos":"VERB 动词","cn":"穿行;曲折穿过;蜿蜒","en":"If you thread your way through a group of people or things, or thread through it, you move through it carefully or slowly, changing direction frequently as you move.","ex":{"en":"Slowly she threaded her way back through the moving mass of bodies","cn":"她从人流中慢慢地挤了回来。"}},{"pos":"VERB 动词","cn":"使(细长的物体)穿过;使穿进","en":"If you thread a long thin object through something, you pass it through one or more holes or narrow spaces.","ex":{"en":"...threading the laces through the eyelets of his shoes","cn":"把鞋带穿进他的鞋眼"}},{"pos":"VERB 动词","cn":"将(珠子等)穿起来","en":"If you thread small objects such as beads onto a string or thread, you join them together by pushing the string through them.","ex":{"en":"Wipe the mushrooms clean and thread them on a string.","cn":"把这些蘑菇擦干净，然后用线穿起来。"}},{"pos":"VERB 动词","cn":"穿(针)","en":"When you thread a needle, you put a piece of thread through the hole in the top of the needle in order to sew with it.","ex":{"en":"I sit down, thread a needle, snip off an old button.","cn":"我坐下来，穿好针，剪下一枚旧纽扣。"}},{"pos":"PHRASE 短语","cn":"千钧一发;岌岌可危","en":"If you say that something is hanging by a thread, you mean that it is in a very uncertain state and is unlikely to survive or succeed.","ex":{"en":"The fragile peace was hanging by a thread as thousands of hardliners took to the streets.","cn":"成千上万的强硬派分子走上街头示威，脆弱的和平局势危在旦夕。"}},{"pos":"PHRASE 短语","cn":"(活动中断后)继续下去/(经历失败、霉运后)恢复生机","en":"If you pick up the threads of an activity, you start it again after an interruption. If you pick up the threads of your life, you become more active again after a period of failure or bad luck.","ex":{"en":"Many women have been able to pick up the threads of their former career.","cn":"许多女性得以重操旧业。"}}]},"media":{"img":["media/ldoce/img/thread.jpg","media/pic/rope_comp.jpg"],"uk":"media/uk/thread__gb_1.mp3","us":"media/us/thread__us_1.mp3"},"examples":[{"en":"The author skilfully draws together the different threads of the plot.","cn":"作者娴熟地把情节的各种线索串联在一起。"},{"en":"A common thread runs through these discussions.","cn":"这些讨论都贯穿着一条共同的主线。"}]},"them":{"media":{"uk":"media/uk/them__gb_1.mp3","us":"media/us/them__us_1.mp3"},"oxford":{"phon":"ðəm","pos":"pronoun","senses":[{"en":"used when referring to people, animals or things as the object of a verb or preposition, or after the verb be","cn":"他们；她们；它们","ex":{"en":"Tell them the news.","cn":"把这消息告诉他们。"}},{"en":"used instead of him or her to refer to a person whose sex is not mentioned or not known","cn":"（指性别不详的人时，用以代替 him 或 her）","ex":{"en":"If anyone comes in before I get back, ask them to wait.","cn":"如果在我回来之前有人来，就请他等一等。"}}]},"collins":{"senses":[{"pos":"PRON-PLURAL 复数型代词","cn":"他们;她们;它们","en":"You use them to refer to a group of people, animals, or things.","ex":{"en":"The Beatles — I never get tired of listening to them","cn":"甲壳虫乐队——我是百听不厌。"}},{"pos":"PRON-PLURAL 复数型代词","cn":"(代替 him or her，而不指明是男是女;有人认为这种用法不对)","en":"You use them instead of 'him or her' to refer to a person without saying whether that person is a man or a woman. Some people think this use is incorrect.","ex":{"en":"It takes great courage to face your child and tell them the truth.","cn":"面对自己的孩子，告诉他们真相是需要很大勇气的。"}},{"pos":"DET 限定词","cn":"那些(不规范口语中代替those)","en":"In non-standard spoken English, them is sometimes used instead of 'those'.","ex":{"en":"'Our Billy doesn't eat them ones,' Helen said.","cn":"“咱家比利不吃那些东西，”海伦说。"}}]},"examples":[{"en":"If anyone comes in before I get back, ask them to wait.","cn":"如果在我回来之前有人来，就请他等一等。"},{"en":"What are you doing with those matches? Give them to me.","cn":"你拿那些火柴做什么？把它们交给我。"}]},"three-quarters":{"collins":{"senses":[{"pos":"QUANT 数量词","cn":"四分之三","en":"Three-quarters is an amount that is three out of four equal parts of something.","ex":{"en":"Three-quarters of the country's workers took part in the strike","cn":"该国有 3/4 的工人参加了这次罢工。"}}]},"media":{"uk":"media/ldoce/hwd/bre/9/three_quarters0205.mp3","us":"media/ldoce/hwd/ame/d/laadthree-quarters.mp3"},"examples":[{"en":"three-quarters of an hour 45","cn":"分钟"}],"oxford":{"phon":"ˌθriː ˈkwɔːtəz","pos":"noun","senses":[{"en":"three of the four equal parts into which something may be divided","cn":"四分之三","ex":{"en":"three quarters of an hour","cn":"四十五分钟"}}]}},"theory":{"media":{"uk":"media/uk/theory__gb_1.mp3","us":"media/us/theory__us_1.mp3"},"oxford":{"phon":"ˈθɪəri","pos":"noun","senses":[{"en":"a formal set of ideas that is intended to explain why something happens or exists","cn":"学说；论；说","g":"[countable, uncountable]","ex":{"en":"the theory of evolution/relativity","cn":"进化论；相对论"}},{"en":"the principles on which a particular subject is based","cn":"理论；原理；原则","g":"[uncountable]","ex":{"en":"the theory and practice of language teaching","cn":"语言教学理论与实践"}},{"en":"an opinion or idea that somebody believes is true but that is not proved","cn":"（未证明的）意见；看法；推测","g":"[countable]","ex":{"en":"Theories abound (= people have lots of different ideas) about what happened.","cn":"关于发生了什么事众说纷纭。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"理论;学说","en":"A theory is a formal idea or set of ideas that is intended to explain something.","ex":{"en":"Marx produced a new theory about historical change based upon conflict between competing groups","cn":"马克思创立了一种新理论，认为历史的演变是基于对立集团之间的冲突之上的。"}},{"pos":"N-COUNT 可数名词","cn":"观点;见解","en":"If you have a theory about something, you have your own opinion about it which you cannot prove but which you think is true.","ex":{"en":"There was a theory that he wanted to marry her","cn":"有人认为他想娶她。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(实践科目、技能的)理论基础","en":"The theory of a practical subject or skill is the set of rules and principles that form the basis of it.","ex":{"en":"He taught us music theory.","cn":"他教我们乐理。"}},{"pos":"PHRASE 短语","cn":"从理论上说;照理说","en":"You use in theory to say that although something is supposed to be true or to happen in the way stated, it may not in fact be true or happen in that way.","ex":{"en":"A school dental service exists in theory, but in practice, there are few dentists to work in them.","cn":"照理说，学校也有牙医诊所，可实际上，里面的牙医寥寥无几。"}}]},"examples":[{"en":"That sounds fine in theory, but have you really thought it through?","cn":"这话听起来很有道理，但是你真正全面考虑过没有？"},{"en":"I have this theory that most people prefer being at work to being at home.","cn":"依我看，多数人喜欢工作而不愿待在家里。"}]},"threads":{"lemma":"thread"},"thrilled":{"media":{"uk":"media/uk/thrilled__gb_1.mp3","us":"media/us/thrilled__us_1.mp3"},"oxford":{"phon":"θrɪld","pos":"adjective","senses":[{"en":"very excited and pleased","cn":"非常兴奋的；极为激动的","lab":"British English","ex":{"en":"‘Are you pleased?’ ‘I'm thrilled.’","cn":"“你高兴吗？”“我太兴奋了。”"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"欣喜若狂的;非常开心的","en":"If someone is thrilled, they are extremely pleased about something.","ex":{"en":"I was so thrilled to get a good report from him","cn":"收到他的好消息让我欣喜若狂。"}}]},"examples":[{"en":"He was thrilled at the prospect of seeing them again.","cn":"他一想到有望再次见到他们便欣喜若狂。"},{"en":"( BrE ) She was thrilled to bits (= extremely pleased) that he'd been offered the job.","cn":"她得知他得到了这份工作简直乐不可支。"}],"base":"thrill"},"though":{"media":{"uk":"media/uk/though__gb_1.mp3","us":"media/us/though__us_1.mp3"},"oxford":{"phon":"ðəʊ","pos":"conjunction","senses":[{"en":"despite the fact that","cn":"虽然；尽管；即使","ex":{"en":"Anne was fond of Tim, though he often annoyed her.","cn":"安妮喜欢蒂姆，虽然他经常使她心烦。"}},{"en":"used to add a fact or an opinion that makes the previous statement less strong or less important","cn":"（用于主句后，引出补充说明，使语气变弱）不过，可是，然而","ex":{"en":"They're very different, though they did seem to get on well when they met.","cn":"他们大不相同，可是见面后好像还确实相处得不错。"}},{"en":"used especially at the end of a sentence or clause to add a fact or an opinion that makes the previous statement less strong or less important","cn":"（尤用于句末补充说明，使语气减弱）不过，可是，然而","ex":{"en":"Our team lost. It was a good game though.","cn":"我们队输了，可是这也不失为一场好球。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"CONJ-SUBORD 连词","cn":"尽管;虽然","en":"You use though to introduce a statement in a subordinate clause which contrasts with the statement in the main clause. You often use though to introduce a fact which you regard as less important than the fact in the main clause.","ex":{"en":"Gaelic has been a dying language for many years, though children are nowadays taught it in school","cn":"盖尔语多年来一直濒于消亡，尽管如今孩子们还在学校学习这门语言。"}},{"pos":"CONJ-SUBORD 连词","cn":"不过;可是;然而","en":"You use though to introduce a subordinate clause which gives some information that is relevant to the main clause and weakens the force of what it is saying.","ex":{"en":"I look back on it as the bloodiest (though not literally) winter of the war","cn":"我现在回想起来，觉得那是战时最血腥的(但并非字面意义上的)一个冬天。"}},{"pos":"ADV 副词","cn":"不过;但是","en":"You use though to indicate that the information in a clause contrasts with or modifies information given in a previous sentence or sentences.","ex":{"en":"I like him. Though he makes me angry sometimes","cn":"我喜欢他，不过他有时惹我生气。"}},{"pos":"PHRASE 短语","cn":"不是吹牛;我不是自夸","en":"You can say though I say so myself or even though I say it myself when you are praising yourself or something you have done, but do not want to sound too proud.","ex":{"en":"I'm a good cook, though I say it myself","cn":"我并非自夸，我的厨艺的确高超。"}},{"pos":"","cn":"","en":"as though→see: ; even though→see: ;"}]},"examples":[{"en":"His clothes, though old and worn, looked clean and of good quality.","cn":"他的衣服虽然很旧，但看上去干干净净，质地很好。"},{"en":"They're very different, though they did seem to get on well when they met.","cn":"他们大不相同，可是见面后好像还确实相处得不错。"}]},"thrive":{"oxford":{"phon":"θraɪv","pos":"verb","senses":[{"en":"to become, and continue to be, successful, strong, healthy, etc.","cn":"兴旺发达；繁荣；蓬勃发展；旺盛；茁壮成长","ex":{"en":"New businesses thrive in this area.","cn":"新企业在这一地区蓬勃发展。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"欣欣向荣;茁壮成长;兴旺发达","en":"If someone or something thrives, they do well and are successful, healthy, or strong.","ex":{"en":"Today his company continues to thrive","cn":"今天，他的公司继续蓬勃发展。"}},{"pos":"VERB 动词","cn":"(尤指在别人觉得困难的时候)以…为乐，可以出色应对","en":"If you say that someone thrives on a particular situation, you mean that they enjoy it or that they can deal with it very well, especially when other people find it unpleasant or difficult.","ex":{"en":"Many people thrive on a stressful lifestyle","cn":"有许多人喜欢充满压力的生活方式。"}}]},"media":{"uk":"media/uk/thrive__gb_1.mp3","us":"media/us/thrive__us_1.mp3"},"examples":[{"en":"These animals rarely thrive in captivity.","cn":"这些动物栏养起来很少会肥壮。"},{"en":"New businesses thrive in this area.","cn":"新企业在这一地区蓬勃兴起。"}]},"thirsty":{"oxford":{"phon":"ˈθɜːsti","pos":"adjective","senses":[{"en":"needing or wanting to drink","cn":"渴的；口渴的","ex":{"en":"We were hungry and thirsty.","cn":"我们又饥又渴。"}},{"en":"having a strong desire for something","cn":"渴望；渴求；热望","ex":{"en":"He is thirsty for power.","cn":"他拼命想掌权。"}},{"en":"dry; in need of water","cn":"干旱的；缺水的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"渴的;干渴的","en":"If you are thirsty, you feel a need to drink something.","ex":{"en":"If a baby is thirsty, it feeds more often","cn":"婴儿要是渴了，就会吃得更频繁。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"渴望的;渴求的","en":"If you are thirsty for something, you have a strong desire for it.","ex":{"en":"People should understand how thirsty for revenge they are.","cn":"人们应该理解他们复仇的愿望是多么强烈。"}}]},"media":{"uk":"media/uk/thirsty__gb_1.mp3","us":"media/us/thirsty__us_1.mp3"},"examples":[{"en":"Digging is thirsty work (= makes you thirsty).","cn":"挖地是个使人口渴的活。"},{"en":"Paul drank thirstily.","cn":"保罗渴得拼命喝水。"}]},"theorist":{"media":{"uk":"media/uk/theorist__gb_1.mp3","us":"media/us/theorist__us_1.mp3"},"oxford":{"phon":"ˈθɪərɪst","pos":"noun","senses":[{"en":"a person who develops ideas and principles about a particular subject in order to explain why things happen or exist","cn":"理论家；理论工作者","ex":{"en":"a political theorist","cn":"政治理论家"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"理论家;提出理论的人","en":"A theorist is someone who develops an abstract idea or set of ideas about a particular subject in order to explain it.","ex":{"en":"...theorists unaligned with any particular doctrine.","cn":"不附和任何教条的理论家"}}]},"examples":[{"en":"a leading economic theorist","cn":"一流的经济学理论家"}]},"thoughtfully":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is kind tries to help people and make them happy or comfortable, and shows that they care about them","cn":""},{"en":"friendly and kind. Nice is very common in everyday spoken English and is often used instead of kind","cn":""}]},"examples":[{"en":"Paul is very thoughtful.","cn":"","src":"ld"},{"en":"It was really thoughtful of you to remember my birthday.","cn":"","src":"ld"}],"media":{"uk":"media/uk/thoughtfully__gb_1.mp3","us":"media/us/thoughtfully__us_1.mp3"},"oxford":{"phon":"ˈθɔːtfəli","pos":"adverb","senses":[{"en":"in a quiet way, because you are thinking","cn":"沉思的；深思的；思考的","ex":{"en":"Martin looked at her thoughtfully.","cn":"马丁若有所思地看着她。"}},{"en":"in a way that shows that you think about and care for other people","cn":"体贴的；关心别人的；关切的","lab":"approving","ex":{"en":"She used the towel thoughtfully provided by her host.","cn":"她用了主人用心为她准备的毛巾。"}},{"en":"in a way that shows signs of careful thought","cn":"缜密思考过的；深思熟虑的","ex":{"en":"an elegant and thoughtfully designed building","cn":"一座优雅且精心设计的建筑"}}]}},"thanks":{"media":{"uk":"media/uk/thanks__gb_1.mp3","us":"media/us/thanks__us_1.mp3"},"oxford":{"phon":"θæŋks","pos":"exclamation","senses":[{"en":"used to show that you are grateful to somebody for something they have done","cn":"（表示感谢）谢谢，多谢","ex":{"en":"‘How are you?’ ‘Fine, thanks (= thanks for asking).’","cn":"“你好吗？”“挺好的，谢谢。”"}},{"en":"a polite way of accepting something that somebody has offered you","cn":"（接受好意）好的，谢谢","ex":{"en":"‘Would you like a coffee?’ ‘Oh, thanks.’","cn":"“来杯咖啡好吗？”“好的，谢谢。”"}},{"en":"a polite way of refusing something that somebody has offered you","cn":"（婉言谢绝）不用了，谢谢","ex":{"en":"‘Would you like some more?’ ‘No thanks.’","cn":"“再要一点儿吗？”“不要了，谢谢。”"}},{"en":"words or actions that show that you are grateful to somebody for something","cn":"感谢；感激；谢意","ex":{"en":"How can I ever express my thanks to you for all you've done?","cn":"对你所做的一切，我怎么才能表达谢意？"},"pos":"noun"}]},"examples":[{"en":"We managed to get it finished in the end — no thanks to him (= he didn't help).","cn":"我们终于把这件事完成了，但这没有他的什么功劳。"},{"en":"‘I'm afraid I've finished all the milk.’ ‘Well, thanks a lot!’ “","cn":"对不起，我把牛奶都喝光了。” “哦，多谢了！”"}],"base":"thank"},"thorough":{"oxford":{"phon":"ˈθʌrə","pos":"adjective","senses":[{"en":"done completely; with great attention to detail","cn":"彻底的；完全的；深入的；细致的","ex":{"en":"a thorough knowledge of the subject","cn":"对这一学科的透彻了解"}},{"en":"doing things very carefully and with great attention to detail","cn":"仔细周到；工作缜密","g":"[not usually before noun]","ex":{"en":"She's very thorough and conscientious.","cn":"她勤勤恳恳，一丝不苟。"}},{"en":"used to emphasize how bad or annoying somebody/something is","cn":"十足的；彻头彻尾的；完完全全的","lab":"British English, informal，，","ex":{"en":"Everything was in a thorough mess.","cn":"一切都是乱七八糟的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为、活动)详细的，全面的，彻底的","en":"A thorough action or activity is one that is done very carefully and in a detailed way so that nothing is forgotten.","ex":{"en":"We are making a thorough investigation","cn":"我们正在进行彻底调查。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)仔细的，严谨的","en":"Someone who is thorough is always very careful in their work, so that nothing is forgotten.","ex":{"en":"Martin would be a good judge, I thought. He was calm and thorough","cn":"我想，马丁将会是个优秀的法官，他做事沉稳，头脑严谨。"}},{"pos":"ADJ 形容词","cn":"完全的，绝对的(用来强调程度)","en":"Thorough is used to emphasize the great degree or extent of something.","ex":{"en":"I was a thorough little academic snob","cn":"我那时是个目空一切、自以为是的小学术愤青。"}}]},"media":{"uk":"media/uk/thorough__gb_1.mp3","us":"media/us/thorough__us_1.mp3"},"examples":[{"en":"I was impressed by the thoroughness of the report.","cn":"那份报告全面深入，给我留下了深刻的印象。"},{"en":"The police carried out a thorough investigation.","cn":"警方展开了全面的调查。"}]},"threw":{"lemma":"throw","media":{"uk":"media/uk/threw__gb_1.mp3","us":"media/us/threw__us_1.mp3"}},"thermal":{"media":{"uk":"media/uk/thermal__gb_1.mp3","us":"media/us/thermal__us_1.mp3"},"oxford":{"phon":"ˈθɜːml","pos":"adjective","senses":[{"en":"connected with heat","cn":"热的；热量的","lab":"specialist","ex":{"en":"thermal energy","cn":"热能"}},{"en":"designed to keep you warm by preventing heat from escaping from the body","cn":"保暖的；防寒的","ex":{"en":"thermal underwear","cn":"保暖内衣裤"}},{"en":"in which the water has been naturally heated by the earth","cn":"温暖的；热的","ex":{"en":"thermal springs","cn":"温泉"}},{"en":"a rising current of warm air used, for example, by a glider to gain height","cn":"上升的热气流","g":"[countable]","pos":"noun"},{"en":"warm underwear that prevents heat from escaping from the body","cn":"保暖内衣裤","g":"[plural]","lab":"especially British English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"热的;由热引起的;温度变化引起的","en":"Thermal means relating to or caused by heat or by changes in temperature.","ex":{"en":"...thermal power stations.","cn":"热电厂"}},{"pos":"ADJ 形容词","cn":"(小溪、浴水)天然温热的","en":"Thermal streams or baths contain water which is naturally hot or warm.","ex":{"en":"Volcanic activity has created thermal springs and boiling mud pools.","cn":"火山活动产生了温泉和沸腾的泥浆池。"}},{"pos":"ADJ 形容词","cn":"(衣服)保暖的，御寒的","en":"Thermal clothes are specially designed to keep you warm in cold weather.","ex":{"en":"My feet were like blocks of ice despite the thermal socks","cn":"虽然穿了保暖袜子，我的双脚还是像冰块一样。"}},{"pos":"N-COUNT 可数名词","cn":"上升热气流","en":"A thermal is a movement of rising warm air.","ex":{"en":"Birds use thermals to lift them through the air.","cn":"鸟类利用上升热气流升入空中。"}}]},"examples":[{"en":"thermal underwear","cn":"保暖内衣裤"},{"en":"thermal energy","cn":"热能"}]},"thank":{"media":{"uk":"media/uk/thank__gb_1.mp3","us":"media/us/thank__us_1.mp3"},"oxford":{"phon":"θæŋk","pos":"verb","senses":[{"en":"to tell somebody that you are grateful for something","cn":"谢谢，感谢（某人）；（为某事）道谢","ex":{"en":"I must write and thank Mary for the present.","cn":"我得写信感谢玛丽送给我这份礼物。"}}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"谢谢您;谢谢;多谢","en":"You use thank you or, in more informal English, thanks to express your gratitude when someone does something for you or gives you what you want.","ex":{"en":"Thank you very much for your call","cn":"非常感谢您的来电。"}},{"pos":"CONVENTION 惯用语","cn":"谢谢你，多谢(用于有礼貌地接受或拒绝)","en":"You use thank you or, in more informal English, thanks to politely accept or refuse something that has just been offered to you.","ex":{"en":"'You'd like a cup as well, would you, Mr Secombe?' — 'Thank you, Jane, I'd love one.'","cn":"“塞科姆先生，你也想来一杯吧？”——“谢谢，简，我确实想来一杯。”"}},{"pos":"CONVENTION 惯用语","cn":"谢谢你，多谢(尤用于礼貌地感谢对方的回答或所说的令人开心的话)","en":"You use thank you or, in more informal English, thanks to politely acknowledge what someone has said to you, especially when they have answered your question or said something nice to you.","ex":{"en":"The policeman smiled at her. 'Pretty dog.' — 'Oh well, thank you.'","cn":"警察冲她笑了笑，“这狗真漂亮。”——“哦，谢谢。”"}},{"pos":"CONVENTION 惯用语","cn":"谢谢，非常感谢(用于坚决回绝别人的帮助或表示不喜欢别人的举动)","en":"You use thank you or thank you very much in order to say firmly that you do not want someone's help or to tell them that you do not like the way that they are behaving towards you.","ex":{"en":"I can stir my own tea, thank you","cn":"我的茶我自己会搅，谢谢。"}},{"pos":"VERB 动词","cn":"向…表示谢意;感谢","en":"When you thank someone for something, you express your gratitude to them for it.","ex":{"en":"I thanked them for their long and loyal service","cn":"我感谢他们长期以来忠诚的效力。"}},{"pos":"N-PLURAL 复数名词","cn":"感谢;谢意;感激","en":"When you express your thanks to someone, you express your gratitude to them for something.","ex":{"en":"They accepted their certificates with words of thanks.","cn":"他们一边道谢，一边接过证书。"}},{"pos":"PHRASE 短语","cn":"感谢(上帝);感恩","en":"When people give thanks, they thank God for something good that has happened.","ex":{"en":"We give thanks for this food.","cn":"感谢上帝赐给我们食物。"}},{"pos":"PHRASE 短语","cn":"谢天谢地;感谢上帝","en":"You say 'Thank God', 'Thank Goodness', or 'Thank heavens' when you are very relieved about something.","ex":{"en":"I was wrong, thank God","cn":"原来我错了，感谢上帝。"}},{"pos":"PHRASE 短语","cn":"要向…表示感谢;多亏","en":"If you say that you have someone to thank for something, you mean that you are grateful to them because they caused it to happen.","ex":{"en":"I have her to thank for my life","cn":"我这条命多亏了她。"}},{"pos":"PHRASE 短语","cn":"幸亏;归因于","en":"If you say that something happens thanks to a particular person or thing, you mean that they are responsible for it happening or caused it to happen.","ex":{"en":"It is thanks to this committee that many new sponsors have come forward","cn":"又有许多赞助商找上门来，这要归功于这个委员会。"}},{"pos":"PHRASE 短语","cn":"并非由于…才(发生);并不归功于","en":"If you say that something happens no thanks to a particular person or thing, you mean that they did not help it to happen, or that it happened in spite of them.","ex":{"en":"It is no thanks to the Government that net assets did rise.","cn":"净资产的确增长了，但这与政府无关。"}},{"pos":"","cn":"","en":"to thank your lucky stars→see: ;"}]},"examples":[{"en":"‘Thank goodness for that!’ she said with a sigh of relief. “","cn":"这可要谢天谢地！”她宽慰地舒了一口气。"},{"en":"I must write and thank Mary for the present.","cn":"我得写信感谢玛丽送给我这份礼物。"}]},"thirty":{"media":{"uk":"media/uk/thirty__gb_1.mp3","us":"media/us/thirty__us_1.mp3"},"oxford":{"phon":"ˈθɜːti","pos":"","senses":[{"en":"30","cn":"三十"},{"en":"numbers, years or temperatures from 30 to 39","cn":"三十几；三十年代","g":"[plural]"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 30","en":"Thirty is the number 30."},{"pos":"N-PLURAL 复数名词","cn":"三十多，三十几(指 30 至 39 之间的数字)","en":"When you talk about the thirties, you are referring to numbers between 30 and 39. For example, if you are in your thirties, you are aged between 30 and 39. If the temperature is in the thirties, the temperature is between 30 and 39 degrees.","ex":{"en":"Mozart clearly enjoyed good health throughout his twenties and early thirties.","cn":"显然，莫扎特在二十几岁到三十刚出头时，身体非常好。"}},{"pos":"N-PLURAL 复数名词","cn":"三十年代(指 1930 年至 1939 年)","en":"The thirties is the decade between 1930 and 1939.","ex":{"en":"She became quite a notable director in the thirties and forties.","cn":"她在三四十年代成了一位名导演。"}}]},"examples":[{"en":"In the thirties, air travel really began to take off.","cn":"在30年代﹐乘飞机旅行迅速流行了起来。"},{"en":"The family sold the house in the early thirties. 30","cn":"年代初期﹐这家人把房子卖了。"}]},"the":{"media":{"uk":"media/uk/the__gb_1.mp3","us":"media/us/the__us_1.mp3"},"oxford":{"phon":"ðə","pos":"definite article","senses":[{"en":"used to refer to somebody/something that has already been mentioned or is easily understood","cn":"（指已提到或易领会到的人或事物）","ex":{"en":"There were three questions. The first two were relatively easy but the third one was hard.","cn":"有三个问题。头两个相对容易，第三个困难。"}},{"en":"used to refer to somebody/something that is the only, normal or obvious one of their kind","cn":"（指独一无二的、正常的或不言而喻的人或事物）","ex":{"en":"the Mona Lisa","cn":"《蒙娜丽莎》"}},{"en":"used when explaining which person or thing you mean","cn":"（解说时用）","ex":{"en":"the house at the end of the street","cn":"街尽头的房子"}},{"en":"used to refer to a thing in general rather than a particular example","cn":"（用以泛指）","ex":{"en":"He taught himself to play the violin.","cn":"他自学拉小提琴。"}},{"en":"used with adjectives to refer to a thing or a group of people described by the adjective","cn":"（与形容词连用，指事物或统称的人）","ex":{"en":"With him, you should always expect the unexpected.","cn":"在他身上你应随时料到有意想不到的事情发生。"}},{"en":"used before the plural of somebody’s last name to refer to a whole family or a married couple","cn":"（用于姓氏的复数形式前，指家庭或夫妇）","ex":{"en":"Don't forget to invite the Jordans.","cn":"别忘了邀请乔丹一家。"}},{"en":"used with a unit of measurement to mean ‘every’","cn":"（与计量单位连用）每，一","ex":{"en":"My car does forty miles to the gallon.","cn":"我的车每加仑汽油跑四十英里。"}},{"en":"enough of something for a particular purpose","cn":"（指特定用途的事物）足够，恰好","ex":{"en":"I wanted it but I didn't have the money.","cn":"我想买那东西，但钱不够。"}},{"en":"used with a unit of time to mean ‘the present’","cn":"（与时间单位连用）当前的，本，此","ex":{"en":"Why not have the dish of the day?","cn":"何不试一下今天的特色菜？"}},{"en":"used, stressing the, to show that the person or thing referred to is famous or important","cn":"（重读，表示所指的为知名或重要的人或事物）","ex":{"en":"Sheryl Crow? Not the Sheryl Crow?","cn":"雪瑞尔·克洛？莫不是大名鼎鼎的雪瑞尔·克洛？"}},{"en":"Times Higher Education","cn":"泰晤士高等教育","pos":""}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"(用于名词短语之前，指代已经提及或指明的人或物)","en":"You use the at the beginning of noun groups to refer to someone or something that you have already mentioned or identified.","ex":{"en":"A waiter came and hovered. John caught my look and we both got up and, ignoring the waiter, made our way to the buffet","cn":"一个侍者走了过来，候在附近。约翰领会了我的眼神，我们两个都站了起来，没有理睬那个侍者，朝自助餐台走去。"}},{"pos":"DET 限定词","cn":"(当名词后接 of 短语或表明身份的从句时，该名词前用the)","en":"You use the at the beginning of a noun group when the first noun is followed by an 'of' phrase or a clause which identifies the person or thing.","ex":{"en":"There has been a slight increase in the consumption of meat","cn":"肉类消费量略有增长。"}},{"pos":"DET 限定词","cn":"(用于某些表示人们共有经历的名词前)","en":"You use the in front of some nouns that refer to something in our general experience of the world.","ex":{"en":"It's always hard to speculate about the future","cn":"未来一向很难预测。"}},{"pos":"DET 限定词","cn":"(用于和日常生活相关的人、物、服务、机构的名词前)","en":"You use the in front of nouns that refer to people, things, services, or institutions that are associated with everyday life.","ex":{"en":"The doctor's on his way","cn":"医生正在路上。"}},{"pos":"DET 限定词","cn":"(用于代替所有格限定词，尤在谈论身体某一部分或家庭某一成员时)","en":"You use the instead of a possessive determiner, especially when you are talking about a part of someone's body or a member of their family.","ex":{"en":"'How's the family?' — 'Just fine, thank you.'","cn":"“家里人都好吧？”——“都好，谢谢。”"}},{"pos":"DET 限定词","cn":"(用于单数名词前，表示一类人或事物)","en":"You use the in front of a singular noun when you want to make a general statement about things or people of that type.","ex":{"en":"An area in which the computer has made considerable strides in recent years is in playing chess","cn":"近年来，计算机应用取得长足进步的一个领域是国际象棋。"}},{"pos":"DET 限定词","cn":"(谈论是否会演奏乐器时，用于乐器名称前)","en":"You use the with the name of a musical instrument when you are talking about someone's ability to play the instrument.","ex":{"en":"Did you play the piano as a child?","cn":"你小时候弹过钢琴吗？"}},{"pos":"DET 限定词","cn":"(用于表示国籍的形容词和名词以谈论一国全体国民)","en":"You use the with nationality adjectives and nouns to talk about the people who live in a country.","ex":{"en":"The Japanese, Americans, and even the French and Germans, judge economic policies by results.","cn":"日本人、美国人，甚至法国人和德国人，都依据结果来评判经济政策的好坏。"}},{"pos":"DET 限定词","cn":"(与 rich, poor, old, unemployed 等形容词连用，表示某一类人)","en":"You use the with words such as 'rich', 'poor', 'old', or 'unemployed' to refer to all people of a particular type.","ex":{"en":"Conditions for the poor in Los Angeles have not improved.","cn":"洛杉矶穷人的境况仍未得到改善。"}},{"pos":"DET 限定词","cn":"(用于姓氏的复数前，表示一家人或夫妻)","en":"If you want to refer to a whole family or to a married couple, you can make their surname into a plural and use the in front of it.","ex":{"en":"...a 400 acre farm owned by the Allens","cn":"艾伦家的一个面积为 400 英亩的农场"}},{"pos":"DET 限定词","cn":"(用于形容词前，表示其修饰的某个事物)","en":"You use the in front of an adjective when you are referring to a particular thing that is described by that adjective.","ex":{"en":"He knows he's wishing for the impossible","cn":"他清楚他在期盼一件不可能发生的事。"}},{"pos":"DET 限定词","cn":"(表示拥有为某一特定目的所需的足够的某物)","en":"You use the to indicate that you have enough of the thing mentioned for a particular purpose.","ex":{"en":"She may not have the money to maintain or restore her property","cn":"她可能没有足够的钱来维护或修葺她的房产。"}},{"pos":"DET 限定词","cn":"(与某些称号、地名和其他名称连用)","en":"You use the with some titles, place names, and other names.","ex":{"en":"The company was alleged to have leaked the news to the Daily Mail.","cn":"据称，那家公司将消息透露给了《每日邮报》。"}},{"pos":"DET 限定词","cn":"(用于序数词前)","en":"You use the in front of numbers such as first, second, and third.","ex":{"en":"The meeting should take place on the fifth of May","cn":"会议将会于 5 月 5 日举行。"}},{"pos":"DET 限定词","cn":"(用于表示年代的数字前)","en":"You use the in front of numbers when they refer to decades.","ex":{"en":"It's sometimes hard to imagine how bad things were in the thirties.","cn":"有时很难想象 30 年代的日子有多么困难。"}},{"pos":"DET 限定词","cn":"(用于形容词和副词的最高级前)","en":"You use the in front of superlative adjectives and adverbs.","ex":{"en":"Brisk daily walks are still the best exercise for young and old alike","cn":"不管年轻人还是老人，每天快步行走仍是最好的锻炼方式。"}},{"pos":"DET 限定词","cn":"越…越…(用于两个比较级前，表示其中一个随另一个发生量或质的变化)","en":"You use the in front of each of two comparative adjectives or adverbs when you are describing how one amount or quality changes in relation to another.","ex":{"en":"The longer you have been in shape in the past, the quicker you will regain fitness in future","cn":"过去健美身形保持的时间越长，将来身材恢复得就越快。"}},{"pos":"DET 限定词","cn":"每，一(表示速度、价格、度量等)","en":"When you express rates, prices, and measurements, you can use the to say how many units apply to each of the items being measured.","ex":{"en":"New Japanese cars averaged 13 km to the litre in 1981","cn":"1981 年，新型的日产汽车平均每升汽油能跑 13 千米。"}},{"pos":"DET 限定词","cn":"(表示某人或某物是同类中最有名、最重要或最好的。口语中 the 要重读；书面语中常加下划线或用大写、斜体)","en":"You use the to indicate that something or someone is the most famous, important, or best thing of its kind. In spoken English, you put more stress on it, and in written English, you often underline it or write it in capitals or italics.","ex":{"en":"Camden Market is the place to be on a Saturday or Sunday","cn":"卡姆登市场是周末的最佳去处。"}}]},"examples":[{"en":"There was an accident here yesterday. A car hit a tree and the driver was killed.","cn":"昨天这里发生了一起事故。一辆小轿车撞到树上，驾车的人死了。"},{"en":"Sheryl Crow? Not ˈthe Sheryl Crow?","cn":"谢里尔 · 克罗？莫不是大名鼎鼎的谢里尔 · 克罗？"}]},"thus":{"media":{"uk":"media/uk/thus__gb_1.mp3","us":"media/us/thus__us_1.mp3"},"oxford":{"phon":"ðʌs","pos":"adverb","senses":[{"en":"in this way; like this","cn":"以此方式；如此；这样","ex":{"en":"Many scholars have argued thus.","cn":"许多学者都这样论证过。"}},{"en":"as a result of something just mentioned","cn":"因此；从而；所以","ex":{"en":"He is the eldest son and thus heir to the title.","cn":"他是长子，因此是这个封号的继承人。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"所以;因此","en":"You use thus to show that what you are about to mention is the result or consequence of something else that you have just mentioned.","ex":{"en":"Neither of them thought of turning on the lunch-time news. Thus Caroline didn't hear of John's death until Peter telephoned","cn":"两个人谁也没有想到打开电视看午间新闻，所以直到彼得打来电话，卡罗琳才得知约翰的死讯。"}},{"pos":"ADV 副词","cn":"就像这样;以这种方式","en":"If you say that something is thus or happens thus you mean that it is, or happens, as you have just described or as you are just about to describe.","ex":{"en":"Joanna was pouring the drink. While she was thus engaged, Charles sat on one of the bar-stools","cn":"乔安娜正在倒酒。就在她正忙的当儿，查尔斯坐在了一张酒吧凳子上。"}},{"pos":"","cn":"","en":"thus far→see: ;"}]},"examples":[{"en":"The universities have expanded, thus allowing many more people the chance of higher education.","cn":"大学扩招了，这样就使更多人能有机会接受高等教育。"},{"en":"We do not own the building. Thus, it would be impossible for us to make any major changes to it.","cn":"我们不是这栋楼房的房主，因此不能对它进行大改动。"}]},"then":{"media":{"uk":"media/uk/then__gb_1.mp3","us":"media/us/then__us_1.mp3"},"oxford":{"phon":"ðen","pos":"adverb","senses":[{"en":"used to refer to a particular time in the past or future","cn":"（指过去）当时，那时；（指将来）到那时，届时","ex":{"en":"Life was harder then because neither of us had a job.","cn":"那时生活比较艰苦，因为我俩都没有工作。"}},{"en":"used to introduce the next item in a series of actions, events, instructions, etc.","cn":"然后；接着；其后；后来","ex":{"en":"He ate a cookie, then another and then another.","cn":"他吃了一块饼干，然后又吃了一块，然后又吃了一块。"}},{"en":"used to show the logical result of a particular statement or situation","cn":"那么；因此；既然如此","ex":{"en":"If you miss that train then you'll have to get a taxi.","cn":"如果你错过那趟火车，那就得坐出租车。"}},{"en":"used to introduce additional information","cn":"另外；还有；再者；而且","ex":{"en":"She's been very busy at work and then there was all that trouble with her son.","cn":"她工作一直很忙，另外还有儿子的一大堆麻烦事。"}},{"en":"used to introduce a summary of something that has just been said","cn":"总之","lab":"formal","ex":{"en":"These, then, are the main areas of concern.","cn":"总之，这些是人们主要关注的方面。"}},{"en":"used to show the beginning or end of a conversation, statement, etc.","cn":"（表示交谈、陈述等的开始或结束）那么","ex":{"en":"Right then, where do you want the table to go?","cn":"那好吧，你要把桌子放在哪里呢？"}},{"en":"used to describe somebody who had a particular title, job, etc. at the time in the past that is being discussed","cn":"当时（任职等）的","ex":{"en":"That decision was taken by the then president.","cn":"那个决定是由当时的总统作出的。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"当时;那时;届时;到时候","en":"Then means at a particular time in the past or in the future.","ex":{"en":"He wanted to have a source of income after his retirement; until then, he wouldn't require additional money","cn":"他想退休后有份收入;在那以前，他并不需要额外的钱。"}},{"pos":"ADJ 形容词","cn":"当时的;那时的","en":"Then is used when you refer to something which was true at a particular time in the past but is not true now.","ex":{"en":"...the Race Relations Act of 1976 (enacted by the then Labour Government)","cn":"1976 年的《种族关系法》(由当时的工党政府颁布施行)"}},{"pos":"ADV 副词","cn":"然后;之后;接着","en":"You use then to say that one thing happens after another, or is after another on a list.","ex":{"en":"Add the oil and then the scallops to the pan, leaving a little space for the garlic","cn":"先在锅里放油，然后放入扇贝，留点地方搁蒜。"}},{"pos":"ADV 副词","cn":"(口语中)那么，因此","en":"You use then in conversation to indicate that what you are about to say follows logically in some way from what has just been said or implied.","ex":{"en":"'I wasn't a very good scholar at school.' — 'What did you like doing best then?'","cn":"“我在学校时成绩不大好。”——“那么你当时最喜欢做什么呢？”"}},{"pos":"ADV 副词","cn":"(用于话题、谈话的结尾)","en":"You use then at the end of a topic or at the end of a conversation.","ex":{"en":"'I can meet you after work. Six o'clock?'— 'Fine.' — 'Six o'clock, then?'","cn":"“我下班后可以和你碰面。6 点可以吗？”——“行啊。”——“那就定 6 点啦？”"}},{"pos":"ADV 副词","cn":"(和 now，well，okay 等连用，引出新话题或新观点)","en":"You use then with words like 'now', 'well', and 'okay', to introduce a new topic or a new point of view.","ex":{"en":"Now then, you say you walk on the fields out the back?","cn":"那么，你说你在后面的田地里散步？"}},{"pos":"ADV 副词","cn":"也就是说，总之(引出总结或结论)","en":"You use then to introduce a summary of what you have said or the conclusions that you are drawing from it.","ex":{"en":"This, then, was the music that appeared to dominate the world of serious concert music in the mid-1960s","cn":"这就是 20 世纪 60 年代中期严肃的管弦乐中的主流音乐。"}},{"pos":"ADV 副词","cn":"那么，则(引导if开头的句子的第二部分，第一部分描述可能的情况，第二部分引入结果)","en":"You use then to introduce the second part of a sentence which begins with 'if'. The first part of the sentence describes a possible situation, and then introduces the result of the situation.","ex":{"en":"If the answer is 'yes', then we must decide on an appropriate course of action","cn":"如果答案是肯定的，那么我们必须商定合适的行动方案。"}},{"pos":"ADV 副词","cn":"毕竟，话说回来，而且(用于句首，或用于 and，but 之后引出对之前所说话的评论或补充)","en":"You use then at the beginning of a sentence or after 'and' or 'but' to introduce a comment or an extra piece of information to what you have already said.","ex":{"en":"We have to do quite a bit of reading, and then we have our ongoing work which would be an essay","cn":"我们要进行大量阅读，而且手头有一篇论文要写。"}},{"pos":"","cn":"","en":"now and then→see: ; there and then→see: ;"}]},"examples":[{"en":"There are Indian, Chinese, Mexican, Thai restaurants … and then some!","cn":"有印度、中国、墨西哥、泰国餐馆 … ，而且还有很多其他国家的餐馆！"},{"en":"‘So you might accept their offer?’ ‘Yes, then again I might not.’ “","cn":"这么说你也许会接受他们的提议了？” “是的，不过也可能不接受。”"}]},"they'd":{"media":{"uk":"media/uk/they_d_1_gb_1.mp3","us":"media/us/they_d_1_us_1.mp3"},"oxford":{"phon":"ðeɪd","pos":"short form","senses":[{"en":"they had","cn":""},{"en":"they would","cn":""}]},"collins":{"senses":[{"pos":"","cn":"(尤当had为助动词时，they had的一种口语形式)","en":"They'd is a spoken form of 'they had', especially when 'had' is an auxiliary verb.","ex":{"en":"They'd both lived in this road all their lives.","cn":"他们俩在这条路上生活了一辈子。"}},{"pos":"","cn":"(they would 的一种口语形式)","en":"They'd is a spoken form of 'they would'.","ex":{"en":"He agreed that they'd visit her after they stopped at Jan's for coffee.","cn":"他答应他们在简的家里喝完咖啡后就去看她。"}}]},"examples":[{"en":"If only they’d been there.","cn":"他们当时要在那儿就好了。"},{"en":"It’s a pity my parents didn’t come – they’d have enjoyed it.","cn":"很遗憾﹐我的父母没有来——要不然他们也会很开心的。"}]},"therefore":{"media":{"uk":"media/uk/therefore__gb_1.mp3","us":"media/us/therefore__us_1.mp3"},"oxford":{"phon":"ˈðeəfɔː(r)","pos":"adverb","senses":[{"en":"used to introduce the logical result of something that has just been mentioned","cn":"因此；所以；因而","ex":{"en":"He's only 17 and therefore not eligible to vote.","cn":"他只有 17 岁，因此没有投票选举的资格。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"所以;因此;因而","en":"You use therefore to introduce a logical result or conclusion.","ex":{"en":"Muscle cells need lots of fuel and therefore burn lots of calories","cn":"肌肉细胞需要很多能量，所以会燃烧大量卡路里。"}}]},"examples":[{"en":"There is still much to discuss. We shall, therefore, return to this item at our next meeting.","cn":"要讨论的问题还有很多。所以，我们将在下次会议上再讨论这项议题。"},{"en":"He's only 17 and therefore not eligible to vote.","cn":"他只有 17 岁，因此没有投票选举的资格。"}]},"they":{"media":{"uk":"media/uk/they__gb_1.mp3","us":"media/us/they__us_1.mp3"},"oxford":{"phon":"ðeɪ","pos":"pronoun","senses":[{"en":"people, animals or things that have already been mentioned or are easily identified","cn":"他们；她们；它们","ex":{"en":"‘Where are John and Liz?’ ‘They went for a walk.’","cn":"“约翰和利兹在哪儿？”“他们去散步了。”"}},{"en":"used instead of he or she to refer to a person whose sex is not mentioned or not known","cn":"（用以代替 he 或 she，指性别不详的人）","lab":"British English","ex":{"en":"If anyone arrives late they'll have to wait outside.","cn":"谁要是迟到，他就得在外面等着。"}},{"en":"people in general","cn":"（泛指）人们，人人，众人","ex":{"en":"The rest, as they say, is history.","cn":"其余的就尽人皆知，不须赘述了。"}},{"en":"people in authority or experts","cn":"权威人士；上面（指负责人）；专家","ex":{"en":"They cut my water off.","cn":"管事的把水给我掐了。"}}]},"collins":{"senses":[{"pos":"PRON-PLURAL 复数型代词","cn":"他们;她们;它们","en":"You use they to refer to a group of people, animals, or things.","ex":{"en":"The two men were far more alike than they would ever admit","cn":"那两个人也许不承认，可他们非常相像。"}},{"pos":"PRON-PLURAL 复数型代词","cn":"(用以代替he or she，而不指明是男是女;有人认为这种用法不对)","en":"You use they instead of 'he or she' to refer to a person without saying whether that person is a man or a woman. Some people think this use is incorrect.","ex":{"en":"The teacher is not responsible for the student's success or failure. They are only there to help the student learn","cn":"教师对学生的成败并不负有责任，其职责只是帮助学生学习。"}},{"pos":"PRON-PLURAL 复数型代词","cn":"(用于 they say，they call it 等表达中表示泛指)他们","en":"You use they in expressions such as 'they say' or 'they call it' to refer to people in general when you are making general statements about what people say, think, or do.","ex":{"en":"They say there's plenty of opportunities out there, you just have to look carefully and you'll find them","cn":"他们说，那里机会多的是，你只要仔细找就能发现。"}}]},"examples":[{"en":"‘Where are John and Liz?’ ‘They went for a walk.’ “","cn":"约翰和利兹在哪儿？” “他们去散步了。”"},{"en":"They now say that red wine is good for you.","cn":"现在专家说喝红葡萄酒对人有好处。"}]},"through":{"media":{"uk":"media/uk/through__gb_1.mp3","us":"media/us/through__us_1.mp3"},"oxford":{"phon":"θruː","pos":"preposition","senses":[{"en":"from one end or side of something/somebody to the other","cn":"从…一端至另一端；穿过；贯穿","ex":{"en":"The burglar got in through the window.","cn":"盗贼是从窗户进来的。"}},{"en":"to see, hear, etc. something from the other side of an object or a substance","cn":"透过…看到；隔着…听到","ex":{"en":"I couldn't hear their conversation through the wall.","cn":"我隔墙听不到他们的交谈。"}},{"en":"from the beginning to the end of an activity, a situation or a period of time","cn":"自始至终；从头到尾","ex":{"en":"The children are too young to sit through a concert.","cn":"这些孩子年纪太小，音乐会没完就坐不住了。"}},{"en":"past a barrier, stage or test","cn":"通过（障碍、阶段或测试）；穿过","ex":{"en":"Go through this gate, and you'll see the house on your left.","cn":"你穿过这道大门，就看到左面的房子了。"}},{"en":"until, and including","cn":"直至，一直到（所指时间包括在内）","lab":"informal","ex":{"en":"We'll be in New York Tuesday through Friday.","cn":"我们从星期二到星期五将一直待在纽约。"}},{"en":"by means of; because of","cn":"以；凭借；因为；由于","ex":{"en":"You can only achieve success through hard work.","cn":"你得孜孜不倦方能成功。"}},{"en":"from one end or side of something to the other","cn":"从一端到另一端；通过","ex":{"en":"Put the coffee in the filter and let the water run through.","cn":"把咖啡放入过滤器里让水流过。"},"pos":"adverb"},{"en":"from the beginning to the end of a thing or period of time","cn":"自始至终；从头至尾","ex":{"en":"Don't tell me how it ends—I haven't read it all the way through yet.","cn":"先别告诉我结尾，我还没有读完呢。"},"pos":"adverb"},{"en":"past a barrier, stage or test","cn":"通过（障碍、阶段或测试）；穿过","ex":{"en":"The lights were red but he drove straight through.","cn":"红灯亮着，但他开车闯了过去。"},"pos":"adverb"},{"en":"travelling through a place without stopping or without people having to get off one train and onto another","cn":"直达；径直","ex":{"en":"‘Did you stop in Oxford on the way?’ ‘No, we drove straight through.’","cn":"“你路经牛津时停车了吗？”“没有，我一直开过来的。”"},"pos":"adverb"},{"en":"connected by phone","cn":"（电话）接通着","ex":{"en":"Ask to be put through to me personally.","cn":"请接线员把电话直接接给我本人。"},"pos":"adverb"},{"en":"used after an adjective to mean ‘completely’","cn":"（用于形容词后）完全，彻底","ex":{"en":"We got wet through.","cn":"我们浑身上下都湿透了。"},"pos":"adverb"},{"en":"through traffic travels from one side of a place to the other without stopping","cn":"（交通旅行）直达的，直通的，全程的","g":"[only before noun]","pos":"adjective"},{"en":"a through train takes you to the final place you want to get to and you do not have to get off and get on another train","cn":"（火车）直达的，直通的","g":"[only before noun]","pos":"adjective"},{"en":"a through road or route is open at both ends and allows traffic to travel from one end to the other","cn":"（道路或路线）直通的","g":"[only before noun]","ex":{"en":"The village lies on a busy through road.","cn":"那村庄坐落在一条繁忙的直达公路上。"},"pos":"adjective"},{"en":"used to show that you have finished using something or have ended a relationship with somebody","cn":"（使用）完成，结束；（关系）了结，断绝","g":"[not before noun]","lab":"especially North American English","ex":{"en":"Are you through with that newspaper?","cn":"你看完那份报纸了吗？"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"穿过,通过(洞、口子、管道等);从…的一端到另一端","en":"To move through something such as a hole, opening, or pipe means to move directly from one side or end of it to the other.","ex":{"en":"The theatre was evacuated when rain poured through the roof at the Liverpool Playhouse","cn":"雨从利物浦剧院的屋顶倾泻而入，剧院的观众被疏散了。"}},{"pos":"PREP 介词","cn":"(切)开;(割)断;(凿)穿","en":"To cut through something means to cut it in two pieces or to make a hole in it.","ex":{"en":"Use a proper fish knife and fork if possible as they are designed to cut through the flesh but not the bones","cn":"如果可能的话，选用正规的吃鱼刀叉，因为它们是专门设计来切开鱼肉而又不会切断鱼骨的。"}},{"pos":"PREP 介词","cn":"穿过，通过(城市、地区、国家);遍及","en":"To go through a town, area, or country means to travel across it or in it.","ex":{"en":"Go up to Ramsgate, cross into France, go through Andorra and into Spain.","cn":"北行至拉姆斯盖特，然后横跨法国，穿过安多拉，进入西班牙。"}},{"pos":"PREP 介词","cn":"在…之间;在…之中","en":"If you move through a group of things or a mass of something, it is on either side of you or all around you.","ex":{"en":"We made our way through the crowd to the river","cn":"我们挤过人群，来到河边。"}},{"pos":"PREP 介词","cn":"跨越(障碍等)","en":"To get through a barrier or obstacle means to get from one side of it to the other.","ex":{"en":"Allow twenty-five minutes to get through Passport Control and Customs","cn":"留出 25 分钟过护照检查处和海关。"}},{"pos":"PREP 介词","cn":"闯过，硬闯(红灯)","en":"If a driver goes through a red light, they keep driving even though they should stop.","ex":{"en":"He was killed at a road junction by a van driver who went through a red light","cn":"他在交叉路口被一辆闯红灯的小货车撞死了。"}},{"pos":"PREP 介词","cn":"穿过，通过(某物内部)","en":"If something goes into an object and comes out of the other side, you can say that it passes through the object.","ex":{"en":"The ends of the net pass through a wooden bar at each end","cn":"网的两端各穿过一根木棒。"}},{"pos":"PREP 介词","cn":"通过，经过(系统)","en":"To go through a system means to move around it or to pass from one end of it to the other.","ex":{"en":"...electric currents travelling through copper wires","cn":"通过铜导线的电流"}},{"pos":"PREP 介词","cn":"透过，通过(…感知)","en":"If you see, hear, or feel something through a particular thing, that thing is between you and the thing you can see, hear, or feel.","ex":{"en":"Alice gazed pensively through the wet glass","cn":"艾丽斯透过湿漉漉的玻璃神情忧郁地凝视着窗外。"}},{"pos":"PREP 介词","cn":"(感觉、态度、品质)遍布，遍及，贯穿","en":"If something such as a feeling, attitude, or quality, happens through an area, organization, or a person's body, it happens everywhere in it or affects all of it.","ex":{"en":"An atmosphere of anticipation vibrated through the crowd","cn":"期待的心情在人群中弥漫开来。"}},{"pos":"PREP 介词","cn":"自始至终;从头到尾","en":"If something happens or exists through a period of time, it happens or exists from the beginning until the end.","ex":{"en":"We're playing in New Zealand, Australia and Japan through November","cn":"整个 11 月，我们都在新西兰、澳大利亚和日本巡回演出。"}},{"pos":"PREP 介词","cn":"直至;一直到","en":"If something happens from a particular period of time through another, it starts at the first period and continues until the end of the second period.","ex":{"en":"...open Monday through Sunday from 7:00 am to 10:00 pm","cn":"开放时间：周一到周日，每天早晨 7: 00 到晚上 10: 00"}},{"pos":"PREP 介词","cn":"经历;度过","en":"If you go through a particular experience or event, you experience it, and if you behave in a particular way through it, you behave in that way while it is happening.","ex":{"en":"Men go through a change of life emotionally just like women.","cn":"男人和女人一样，也要在情绪上经历更年期。"}},{"pos":"ADJ 形容词","cn":"完成的;结束的;(与…)关系了结的","en":"If you are through with something or if it is through, you have finished doing it and will never do it again. If you are through with someone, you do not want to have anything to do with them again.","ex":{"en":"I'm through with the explaining","cn":"我不想再解释了。"}},{"pos":"PREP 介词","cn":"进行到一半/一直到底","en":"You use through in expressions such as half-way through and all the way through to indicate to what extent an action or task is completed.","ex":{"en":"A thirty-nine-year-old competitor collapsed half-way through the marathon and died shortly afterwards.","cn":"一名 39 岁的马拉松参赛者跑到一半时瘫倒在地，没过多久就死了。"}},{"pos":"PREP 介词","cn":"因为;由于","en":"If something happens because of something else, you can say that it happens through it.","ex":{"en":"They are understood to have retired through age or ill health","cn":"据知他们是因年龄或健康问题而退休。"}},{"pos":"PREP 介词","cn":"通过;凭借;依靠","en":"You use through when stating the means by which a particular thing is achieved.","ex":{"en":"Those who seek to grab power through violence deserve punishment","cn":"企图通过暴力夺权的人理应受到惩罚。"}},{"pos":"PREP 介词","cn":"经过;经由","en":"If you do something through someone else, they take the necessary action for you.","ex":{"en":"Do I need to go through my doctor or can I make an appointment direct?","cn":"我必须经过我的医生呢，还是可以直接预约？"}},{"pos":"ADV 副词","cn":"(提议、观点)获得通过，得到批准","en":"If something such as a proposal or idea goes through, it is accepted by people in authority and is made legal or official.","ex":{"en":"It is possible that the present Governor General will be made interim President, if the proposals go through","cn":"如果提案获得通过，现任总督可能被任命为临时总统。"}},{"pos":"PREP 介词","cn":"通过(考试);(在比赛中)胜出","en":"If someone gets through an examination or a round of a competition, they succeed or win.","ex":{"en":"She was bright, learned languages quickly, and sailed through her exams","cn":"她头脑聪明，学语言学得快，各门考试都顺利地通过。"}},{"pos":"ADV 副词","cn":"(电话)接通，打通","en":"When you get through while making a telephone call, the call is connected and you can speak to the person you are phoning.","ex":{"en":"He may find the line cut on the telephone so that he can't get through","cn":"他可能会发现电话线被切断了，所以打不通。"}},{"pos":"PREP 介词","cn":"彻底地(查看或检查)","en":"If you look or go through a lot of things, you look at them or deal with them one after the other.","ex":{"en":"Let's go through the numbers together and see if a workable deal is possible","cn":"我们一起把这些数目过一遍，看能不能找出个可行方案。"}},{"pos":"PREP 介词","cn":"从头到尾(阅读)","en":"If you read through something, you read it from beginning to end.","ex":{"en":"She read through pages and pages of the music I had brought her","cn":"她一页一页地翻看我带给她的乐谱。"}},{"pos":"ADJ 形容词","cn":"(火车)直达的","en":"A through train goes directly to a particular place, so that the people who want to go there do not have to change trains.","ex":{"en":"...Britain's longest through train journey, 685 miles.","cn":"英国行程最远的直达列车路线——685 英里"}},{"pos":"ADV 副词","cn":"(湿)透","en":"If you say that someone or something is wet through, you are emphasizing how wet they are.","ex":{"en":"I returned to the inn cold and wet, soaked through by the drizzling rain","cn":"我回到小旅馆时身上被毛毛雨淋透了，感觉又冷又湿。"}},{"pos":"PHRASE 短语","cn":"彻底;完全","en":"Through and through means completely and to the greatest extent possible.","ex":{"en":"I've gotten my feet thoroughly soaked and feel frozen through and through","cn":"我双脚湿透，感觉都冻到骨头里了。"}}]},"examples":[{"en":"‘Did you stop in Oxford on the way?’ ‘No, we drove straight through.’ “","cn":"你路经牛津时停车了吗？” “没有，我一直开过来的。”"},{"en":"The children are too young to sit through a concert.","cn":"这些孩子年纪太小，音乐会没完就坐不住了。"}]},"throng":{"media":{"uk":"media/uk/throng__gb_1.mp3","us":"media/us/throng__us_1.mp3"},"oxford":{"phon":"θrɒŋ","pos":"noun","senses":[{"en":"a crowd of people","cn":"聚集的人群；一大群人","ex":{"en":"We pushed our way through the throng.","cn":"我们挤过人群。"}},{"en":"to go somewhere or be present somewhere in large numbers","cn":"群集；拥塞；拥向","ex":{"en":"The children thronged into the hall.","cn":"孩子们拥进了大厅。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一大群人;人群","en":"A throng is a large crowd of people.","ex":{"en":"An official pushed through the throng.","cn":"一名官员费力地挤过人群。"}},{"pos":"VERB 动词","cn":"(人群)涌向，蜂拥","en":"When people throng somewhere, they go there in great numbers.","ex":{"en":"The crowds thronged into the mall.","cn":"人群涌进大厅。"}},{"pos":"VERB 动词","cn":"挤满;群集","en":"If people throng a place, they are present there in great numbers.","ex":{"en":"They throng the beaches between late June and early August.","cn":"6 月底到 8 月初，他们群聚在海滩上。"}}]},"examples":[{"en":"People are thronging to see his new play.","cn":"人们成群结队地去看他的新戏。"},{"en":"The cafes were thronging with students.","cn":"小餐馆里都挤满了学生。"}]},"themselves":{"media":{"uk":"media/uk/themselves__gb_1.mp3","us":"media/us/themselves__us_1.mp3"},"oxford":{"phon":"ðəmˈselvz","pos":"pronoun","senses":[{"en":"used when people or animals performing an action are also affected by it","cn":"他们自己；她们自己；它们自己","ex":{"en":"They seemed to be enjoying themselves.","cn":"他们好像玩得非常高兴。"}},{"en":"used instead of himself or herself to refer to a person whose sex is not mentioned or not known","cn":"（用以代替 himself 或 herself，指称性别不详的人）","ex":{"en":"There wasn't anyone who hadn't enjoyed themselves.","cn":"没有人不尽兴。"}},{"en":"used to emphasize they or a plural subject","cn":"（用以强调 they 或复数主语）他们（或她们、它们）亲自，他们（或她们、它们）本身","ex":{"en":"They themselves had had a similar experience.","cn":"他们本身就曾有过类似的经历。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"他们自己;她们自己;它们自己","en":"You use themselves to refer to people, animals, or things when the object of a verb or preposition refers to the same people or things as the subject of the verb.","ex":{"en":"They all seemed to be enjoying themselves","cn":"他们好像玩得都很开心。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"他们自己，她们自己，它们自己(强调所指的人或物，有时用作动词或介词宾语，代替 them)","en":"You use themselves to emphasize the people or things that you are referring to. Themselves is also sometimes used instead of 'them' as the object of a verb or preposition.","ex":{"en":"Many mentally ill people are themselves unhappy about the idea of community care","cn":"许多精神病患者本身不喜欢社区护理。"}},{"pos":"PRON-REFL 反身代词","cn":"(用以代替himself or herself，指代句子的主语，而不指明是男是女;有人认为这种用法不对)","en":"You use themselves instead of 'himself or herself' to refer back to the person who is the subject of sentence without saying whether it is a man or a woman. Some people think this use is incorrect.","ex":{"en":"What can a patient with emphysema do to help themselves?","cn":"肺气肿病人能做些什么来帮助自己恢复健康？"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"(用以代替 himself or herself，强调所指代的人，但是不指明是男是女; themselves 有时也用作动词或介词的宾语;有人认为这种用法不对)","en":"You use themselves instead of 'himself or herself' to emphasize the person you are referring to without saying whether it is a man or a woman. Themselves is also sometimes used as the object of a verb or preposition. Some people think this use is incorrect.","ex":{"en":"Each student makes only one item themselves","cn":"每个学生自己只做一项。"}}]},"examples":[{"en":"They themselves had had a similar experience.","cn":"他们本身就曾有过类似的经历。"},{"en":"They wanted to spend the evening by themselves.","cn":"他们想要单独度过这个夜晚。"}]},"they're":{"media":{"uk":"media/uk/they_re_1_gb_1.mp3","us":"media/us/they_re_1_us_1.mp3"},"oxford":{"phon":"ðeə(r)","pos":"short form","senses":[{"en":"they are","cn":""}]},"collins":{"senses":[{"pos":"","cn":"(they are 的常用口语形式)","en":"They're is the usual spoken form of 'they are'.","ex":{"en":"People eat when they're depressed.","cn":"人在心情沮丧时就吃东西。"}}]},"examples":[{"en":"They’re going to Crete next week.","cn":"他们下周要去克里特岛。"}]},"theirs":{"media":{"uk":"media/uk/theirs__gb_1.mp3","us":"media/us/theirs__us_1.mp3"},"oxford":{"phon":"ðeəz","pos":"pronoun","senses":[{"en":"of or belonging to them","cn":"他们的，她们的，它们的（所有物）","ex":{"en":"Theirs are the children with very fair hair.","cn":"他们的孩子是那些长着满头金发的。"}}]},"collins":{"senses":[{"pos":"PRON-POSS 所有格代词","cn":"他们的，她们的，它们的(东西)","en":"You use theirs to indicate that something belongs or relates to the group of people, animals, or things that you are talking about.","ex":{"en":"There was a big group of a dozen people at the table next to theirs","cn":"他们旁边的桌上坐了一大群人，有十几个。"}},{"pos":"PRON-POSS 所有格代词","cn":"(用以代替his or hers，而不指明是男是女;有人认为这种用法不对)","en":"You use theirs instead of 'his or hers' to indicate that something belongs or relates to a person without saying whether that person is a man or a woman. Some people think this use is incorrect.","ex":{"en":"He would leave the trailer unlocked. If there was something inside someone wanted, it would be theirs for the taking","cn":"他不会给那个活动房屋上锁。里面要是有什么别人想要的东西，他们可以尽管拿。"}}]},"examples":[{"en":"Theirs are the children with very fair hair.","cn":"他们的孩子是那些长着满头金发的。"},{"en":"It's a favourite game of theirs.","cn":"这是他们最喜爱的游戏。"}]},"third":{"media":{"uk":"media/uk/third__gb_1.mp3","us":"media/us/third__us_1.mp3"},"oxford":{"phon":"θɜːd","pos":"ordinal number","senses":[{"en":"3rd","cn":"第三","ex":{"en":"Today is the third (of May).","cn":"今天是五月三日。"}},{"en":"each of three equal parts of something","cn":"三分之一","ex":{"en":"He divided the money into thirds.","cn":"他把钱分成三份。"},"pos":"noun"},{"en":"the lowest standard of degree given by a British university","cn":"第三等学位（英国大学颁发的最低标准学位）","pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"第三","en":"The third item in a series is the one that you count as number three.","ex":{"en":"I sleep on the third floor","cn":"我睡在三楼。"}},{"pos":"FRACTION 分数词","cn":"三分之一","en":"A third is one of three equal parts of something.","ex":{"en":"A third of the cost went into technology and services","cn":"有三分之一的支出投入了技术和服务。"}},{"pos":"ADV 副词","cn":"第三(点)","en":"You say third when you want to make a third point or give a third reason for something.","ex":{"en":"First, interest rates may take longer to fall than is hoped. Second, in real terms, lending may fall. Third, bad loans could wipe out much of any improvement.","cn":"首先，利率的下降可能没有希望的那样快;第二，实际贷款额可能会减少;第三，坏账很可能抵消大部分增长。"}},{"pos":"N-COUNT 可数名词","cn":"三等学位(英国大学颁发的最低级荣誉学位)","en":"A third is the lowest honours degree that can be obtained from a British university."}]},"examples":[{"en":"Divide it into thirds.","cn":"把它分成三等份。"},{"en":"A third of these jobs are held by women.","cn":"这些工作有三分之一由女性来做。"}]},"those":{"media":{"uk":"media/uk/those__gb_1.mp3","us":"media/us/those__us_1.mp3"},"collins":{"senses":[{"pos":"DET 限定词","cn":"(指代已经提及的人或物)那些","en":"You use those to refer to people or things which have already been mentioned.","ex":{"en":"Theoretically he had control over more than $400 million in US accounts. But, in fact, it was the US Treasury and State Department who controlled those accounts","cn":"从理论上说，他掌管着美国账户里的 4 亿美元。然而，事实上，是美国财政部和国务院在掌控那些账户。"}},{"pos":"DET 限定词","cn":"那些(尤用于指示或指向在时间、空间上离自己稍远的人或物)","en":"You use those when you are referring to people or things that are a distance away from you in position or time, especially when you indicate or point to them.","ex":{"en":"What are those buildings?","cn":"那些是什么建筑？"}},{"pos":"DET 限定词","cn":"(用于提供更多的细节、信息)","en":"You use those to refer to someone or something when you are going to give details or information about them.","ex":{"en":"Those people who took up weapons to defend themselves are political prisoners","cn":"那些拿起武器自卫的人是些政治犯。"}},{"pos":"PRON 代词","cn":"(用来对已经提及的事物作补充说明)","en":"You use those to introduce more information about something already mentioned, instead of repeating the noun which refers to it.","ex":{"en":"The interests he is most likely to enjoy will be those which enable him to show off himself or his talents","cn":"他最有可能感兴趣的就是那些能让他表现自己或炫耀才华的事情。"}},{"pos":"PRON 代词","cn":"人们;人","en":"You use those to mean 'people'.","ex":{"en":"A little selfish behaviour is unlikely to cause real damage to those around us","cn":"稍许自私的行为不会对我们身边的人造成实质性伤害。"}},{"pos":"DET 限定词","cn":"(用于认为谈话对象知道所谈事物或确认双方所想为相同的人或事物时)","en":"You use those when you refer to things that you expect the person you are talking to to know about or when you are checking that you are both thinking of the same people or things.","ex":{"en":"He did buy me those daffodils a week or so ago","cn":"他确实在大约一个星期前给我买了那些水仙花。"}}]}},"threaded":{"media":{"uk":"media/uk/threaded__gb_1.mp3","us":"media/us/threaded__us_1.mp3"},"oxford":{"phon":"ˈθredɪd","pos":"adjective","senses":[{"en":"having a thread (5)","cn":"有螺纹的"}]},"base":"thread"},"thriving":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"achieving what you wanted, or having the effect or result you intended","cn":""},{"en":"having the effect or result that was wanted – used especially about treatments, drugs, or methods","cn":""}]},"examples":[{"en":"a thriving tourist industry","cn":"欣欣向荣的旅游业","src":"ld"}],"media":{"uk":"media/uk/thriving__gb_1.mp3","us":"media/us/thriving__us_1.mp3"},"oxford":{"phon":"ˈθraɪvɪŋ","pos":"adjective","senses":[{"en":"continuing to be successful, strong, healthy, etc.","cn":"兴旺发达；繁荣；蓬勃发展；旺盛；茁壮成长","ex":{"en":"a thriving industry","cn":"繁荣的行业"}}]},"base":"thrive"},"thunder":{"oxford":{"phon":"ˈθʌndə(r)","pos":"noun","senses":[{"en":"the loud noise that you hear after a flash of lightning, during a storm","cn":"雷；雷声","lab":"North American English","ex":{"en":"the rumble of distant thunder","cn":"远处雷声隆隆"}},{"en":"a loud noise like thunder","cn":"雷鸣般的响声；轰隆声","ex":{"en":"the thunder of horses' hooves","cn":"隆隆的马蹄声"}},{"en":"when it thunders, there is a loud noise in the sky during a storm","cn":"打雷","g":"[intransitive]","pos":"verb"},{"en":"to make a very loud, deep noise","cn":"发出雷鸣般响声；轰隆隆地响","g":"[intransitive]","ex":{"en":"A voice thundered in my ear.","cn":"一个震耳欲聋的声音在我耳边响起。"},"pos":"verb"},{"en":"to move very fast and with a loud deep noise","cn":"轰隆隆地快速移动","g":"[intransitive]","ex":{"en":"Heavy trucks kept thundering past.","cn":"重型卡车不断地隆隆驶过。"},"pos":"verb"},{"en":"to make something move somewhere very fast","cn":"使快速移动","g":"[transitive]","lab":"informal","ex":{"en":"Essien thundered the ball past the goalie.","cn":"埃辛砰的一脚将球踢过了守门员。"},"pos":"verb"},{"en":"to shout, complain, etc. very loudly and angrily","cn":"怒喝；大声斥责","g":"[intransitive, transitive]","lab":"literary","ex":{"en":"He thundered against the evils of television.","cn":"他大声谴责电视的种种坏处。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"雷;雷声","en":"Thunder is the loud noise that you hear from the sky after a flash of lightning, especially during a storm.","ex":{"en":"There was frequent thunder and lightning, and torrential rain.","cn":"雷电交加，大雨倾盆。"}},{"pos":"VERB 动词","cn":"打雷","en":"When it thunders, a loud noise comes from the sky after a flash of lightning.","ex":{"en":"The day was heavy and still. It would probably thunder later.","cn":"天色阴沉，一丝风也没有。或许马上就要打雷。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"雷鸣般的响声;轰隆声","en":"The thunder of something that is moving or making a sound is the loud deep noise it makes.","ex":{"en":"The thunder of the sea on the rocks seemed to blank out other thoughts","cn":"海水拍打礁石的咆哮声似乎要淹没一切思绪。"}},{"pos":"VERB 动词","cn":"轰隆隆地快速移动","en":"If something or someone thunders somewhere, they move there quickly and with a lot of noise.","ex":{"en":"The horses thundered across the valley floor","cn":"马群轰隆隆地从谷底奔跑而过。"}},{"pos":"VERB 动词","cn":"发出轰隆声;轰鸣","en":"If something thunders, it makes a very loud noise, usually continuously.","ex":{"en":"She heard the sound of the guns thundering in the fog.","cn":"她听到雾中传来隆隆的枪炮声。"}},{"pos":"VERB 动词","cn":"愤怒地大叫;怒吼","en":"If you thunder something, you say it loudly and forcefully, especially because you are angry.","ex":{"en":"'It's your money. Ask for it!' she thundered","cn":"“那是你的钱。快去要！”她生气地大喊。"}},{"pos":"PHRASE 短语","cn":"抢…的风头;抢…的功劳","en":"If you steal someone's thunder, you get the attention or praise that they thought they would get, usually by saying or doing what they had intended to say or do.","ex":{"en":"He had no intention of letting the Foreign Secretary steal any of his thunder.","cn":"他无意让外交大臣抢他的风头。"}}]},"media":{"uk":"media/uk/thunder__gb_1.mp3","us":"media/us/thunder__us_1.mp3"},"examples":[{"en":"A voice thundered in my ear.","cn":"一个震耳欲聋的声音在我耳边响起。"},{"en":"Essien thundered the ball past the goalie.","cn":"埃辛砰地一脚将球踢过了守门员。"}]},"they've":{"media":{"uk":"media/uk/they_ve_1_gb_1.mp3","us":"media/us/they_ve_1_us_1.mp3"},"oxford":{"phon":"ðeɪv","pos":"short form","senses":[{"en":"they have","cn":""}]},"collins":{"senses":[{"pos":"","cn":"(尤当have为助动词时，they have的常用口语形式)","en":"They've is the usual spoken form of 'they have', especially when 'have' is an auxiliary verb.","ex":{"en":"The worst thing is when you call friends and they've gone out.","cn":"最糟糕的事情是，你给朋友打电话，而他们却出去了。"}}]},"examples":[{"en":"They’ve had a lot of trouble with their car.","cn":"他们的车子出过许多毛病。"}]},"thorny":{"oxford":{"phon":"ˈθɔːni","pos":"adjective","senses":[{"en":"causing difficulty or disagreement","cn":"棘手的；麻烦的；引起争议的","g":"[usually before noun]","ex":{"en":"There are still some thorny questions to be answered.","cn":"还有一些棘手的问题需要回答。"}},{"en":"having thorns","cn":"有刺的；多刺的","ex":{"en":"a thorny bush","cn":"有刺的灌木"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(植物、树木)带刺的，多刺的","en":"A thorny plant or tree is covered with thorns.","ex":{"en":"...thorny hawthorn trees.","cn":"长满刺的山楂树"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(问题)棘手的，复杂难解的，令人头疼的","en":"If you describe a problem as thorny, you mean that it is very complicated and difficult to solve, and that people are often unwilling to discuss it.","ex":{"en":"...the thorny issue of immigration policy","cn":"移民政策这个棘手问题"}}]},"media":{"uk":"media/uk/thorny__gb_1.mp3","us":"media/us/thorny__us_1.mp3"},"examples":[{"en":"a thorny question/issue/problem","cn":"棘手的问题"},{"en":"a thorny bush","cn":"有刺的灌木"}]},"thursday":{"media":{"uk":"media/uk/thursday__gb_1.mp3","us":"media/us/thursday__us_1.mp3"},"oxford":{"phon":"ˈθɜːzdeɪ","pos":"noun","senses":[{"en":"the day of the week after Wednesday and before Friday","cn":"星期四","lab":"informal or North American English","ex":{"en":"It's Thursday today, isn't it?","cn":"今天是星期四，对吧？"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"星期四","en":"Thursday is the day after Wednesday and before Friday.","ex":{"en":"On Thursday Barrett invited me for a drink","cn":"星期四，巴雷特约我去喝两杯。"}}]}},"thrice":{"media":{"uk":"media/uk/thrice__gb_1.mp3","us":"media/us/thrice__us_1.mp3"},"oxford":{"phon":"θraɪs","pos":"adverb","senses":[{"en":"three times","cn":"三次；三倍"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"三次","en":"Something that happens thrice happens three times.","ex":{"en":"They should think not twice, but thrice, before ignoring such advice","cn":"对于这样的建议，他们应该反复考虑再决定是否拒绝。"}},{"pos":"ADV 副词","cn":"三倍","en":"You can use thrice to indicate that something is three times the size, value, or intensity of something else.","ex":{"en":"The metal had been valued at twice or thrice its current price.","cn":"这种金属以前的估价是目前价格的两到三倍。"}}]}},"threatens":{"lemma":"threaten"},"thrill":{"oxford":{"phon":"θrɪl","pos":"noun","senses":[{"en":"a strong feeling of excitement or pleasure; an experience that gives you this feeling","cn":"震颤感；兴奋感；兴奋；激动；令人兴奋的经历","ex":{"en":"It gave me a big thrill to meet my favourite author in person.","cn":"能见到我最喜欢的作者本人使我感到兴奋不已。"}},{"en":"a sudden, strong feeling that produces a physical effect","cn":"一阵强烈的感觉","ex":{"en":"A thrill of alarm ran through him.","cn":"一阵惊恐的感觉传遍他的全身。"}},{"en":"to cause somebody to feel very pleased or excited","cn":"使非常兴奋；使非常激动","ex":{"en":"This band has thrilled audiences all over the world.","cn":"这支乐队使全世界的观众狂热痴迷。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(突然而强烈的)激动，狂喜，恐惧","en":"If something gives you a thrill, it gives you a sudden feeling of great excitement, pleasure, or fear.","ex":{"en":"I can remember the thrill of not knowing what I would get on Christmas morning","cn":"我还记得自己不知道圣诞节早晨会得到什么礼物时内心有多么激动。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)狂喜;(使)激动;(使)极度兴奋","en":"If something thrills you, or if you thrill at it, it gives you a feeling of great pleasure and excitement.","ex":{"en":"The electric atmosphere both terrified and thrilled him","cn":"极度紧张的气氛让他既害怕又兴奋。"}},{"pos":"PHRASE 短语","cn":"惊险刺激","en":"If you refer to thrills and spills, you are referring to an experience which is exciting and full of surprises.","ex":{"en":"Its prime audience lies in the 17 to 24 age group, and they want instant thrills and spills.","cn":"它的主要观众的年龄集中在 17 岁到 24 岁之间，而这些人喜欢极速的惊险刺激。"}}]},"media":{"uk":"media/uk/thrill__gb_1.mp3","us":"media/us/thrill__us_1.mp3"},"examples":[{"en":"It gave me a big thrill to meet my favourite author in person.","cn":"能见到我最喜欢的作者本人使我感到兴奋不已。"},{"en":"This band has thrilled audiences all over the world.","cn":"这支乐队使全世界的观众狂热痴迷。"}]},"thankfully":{"media":{"uk":"media/uk/thankfully__gb_1.mp3","us":"media/us/thankfully__us_1.mp3"},"oxford":{"phon":"ˈθæŋkfəli","pos":"adverb","senses":[{"en":"used to show that you are pleased that something good has happened or that something bad has been avoided","cn":"（用以表示高兴）幸亏","ex":{"en":"There was a fire in the building, but thankfully no one was hurt.","cn":"大楼失火了，但幸好没有伤着人。"}},{"en":"in a pleased or grateful way","cn":"高兴地；感激地","ex":{"en":"At the end of a busy day, I just sink thankfully into bed.","cn":"忙碌的一天结束后，我庆幸地躺在床上。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"幸运的是;幸亏;幸好","en":"You use thankfully in order to express approval or happiness about a statement that you are making.","ex":{"en":"Thankfully, she was not injured","cn":"好在她没有受伤。"}}]},"examples":[{"en":"There was a fire in the building, but thankfully no one was hurt.","cn":"大楼失火了，但幸好没有伤着人。"},{"en":"I accepted the invitation thankfully.","cn":"我愉快地接受了邀请。"}]},"theft":{"media":{"uk":"media/uk/theft__gb_1.mp3","us":"media/us/theft__us_1.mp3"},"oxford":{"phon":"θeft","pos":"noun","senses":[{"en":"the crime of stealing something from a person or place","cn":"偷；偷窃；盗窃罪","ex":{"en":"car theft","cn":"偷盗汽车"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"偷窃;盗窃(罪)","en":"Theft is the crime of stealing.","ex":{"en":"Art theft is now part of organised crime.","cn":"盗窃艺术品如今成为一种有组织的犯罪活动。"}}]},"examples":[{"en":"Police are investigating the theft of computers from the company's offices.","cn":"警方正在调查这家公司办公室里的计算机失窃案。"},{"en":"car theft","cn":"偷盗汽车"}]},"thinking":{"media":{"uk":"media/uk/thinking__gb_1.mp3","us":"media/us/thinking__us_1.mp3"},"oxford":{"phon":"ˈθɪŋkɪŋ","pos":"noun","senses":[{"en":"the process of thinking about something","cn":"思想；思考；思维","ex":{"en":"I had to do some quick thinking.","cn":"我得迅速思考一番。"}},{"en":"ideas or opinions about something","cn":"想法；见解","ex":{"en":"What is the current thinking on this question?","cn":"目前对这个问题的看法是什么？"}},{"en":"intelligent and able to think seriously about things","cn":"思想的；有理智的；有思考力的","ex":{"en":"the thinking man's football website","cn":"有思想的人的足球网站"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"思想;观点","en":"The general ideas or opinions of a person or group can be referred to as their thinking .","ex":{"en":"There was undeniably a strong theoretical dimension to his thinking.","cn":"不可否认，他的思想很有理论深度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"思想;思维;思考","en":"Thinking is the activity of using your brain by considering a problem or possibility or creating an idea.","ex":{"en":"This is a time of decisive action and quick thinking","cn":"这个时候应该果断行动、快速反应。"}},{"pos":"ADJ 形容词","cn":"有头脑的;有见识的","en":"If you describe someone as a thinking man or woman, you mean that they are intelligent and take an interest in important events and issues, and you approve of this.","ex":{"en":"Thinking people on both sides will applaud this book","cn":"双方的有识之士都会称赞这本书。"}},{"pos":"See also:","cn":"","en":"to my way of thinking→see: ;"}]},"examples":[{"en":"What is the current thinking on this question?","cn":"目前对这个问题的看法是什么？"},{"en":"She explained the thinking behind the campaign.","cn":"她解释了发动这场运动的想法。"}],"base":"think"},"think":{"media":{"uk":"media/uk/think__gb_1.mp3","us":"media/us/think__us_1.mp3"},"oxford":{"phon":"θɪŋk","pos":"verb","senses":[{"en":"to have a particular idea or opinion about something/somebody; to believe something","cn":"认为；以为","g":"[transitive, intransitive]","lab":"North American English, informal，，","sc":"have opinion/belief","ex":{"en":"Do you really think (that) he'll win?","cn":"你真认为他会赢吗？"}},{"en":"to use your mind to consider something, to form connected ideas, to try to solve problems, etc.","cn":"想；思考；思索；思想","g":"[intransitive, transitive]","sc":"use mind","ex":{"en":"Are animals able to think?","cn":"动物会思考吗？"}},{"en":"to have ideas, words or images in your mind","cn":"想；琢磨","g":"[transitive]","sc":"use mind","ex":{"en":"You're very quiet. What are you thinking?","cn":"你一声不吭，在想什么？"}},{"en":"to form an idea of something; to imagine something","cn":"猜想；想象；试想","g":"[transitive, no passive, intransitive]","lab":"especially British English","sc":"imagine","ex":{"en":"We couldn't think where you'd gone.","cn":"我们猜不出来你到哪里去了。"}},{"en":"to expect something","cn":"料想；预料；预期","g":"[transitive]","lab":"formal","sc":"expect","ex":{"en":"I never thought (that) I’d see her again.","cn":"我从未料想到还会见到她。"}},{"en":"to think in a particular way or on a particular subject","cn":"只想；一心想；对…着迷","g":"[intransitive, transitive]","lab":"informal","sc":"in a particular way","ex":{"en":"Let's think positive.","cn":"咱们往好的方面想吧。"}},{"en":"used in questions to show that you are angry or surprised","cn":"（用于问句，表示生气或吃惊）","g":"[transitive]","sc":"showing anger/surprise","ex":{"en":"What do you think you're doing?","cn":"你以为你在干什么？"}},{"en":"used to make something you say sound less definite or more polite","cn":"（用于使话语不太肯定或较为婉转）","g":"[transitive, intransitive]","sc":"being less definite/more polite","ex":{"en":"I thought we could go out tonight.","cn":"我本想我们今晚可以出去。"}},{"en":"to intend something; to have a plan about something","cn":"打算；想要；计划","g":"[transitive, intransitive]","sc":"intend","ex":{"en":"I think I'll go for a swim.","cn":"我想去游泳。"}},{"en":"to remember something; to have something come into your mind","cn":"记得；想起","g":"[transitive]","sc":"remember","ex":{"en":"I didn't think (= it did not occur to me) to tell her.","cn":"我没有想到要告诉她。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"想;认为","en":"If you think that something is the case, you have the opinion that it is the case.","ex":{"en":"I certainly think there should be a ban on tobacco advertising","cn":"我确实认为应该禁止香烟广告。"}},{"pos":"VERB 动词","cn":"感觉;觉得","en":"If you say that you think that something is true or will happen, you mean that you have the impression that it is true or will happen, although you are not certain of the facts.","ex":{"en":"Nora thought he was seventeen years old","cn":"诺拉觉得他有 17 岁。"}},{"pos":"VERB 动词","cn":"（以某种方式）考虑，思考","en":"If you think in a particular way, you have those general opinions or attitudes.","ex":{"en":"You were probably brought up to think like that","cn":"你可能从小就被教育那样考虑问题。"}},{"pos":"VERB 动词","cn":"想;考虑;思考","en":"When you think about ideas or problems, you make a mental effort to consider them.","ex":{"en":"She closed her eyes for a moment, trying to think","cn":"她闭了一会儿眼睛，努力思考着。"}},{"pos":"VERB 动词","cn":"(以某种方式)考虑，思考","en":"If you think in a particular way, you consider things, solve problems, or make decisions in this way, for example because of your job or your background.","ex":{"en":"To make the computer work at full capacity, the programmer has to think like the machine","cn":"为了让计算机充分发挥作用，程序员就得像计算机一样思考。"}},{"pos":"VERB 动词","cn":"想到;想起;想出","en":"If you think of something, it comes into your mind or you remember it.","ex":{"en":"Nobody could think of anything to say","cn":"谁也想不出什么话说。"}},{"pos":"VERB 动词","cn":"想出，想到(主意)","en":"If you think of an idea, you make a mental effort and use your imagination and intelligence to create it or develop it.","ex":{"en":"He thought of another way of getting out of the marriage","cn":"他又想到一个摆脱那桩婚姻的点子。"}},{"pos":"VERB 动词","cn":"心里想;琢磨","en":"If you are thinking something at a particular moment, you have words or ideas in your mind without saying them out loud.","ex":{"en":"She must be ill, Tatiana thought","cn":"她一定是病了，塔蒂亚娜心想。"}},{"pos":"VERB 动词","cn":"认为，以为(人或物具有某特点或用途)","en":"If you think of someone or something as having a particular quality or purpose, you regard them as having this quality or purpose.","ex":{"en":"We all thought of him as a father","cn":"我们都视他为父亲。"}},{"pos":"VERB 动词","cn":"对…评价(很高)","en":"If you think a lot of someone or something, you admire them very much or think they are very good.","ex":{"en":"To tell the truth, I don't think much of psychiatrists","cn":"说实话，我不太喜欢精神科医生。"}},{"pos":"VERB 动词","cn":"关心;考虑;为…着想","en":"If you think of someone, you show consideration for them and pay attention to their needs.","ex":{"en":"I'm only thinking of you","cn":"我一心只为你着想。"}},{"pos":"VERB 动词","cn":"考虑;打算","en":"If you are thinking of taking a particular course of action, you are considering it as a possible course of action.","ex":{"en":"Martin was thinking of taking legal action against Zuckerman","cn":"马丁在考虑对朱克曼提起诉讼。"}},{"pos":"VERB 动词","cn":"(用来引出例子或进一步解释)考虑,想到(某方面、某主题)","en":"You can say that you are thinking of a particular aspect or subject, in order to introduce an example or explain more exactly what you are talking about.","ex":{"en":"I'm primarily thinking of the first year","cn":"我考虑的主要是第一年。"}},{"pos":"VERB 动词","cn":"(用于问句，表示生气、震惊)认为，以为","en":"You use think in questions where you are expressing your anger or shock at someone's behaviour.","ex":{"en":"Who does she think she is? Trying to make a fool of me like that","cn":"她以为她是谁啊？竟敢那样取笑我。"}},{"pos":"VERB 动词","cn":"想来，想想看(用于评论过去所做或经历过的事情现在看来不可思议、愚蠢或令人震惊)","en":"You use think when you are commenting on something which you did or experienced in the past and which now seems surprising, foolish, or shocking to you.","ex":{"en":"To think I left you alone in a place with a madman at large!","cn":"想想看，我竟然把你一个人抛在那儿，让你和一个无人看管的疯子呆在一起！"}},{"pos":"VERB 动词","cn":"本来以为，原以为(用于批评别人该做某事而未做)","en":"You can use think in expressions such as you would think or I would have thought when you are criticizing someone because they ought to or could be expected to do something, but have not done it.","ex":{"en":"You'd think you'd remember to wash your ears","cn":"还以为你能记得洗耳朵呢。"}},{"pos":"VERB 动词","cn":"谁都会以为/你会认为(用于对他人的行为表示惊讶或不满)","en":"You can use think in expressions such as anyone would think and you would think to express your surprise or disapproval at the way someone is behaving.","ex":{"en":"Anyone would think you were in love with the girl","cn":"谁都会以为你和那个姑娘恋爱了。"}},{"pos":"PHRASE 短语","cn":"(表示突然记起或意识到某事)想起来了，想想看","en":"You use expressions such as come to think of it ,when you think about it, or thinking about it, when you mention something that you have suddenly remembered or realized.","ex":{"en":"He was her distant relative, as was everyone else on the island, come to think of it","cn":"想起来了，他和岛上的其他人一样，都是她的远亲。"}},{"pos":"PHRASE 短语","cn":"我想，我觉得(用于委婉地解释等)","en":"You use 'I think' as a way of being polite when you are explaining or suggesting to someone what you want to do, or when you are accepting or refusing an offer.","ex":{"en":"I think I'll go home and have a shower","cn":"我觉得我得回家冲个澡。"}},{"pos":"PHRASE 短语","cn":"我认为，我想(用于会话或讲话中，使语气稍显婉转)","en":"You use 'I think' in conversations or speeches to make your statements and opinions sound less forceful, rude, or direct.","ex":{"en":"I think he means 'at' rather than 'to'","cn":"我想，他是想说at，而不是to。"}},{"pos":"PHRASE 短语","cn":"你想一想，想象一下(表示激动、着迷或震惊，同时希望谈话对方也有同感)","en":"You say just think when you feel excited, fascinated, or shocked by something, and you want the person to whom you are talking to feel the same.","ex":{"en":"Just think; tomorrow we shall walk out of this place and leave it all behind us forever","cn":"你想想看，明天我们就要走出这个地方，再也不回来了。"}},{"pos":"PHRASE 短语","cn":"重新考虑，再三斟酌(常指最终改变主意)","en":"If you think again about an action or decision, you consider it very carefully, often with the result that you change your mind and decide to do things differently.","ex":{"en":"It has forced politicians to think again about the wisdom of trying to evacuate refugees","cn":"这迫使政治家们重新考虑疏散难民是否明智。"}},{"pos":"PHRASE 短语","cn":"认为…没什么了不起;觉得…很容易;认为…无所谓","en":"If you think nothing of doing something that other people might consider difficult, strange, or wrong, you consider it to be easy or normal, and you do it often or would be quite willing to do it.","ex":{"en":"I thought nothing of betting £1,000 on a horse.","cn":"我认为把 1,000 英镑押在一匹马身上没什么了不起。"}},{"pos":"PHRASE 短语","cn":"对…不在意;不觉得…奇怪(或重要)","en":"If something happens and you think nothing of it, you do not pay much attention to it or think of it as strange or important, although later you realize that it is.","ex":{"en":"When she went off to see her parents for the weekend I thought nothing of it","cn":"她周末去看她的父母，我当时没觉得有什么特别的。"}},{"pos":"","cn":"","en":"you can't hear yourself think→see: ; to shudder to think→see: ; to think better of it→see: ; to think big→see: ; to think twice→see: ; to think the world of someone→see: ;"},{"pos":"","cn":"","en":"相关词组：think back think out think over think through think up"}]},"examples":[{"en":"To think that my mother wrote all those books and I never knew!","cn":"想想看，我母亲写了那么多部书，我竟然一无所知！"},{"en":"Just think — we'll be lying on the beach this time tomorrow.","cn":"想想看，明天这个时候我们就躺在海滩上了。"}]},"threatening":{"oxford":{"phon":"ˈθretnɪŋ","pos":"adjective","senses":[{"en":"expressing a threat of harm or violence","cn":"威胁的；恐吓的","ex":{"en":"threatening letters","cn":"恐吓信"}},{"en":"showing that bad weather is likely","cn":"阴沉沉的；乌云密布的","ex":{"en":"The sky was dark and threatening.","cn":"天空乌云密布，阴沉沉的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)有威胁性的，危险的","en":"You can describe someone's behaviour as threatening when you think that they are trying to harm you.","ex":{"en":"The police could have charged them with threatening behaviour","cn":"警方本可指控他们恐吓。"}}]},"media":{"uk":"media/uk/threatening__gb_1.mp3","us":"media/us/threatening__us_1.mp3"},"examples":[{"en":"The sky was dark and threatening.","cn":"天空乌云密布，阴沉沉的。"},{"en":"He glared at her threateningly.","cn":"他气势汹汹地瞪着她。"}],"base":"threaten"},"thief":{"media":{"uk":"media/uk/thief__gb_1.mp3","us":"media/us/thief__us_1.mp3"},"oxford":{"phon":"θiːf","pos":"noun","senses":[{"en":"a person who steals something from another person or place","cn":"贼；小偷；窃贼","lab":"British English","ex":{"en":"a car/jewel thief","cn":"偷汽车／偷珠宝的窃贼"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小偷;窃贼","en":"A thief is a person who steals something from another person.","ex":{"en":"The thieves snatched the camera.","cn":"窃贼偷走了相机。"}}]},"examples":[{"en":"a car/jewel, etc. thief","cn":"偷汽车、珠宝等的窃贼"}]},"third-rate":{"oxford":{"phon":"ˌθɜːd ˈreɪt","pos":"adjective","senses":[{"en":"of very poor quality","cn":"劣质的；非常差劲的；三流的","ex":{"en":"a third-rate actor","cn":"三流演员"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"三流的;低劣的","en":"If you describe something as third-rate, you mean that it is of a very poor quality or standard.","ex":{"en":"...a third-rate movie.","cn":"三流电影"}}]},"media":{"uk":"media/uk/third_rate_1_gb_1.mp3","us":"media/us/third_rate_1_us_1.mp3"},"examples":[{"en":"a third-rate actor","cn":"三流演员"},{"en":"a third-rate hotel","cn":"一家三流宾馆"}]},"thickly":{"oxford":{"phon":"ˈθɪkli","pos":"adverb","senses":[{"en":"in a way that produces a wide piece or deep layer of something","cn":"厚厚地","ex":{"en":"thickly sliced bread","cn":"切成厚片的面包"}},{"en":"having a lot of trees, people, etc. close together","cn":"（树木、人口等）茂密，稠密"},{"en":"in a deep voice that is not as clear as normal, especially because of illness or emotion","cn":"声音不清地，沙哑地（尤指因疾病或激动）","ex":{"en":"‘Just leave me alone,’ he said thickly.","cn":"“让我一个人待着吧。”他沙哑地说道。"}}]},"media":{"uk":"media/uk/thickly__gb_1.mp3","us":"media/us/thickly__us_1.mp3"},"examples":[{"en":"Apply the paint thickly in even strokes.","cn":"涂颜料要厚，笔画要匀。"},{"en":"thickly sliced bread","cn":"切成厚片的面包"}]},"this":{"media":{"uk":"media/uk/this__gb_1.mp3","us":"media/us/this__us_1.mp3"},"oxford":{"phon":"ðɪs","pos":"determiner, pronoun","senses":[{"en":"used to refer to a particular person, thing or event that is close to you, especially compared with another","cn":"（指较近的人或事物）这，这个","ex":{"en":"How long have you been living in this country?","cn":"你在这个国家居住多久啦？"}},{"en":"used to refer to something/somebody that has already been mentioned","cn":"（指已提到过的人或事物）这，这个","ex":{"en":"There was a court case resulting from this incident.","cn":"这一事件引起一宗庭审案件。"}},{"en":"used for introducing somebody/yourself","cn":"（介绍某人或自我介绍时用）这，我","lab":"North American English","ex":{"en":"Hello, this is Carlos Diaz (= on the phone).","cn":"喂，我是卡洛斯·迪亚兹。"}},{"en":"used for showing somebody to something or calling somebody's attention to something","cn":"（展示事物或提请注意时用）这，这样","ex":{"en":"Do it like this (= in the way I am showing you).","cn":"照这样去做。"}},{"en":"used with periods of time related to the present","cn":"（与和现在有关的一段时间连用）今，本，这个，现在","ex":{"en":"this week/month/year","cn":"本周；本月；今年"}},{"en":"used to refer to somebody/something that is connected with a person, especially when you have a particular attitude towards it or them","cn":"（尤指说话者抱有既定看法的人或事物）…的这个（或这些）","lab":"informal","ex":{"en":"These new friends of hers are supposed to be very rich.","cn":"她的这些新朋友想必都很富有。"}},{"en":"used when you are telling a story or telling somebody about something","cn":"（述说时用）有个","lab":"informal","ex":{"en":"There was this strange man sitting next to me on the plane.","cn":"在飞机上有个奇怪的人坐在我身旁。"}},{"en":"to this degree; so","cn":"这样；这么","ex":{"en":"It's about this high (= as high as I am showing you with my hands).","cn":"大约有这么高。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"(指代先前提及的人或物)这，这个","en":"You use this to refer back to a particular person or thing that has been mentioned or implied.","ex":{"en":"When food comes out of any oven, it should stand a while. During this delay the centre carries on cooking","cn":"食物出炉后都应该静置一会。在此期间，中心部分还在继续加热。"}},{"pos":"PRON 代词","cn":"(引出将要谈论的人或物)下面(这个)，以下","en":"You use this to introduce someone or something that you are going to talk about.","ex":{"en":"This is what I will do. I will telephone Anna and explain.","cn":"下面是我要做的：我要给安娜打电话解释清楚。"}},{"pos":"PRON 代词","cn":"这一点(指前一句或几句话中提到的观点或情况)","en":"You use this to refer back to an idea or situation expressed in a previous sentence or sentences.","ex":{"en":"You feel that it's uneconomic to insist that people work together in groups. Why is this?","cn":"你觉得要求大家分组工作不划算，这是为什么呢？"}},{"pos":"DET 限定词","cn":"(叙述时引出新出现的人或物)这个，一个","en":"In spoken English, people use this to introduce a person or thing into a story.","ex":{"en":"I came here by chance and was just watching what was going on, when this girl attacked me","cn":"我碰巧来到这儿，正看着热闹，突然一个女孩袭击了我。"}},{"pos":"PRON 代词","cn":"这个，这位(尤指所触碰或指向的离自己较近的人或物，有两个以上时，用于指最近的一个)","en":"You use this to refer to a person or thing that is near you, especially when you touch them or point to them. When there are two or more people or things near you, this refers to the nearest one.","ex":{"en":"'If you'd prefer something else I'll gladly have it changed for you.' — 'No, this is great.'","cn":"“您要是喜欢别的，我很乐意帮您调换一下。”——“不用了，这个挺好。”"}},{"pos":"PRON 代词","cn":"这个，这(指代正在发生或刚刚发生的与自己有关的一般情况、活动或事件)","en":"You use this when you refer to a general situation, activity, or event which is happening or has just happened and which you feel involved in.","ex":{"en":"I thought, this is why I've travelled thousands of miles","cn":"我想，这就是我为何不远千里赶来的原因。"}},{"pos":"DET 限定词","cn":"这，该，此(指当前所处地点或时间)","en":"You use this when you refer to the place you are in now or to the present time.","ex":{"en":"We've stopped transporting weapons to this country by train","cn":"我们已停止用火车向该国运送武器。"}},{"pos":"DET 限定词","cn":"本，今，这个，下一个(指接下来将要发生某事的特定时间)","en":"You use this to refer to the next occurrence in the future of a particular day, month, season, or festival.","ex":{"en":"...this Sunday's 7.45 performance","cn":"本周日 7 点 45 分的表演"}},{"pos":"ADV 副词","cn":"这么，这样(用于用手比划大小、形状时)","en":"You use this when you are indicating the size or shape of something with your hands.","ex":{"en":"They'd said the wound was only about this big you see and he showed me with his fingers.","cn":"他们说伤口只有这么一点大，他还用手指比划给我看。"}},{"pos":"ADV 副词","cn":"这么，这样(用于说明自己知道或能告知的内容)","en":"You use this when you are going to specify how much you know or how much you can tell someone.","ex":{"en":"I am not going to reveal what my seven-year plan is, but I will tell you this much, if it works out, the next seven years will be very interesting.","cn":"我不想透露我的七年计划的具体内容，不过有一点可以告诉你，如果顺利实施，今后的七年将非常有意义。"}},{"pos":"CONVENTION 惯用语","cn":"是这样;确实","en":"If you say this is it, you are agreeing with what someone else has just said.","ex":{"en":"'You know, people conveniently forget the things they say.' — 'Well this is it.'","cn":"“你知道，人们会选择性地忘记自己说过的话。”——“嗯，是这样。”"}},{"pos":"PRON 代词","cn":"(用于电话、广播或电视中，表明身份或所代表的机构)我是，这里是","en":"You use this in order to say who you are or what organization you are representing, when you are speaking on the telephone, radio, or television.","ex":{"en":"Hello, this is John Thompson","cn":"喂，我是约翰·汤普森。"}},{"pos":"DET 限定词","cn":"这个(指说话、写作时的媒介)","en":"You use this to refer to the medium of communication that you are using at the time of speaking or writing.","ex":{"en":"What I'm going to do in this lecture is focus on something very specific","cn":"我在今天的讲座中将主要探讨一些非常具体的问题。"}},{"pos":"PHRASE 短语","cn":"各种各样的东西;这样那样","en":"If you say that you are doing or talking about this and that, or this, that, and the other you mean that you are doing or talking about a variety of things that you do not want to specify.","ex":{"en":"'And what are you doing now?' — 'Oh this and that.'","cn":"“那你现在在做什么呢？”——“哦，瞎忙。”"}}]},"examples":[{"en":"Well, make up your mind. Which do you want? This one or that one?","cn":"哎，拿定主意。你要哪一个？这个还是那个？"},{"en":"‘What did you talk about? ’ ‘Oh, this and that.’ “","cn":"你们谈什么来着？” “噢，无所不谈。”"}]},"thought":{"media":{"uk":"media/uk/thought__gb_2.mp3","us":"media/us/thought__us_2.mp3"},"oxford":{"phon":"θɔːt","pos":"noun","senses":[{"en":"something that you think of or remember","cn":"想法；看法；主意；记忆","g":"[countable]","sc":"something you think","ex":{"en":"I couldn't bear the thought of waiting any longer.","cn":"一想到要再等下去我就受不了。"}},{"en":"a person’s mind and all the ideas that they have in it when they are thinking","cn":"心思；思想","g":"[plural]","sc":"mind/ideas","ex":{"en":"This is the time of year when our thoughts turn to summer holidays.","cn":"每年这个时候我们就开始想暑假的事了。"}},{"en":"the act of thinking seriously and carefully about something","cn":"考虑；深思","g":"[uncountable]","sc":"process/act of thinking","ex":{"en":"I've given the matter careful thought.","cn":"我对这件事认真考虑过了。"}},{"en":"the power or process of thinking","cn":"思考能力；思维过程；思考；思维","g":"[uncountable]","sc":"process/act of thinking","ex":{"en":"A good teacher encourages independence of thought.","cn":"好的教师鼓励独立思考。"}},{"en":"a feeling of care or worry","cn":"关心；关怀；顾虑；忧虑","g":"[countable]","sc":"care/worry","ex":{"en":"Spare a thought for those without enough to eat this winter.","cn":"请关心一下今冬食不果腹的人。"}},{"en":"an intention or a hope of doing something","cn":"意图；打算；希望；念头","g":"[uncountable, countable]","sc":"intention","ex":{"en":"She had given up all thought of changing her job.","cn":"她打消了所有换工作的念头。"}},{"en":"ideas in politics, science, etc. connected with a particular person, group or period of history","cn":"思想；思潮","g":"[uncountable]","sc":"in politics/science, etc.","ex":{"en":"feminist thought","cn":"女权主义思想"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Thought is the past tense and past participle of think ."},{"pos":"N-COUNT 可数名词","cn":"念头;想法;主意","en":"A thought is an idea that you have in your mind.","ex":{"en":"The thought of Nick made her throat tighten","cn":"一想到尼克，她的喉咙就发紧。"}},{"pos":"N-PLURAL 复数名词","cn":"心思;思想","en":"A person's thoughts are their mind, or all the ideas in their mind when they are concentrating on one particular thing.","ex":{"en":"I jumped to my feet so my thoughts wouldn't start to wander","cn":"我跳起来，免得走神。"}},{"pos":"N-PLURAL 复数名词","cn":"(关于具体问题的)观点，看法","en":"A person's thoughts are their opinions on a particular subject.","ex":{"en":"Many of you have written to us to express your thoughts on the conflict","cn":"你们中有许多人给我们来信，表达对冲突的看法。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"斟酌;沉思","en":"Thought is the activity of thinking, especially deeply, carefully, or logically.","ex":{"en":"Alice had been so deep in thought that she had walked past her car without even seeing it","cn":"艾丽斯考虑问题入了神，连走过自己的车都没看见。"}},{"pos":"N-COUNT 可数名词","cn":"意图;希望;理由","en":"A thought is an intention, hope, or reason for doing something.","ex":{"en":"Sarah's first thought was to run back and get Max","cn":"萨拉首先想到的就是跑回去把马克斯叫来。"}},{"pos":"N-SING 单数名词","cn":"关心，善意，帮助(尤用于感谢或表达钦佩之情)","en":"A thought is an act of kindness or an offer of help; used especially when you are thanking someone, or expressing admiration of someone.","ex":{"en":"'Would you like to move into the ward?' — 'A kind thought, but no, thank you.'","cn":"“你想不想挪到病房里来？”——“哦，您太好心了，不用了，谢谢。”"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(宗教、哲学、科学、政党等的)思想体系，观念体系","en":"Thought is the group of ideas and beliefs which belongs, for example, to a particular religion, philosophy, science, or political party.","ex":{"en":"Aristotle's scientific theories dominated Western thought for fifteen hundred years","cn":"亚里士多德的科学理论统治了西方思想达 1,500 年。"}}]},"examples":[{"en":"‘Why don't you try the other key?’ ‘ That's a thought! ’ “","cn":"你为什么不试试另一把钥匙？” “这倒是个主意！”"},{"en":"I'll wait here. No, on second thoughts, I'll come with you.","cn":"我就在这儿等。不，再一想，我还是跟你一起走。"}],"base":"think"},"throughout":{"media":{"uk":"media/uk/throughout__gb_1.mp3","us":"media/us/throughout__us_1.mp3"},"oxford":{"phon":"θruːˈaʊt","pos":"preposition, adverb","senses":[{"en":"in or into every part of something","cn":"各处；遍及","ex":{"en":"They export their products to markets throughout the world.","cn":"他们把产品出口到世界各地的市场。"}},{"en":"during the whole period of time of something","cn":"自始至终；贯穿整个时期","ex":{"en":"The museum is open daily throughout the year.","cn":"这个博物馆一年到头每天都开放。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"自始至终;从头到尾;贯穿","en":"If you say that something happens throughout a particular period of time, you mean that it happens during the whole of that period.","ex":{"en":"The national tragedy of rival groups killing each other continued throughout 1990","cn":"敌对派别相互残杀的国家悲剧 1990 年全年都在上演。"}},{"pos":"PREP 介词","cn":"遍及;遍布","en":"If you say that something happens or exists throughout a place, you mean that it happens or exists in all parts of that place.","ex":{"en":"'Sight Savers', founded in 1950, now runs projects throughout Africa, the Caribbean and South East Asia","cn":"创始于 1950 年的国际防盲及救盲组织如今在非洲、加勒比海地区和东南亚各地都开展项目。"}}]},"examples":[{"en":"The ceremony lasted two hours and we had to stand throughout.","cn":"仪式进行了两个小时，我们自始至终都得站着。"},{"en":"They export their products to markets throughout the world.","cn":"他们把产品出口到世界各地的市场。"}]},"theme":{"media":{"uk":"media/uk/theme__gb_1.mp3","us":"media/us/theme__us_1.mp3"},"oxford":{"phon":"θiːm","pos":"noun","senses":[{"en":"the subject or main idea in a talk, piece of writing or work of art","cn":"（演讲、文章或艺术作品的）题目，主题，主题思想","lab":"US English","ex":{"en":"the central/main/key/major theme","cn":"中心主题；主要思想；关键／重要主题"}},{"en":"a short tune that is repeated or developed in a piece of music","cn":"（乐曲的）主题，主旋律","lab":"music","ex":{"en":"The trumpets' theme is then taken up by the rest of orchestra.","cn":"接着由乐队其他人员演奏小号主旋律。"}},{"en":"music that is played at the beginning and end and/or is often repeated in a film, television programme, etc.","cn":"（电影、电视节目的）主题音乐","g":"[countable]","ex":{"en":"the theme from ‘The Godfather’","cn":"《教父》的主题音乐"}},{"en":"a short piece of writing on a particular subject, done for school","cn":"（学生的）作文","lab":"North American English, old-fashioned，，"},{"en":"the part of a sentence or clause that contains information that is not new to the reader or audience","cn":"（句子的）主位；词干；主题","lab":"linguistics"},{"en":"a pub, bar, etc. that is designed to reflect a particular subject or period of history","cn":"（反映某主题或历史时期的）主题酒馆（或酒吧、餐馆等）","ex":{"en":"an Irish theme pub","cn":"爱尔兰主题酒馆"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(作品、谈话、讨论的)主题，题目","en":"A theme in a piece of writing, a talk, or a discussion is an important idea or subject that runs through it.","ex":{"en":"The theme of the conference is renaissance Europe","cn":"大会的主题是文艺复兴时期的欧洲。"}},{"pos":"N-COUNT 可数名词","cn":"(艺术品、文学作品的)主题，中心思想","en":"A theme in an artist's work or in a work of literature is an idea in it that the artist or writer develops or repeats.","ex":{"en":"The novel's central theme is the perennial conflict between men and women","cn":"小说的主题是男人和女人之间永无休止的冲突。"}},{"pos":"N-COUNT 可数名词","cn":"(音乐的)主旋律","en":"A theme is a short simple tune on which a piece of music is based.","ex":{"en":"...variations on themes from Mozart's The Magic Flute.","cn":"莫扎特的《魔笛》中主旋律的变奏曲"}},{"pos":"N-COUNT 可数名词","cn":"(电影、电视节目、广播节目的)主题音乐，主题曲","en":"Theme music or a theme song is a piece of music that is played at the beginning and end of a film or of a television or radio programme.","ex":{"en":"...the theme from Dr Zhivago","cn":"电影《日瓦戈医生》的主题曲"}}]},"examples":[{"en":"The President stressed a favourite campaign theme — greater emphasis on education.","cn":"总统强调了最受人欢迎的竞选主题 — 更加重视教育。"},{"en":"The stories are all variations on the theme of unhappy marriage.","cn":"这些故事讲来讲去无非是这样那样的不幸婚姻。"}]},"threat":{"media":{"uk":"media/uk/threat__gb_1.mp3","us":"media/us/threat__us_1.mp3"},"oxford":{"phon":"θret","pos":"noun","senses":[{"en":"a statement in which you tell somebody that you will punish or harm them, especially if they do not do what you want","cn":"威胁；恐吓","g":"[countable, uncountable]","ex":{"en":"to make threats against somebody","cn":"对某人进行威胁"}},{"en":"the possibility of trouble, danger or disaster","cn":"凶兆；不祥之兆","g":"[uncountable, countable, usually singular]","ex":{"en":"These ancient woodlands are under threat from new road developments.","cn":"新道路的修建可能对这些古老的林地造成破坏。"}},{"en":"a person or thing that is likely to cause trouble, danger, etc.","cn":"构成威胁的人；形成威胁的事物","g":"[countable, usually singular]","ex":{"en":"Drugs pose a major threat to our society.","cn":"毒品对社会构成重大威胁。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"构成威胁的人(或事物);祸根","en":"A threat to a person or thing is a danger that something unpleasant might happen to them. A threat is also the cause of this danger.","ex":{"en":"Some couples see single women as a threat to their relationships","cn":"有些夫妇把单身女人看成是对他们婚姻的威胁。"}},{"pos":"N-COUNT 可数名词","cn":"威胁;恐吓","en":"A threat is a statement by someone that they will do something unpleasant, especially if you do not do what they want.","ex":{"en":"He may be forced to carry out his threat to resign","cn":"他也许会被迫把自己的辞职威胁付诸行动。"}},{"pos":"PHRASE 短语","cn":"受到威胁","en":"If a person or thing is under threat, there is a danger that something unpleasant might be done to them, or that they might cease to exist.","ex":{"en":"His position as leader will be under threat at a party congress due next month","cn":"在定于下月举行的党代表大会上，他的领导地位将受到威胁。"}}]},"examples":[{"en":"He is unlikely to be a threat to the Spanish player in the final.","cn":"相信他不会在决赛中对这位西班牙运动员形成威胁。"},{"en":"These ancient woodlands are under threat from new road developments.","cn":"新道路的开发可能对这些古老的林地造成破坏。"}]},"there":{"media":{"uk":"media/uk/there__gb_1.mp3","us":"media/us/there__us_1.mp3"},"oxford":{"phon":"ðeə(r)","pos":"adverb","senses":[{"en":"used to show that something exists or happens","cn":"（表示存在或发生）","lab":"informal","ex":{"en":"There's a restaurant around the corner.","cn":"拐角处有一家餐馆。"}},{"en":"in, at or to that place or position","cn":"在那里；到那里；往那里","ex":{"en":"We went on to Paris and stayed there eleven days.","cn":"我们接着去了巴黎，在那里停留了十一天。"}},{"en":"existing or available","cn":"存在的；现有的；可得到的","ex":{"en":"I went to see if my old school was still there.","cn":"我去看过母校是否依然存在。"}},{"en":"at that point (in a story, an argument, etc.)","cn":"（故事、辩论等）在那一点上","ex":{"en":"‘I feel…’ There she stopped.","cn":"“我觉得…”她说到那儿停了下来。"}},{"en":"used to attract somebody’s attention","cn":"（用以引起注意）喂，嘿","ex":{"en":"Hello, there!","cn":"喂，你好！"}},{"en":"used to attract somebody’s attention to a particular person, thing or fact","cn":"（用以引起对某人、事物或事实的注意）","lab":"humorous","ex":{"en":"There's the statue I was telling you about.","cn":"那就是我跟你们讲过的塑像。"}},{"en":"used to show the role of a person or thing in a situation","cn":"（表示人或事物在某一情况中的作用）","ex":{"en":"The fact is, they're there to make money.","cn":"真实的情况是，他们去那儿是为了赚钱。"}},{"en":"used to show that you are satisfied that you were right about something or to show that something annoys you","cn":"（表示因说中某事而感到满意或表示烦恼）你瞧，好啦，得啦","ex":{"en":"There now! What did I tell you? (= you can see that I was right)","cn":"你瞧！我跟你说什么来着？"},"pos":"exclamation"},{"en":"used to show that something annoys you","cn":"（表示烦恼）瞧你，得啦","ex":{"en":"There! You've gone and woken the baby!","cn":"瞧！你一去就把孩子弄醒了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"PRON 代词","cn":"(作动词 be 的主语，表示存在与否或引起注意)","en":"There is used as the subject of the verb 'be' to say that something exists or does not exist, or to draw attention to it.","ex":{"en":"There are roadworks between Camblesforth and Carlton","cn":"坎布斯福斯和卡尔顿之间的道路在施工。"}},{"pos":"PRON 代词","cn":"(用在某些动词前表示某事物存在、发展或可见，动词的单复数取决于其后的名词)","en":"You use there in front of certain verbs when you are saying that something exists, develops, or can be seen. Whether the verb is singular or plural depends on the noun which follows the verb.","ex":{"en":"There remains considerable doubt over when the intended high-speed rail link will be complete","cn":"人们对于拟建的高速铁路何时能竣工仍存有很大疑问。"}},{"pos":"CONVENTION 惯用语","cn":"(用于 hello 或 hi 之后作为问候语)","en":"There is used after 'hello' or 'hi' when you are greeting someone.","ex":{"en":"'Hello there,' said the woman, smiling at them. — 'Hi!' they chorused","cn":"“嘿，你们好！”那个女人笑着对他们说。——“你好！”他们齐声说。"}},{"pos":"ADV 副词","cn":"存在地;现有地;可得到地","en":"If something is there, it exists or is available.","ex":{"en":"The group of old buildings on the corner by the main road is still there today","cn":"大路拐角处的古老建筑群如今还在。"}},{"pos":"ADV 副词","cn":"那儿(指已经提及的地方)","en":"You use there to refer to a place which has already been mentioned.","ex":{"en":"The next day we drove the 33 miles to Siena (the Villa Arceno is a great place to stay while you are there) for the Palio","cn":"第二天，我们驱车 33 英里来到锡耶纳参加赛马节(此地的阿尔希诺山庄是个好地方，值得一去)。"}},{"pos":"ADV 副词","cn":"那儿，那边(表示用手指向的或目视的地方)","en":"You use there to indicate a place that you are pointing to or looking at, in order to draw someone's attention to it.","ex":{"en":"There it is, on the corner over there","cn":"在那儿呢，在那边那个角上。"}},{"pos":"ADV 副词","cn":"(用于 there he was 或 there we were 等表达方式中，用以概括故事或为了制造特殊效果放慢故事的节奏)","en":"You use there in expressions such as 'there he was' or 'there we were' to sum up part of a story or to slow a story down for dramatic effect.","ex":{"en":"So there we were with Amy and she was driving us crazy","cn":"就这样，我们和埃米到了一起，而她快把我们逼疯了。"}},{"pos":"ADV 副词","cn":"…在吗(电话用语)","en":"You use there when speaking on the telephone to ask if someone is available to speak to you.","ex":{"en":"Hello, is Gordon there please?","cn":"喂，请问戈登在吗？"}},{"pos":"ADV 副词","cn":"在那一点上(指别人谈话中的某个观点)","en":"You use there to refer to a point that someone has made in a conversation.","ex":{"en":"Death is terrible. I agree with you there","cn":"死亡很可怕。这点我同意你的观点。"}},{"pos":"ADV 副词","cn":"那里，那儿(指活动、过程已经达到的阶段)","en":"You use there to refer to a stage that has been reached in an activity or process.","ex":{"en":"We are making further investigations and will take the matter from there","cn":"我们正在进一步调查，将从那儿入手。"}},{"pos":"ADV 副词","cn":"(表示取得圆满成功)","en":"You use there to indicate that something has reached a point or level which is completely successful.","ex":{"en":"We had hoped to fill the back page with extra news; we're not quite there yet","cn":"我们本来希望补充一些新闻把最后一版填满，可是现在差得还很远。"}},{"pos":"ADV 副词","cn":"别无他法;无计可施;只能这样了","en":"You can use there in expressions such as there you go or there we are when accepting that an unsatisfactory situation cannot be changed.","ex":{"en":"I'm the oldest and, according to all the books, should be the achiever, but there you go","cn":"我岁数最大，无论怎么说，都应该有所成就了，可是你看看我这个样子。"}},{"pos":"ADV 副词","cn":"我讲的没错吧;我说对了吧","en":"You can use there in expressions such as there you go and there we are when emphasizing that something proves that you were right.","ex":{"en":"You see? There you go. That's why I didn't mention it earlier. I knew you'd take it the wrong way","cn":"你看，我说的没错吧？这就是为什么我早没提。我就知道你会误解。"}},{"pos":"PHRASE 短语","cn":"话说回来;再说了;不过","en":"You use there again to introduce an extra piece of information which either contradicts what has been said or gives an alternative to it.","ex":{"en":"At 18 stone, I can't run around the way I used to. There again, some people say I never did","cn":"我现在体重18英石，不能像从前那样跑来跑去了;不过有人说我以前就跑不动。"}},{"pos":"PHRASE 短语","cn":"又来了;又来这套","en":"Phrases such as there you go again are used to show annoyance at someone who is repeating something that has annoyed you in the past.","ex":{"en":"'There you go again, upsetting the child!' said Shirley","cn":"“瞧，又来了不是？又惹孩子伤心！”雪莉说。"}},{"pos":"PHRASE 短语","cn":"就这样定了;别说了","en":"You can add 'so there' to what you are saying to show that you will not change your mind about a decision you have made, even though the person you are talking to disagrees with you.","ex":{"en":"'Take That' are the best group in the whole world. So there","cn":"“接招”乐队是世界上最好的组合，就是这样的。"}},{"pos":"PHRASE 短语","cn":"立即;立刻","en":"If something happens there and then or then and there, it happens immediately.","ex":{"en":"Many felt that he should have resigned there and then","cn":"许多人觉得他应该当场辞职。"}},{"pos":"CONVENTION 惯用语","cn":"好了，好了(用于安慰他人，尤其是儿童)","en":"You say 'there there' to someone who is very upset, especially a small child, in order to comfort them.","ex":{"en":"'There, there,' said Mum. 'You've been having a really bad dream.'","cn":"“好了，好了，”妈妈说，“你只是做了一个很可怕的噩梦。”"}},{"pos":"CONVENTION 惯用语","cn":"给你;拿去吧","en":"You say 'there you are' or 'there you go' when you are offering something to someone.","ex":{"en":"Nora picked up the boy, and gave him a biscuit. 'There you are, Lennie, you take the nice biscuit.'","cn":"诺拉抱起那个男孩，给他一块饼干，说：“伦尼，给，拿着这块好吃的饼干。”"}},{"pos":"PHRASE 短语","cn":"(尤指困难时)帮助，支持","en":"If someone is there for you, they help and support you, especially when you have problems.","ex":{"en":"Despite what happened in the past I want her to know I am there for her.","cn":"无论过去发生过什么，我希望她知道，我是支持她的。"}}]},"examples":[{"en":"Not Spain again! Been there, done that, got the T-shirt.","cn":"别再去西班牙了！去过那儿了，连纪念 T 恤都买了，没劲。"},{"en":"I left in 2008 and I haven't been back there since.","cn":"我于 2008 年离开那里，从那以后再也没有回去过。"}]},"thin":{"media":{"uk":"media/uk/thin__gb_1.mp3","us":"media/us/thin__us_1.mp3"},"oxford":{"phon":"θɪn","pos":"adjective","senses":[{"en":"having a smaller distance between opposite sides or surfaces than other similar objects or than normal","cn":"薄的；细的","sc":"not thick","ex":{"en":"Cut the vegetables into thin strips.","cn":"把菜切成细条。"}},{"en":"not covered with much fat or muscle","cn":"瘦的","lab":"sometimes disapproving","sc":"not fat","ex":{"en":"He was tall and thin, with dark hair.","cn":"他又高又瘦，满头黑发。"}},{"en":"not growing closely together or in large amounts","cn":"稀少的；稀疏的","sc":"hair","ex":{"en":"thin grey hair","cn":"稀疏的花白头发"}},{"en":"containing more liquid than is normal or expected","cn":"稀薄的；淡的","sc":"liquid","ex":{"en":"The sauce was thin and tasteless.","cn":"这酱汁淡而无味。"}},{"en":"fairly easy to see through","cn":"能见度较高的；稀薄的","sc":"smoke","ex":{"en":"They fought their way through where the smoke was thinner.","cn":"他们挣扎着从烟雾稀薄的地方逃了出去。"}},{"en":"containing less oxygen than normal","cn":"稀薄的；含氧少的","sc":"air","ex":{"en":"Humans would not be able to survive in the thin atmosphere of the planet.","cn":"人类将无法在地球稀薄的大气层中生存。"}},{"en":"high and weak","cn":"微弱的；尖细的；有气无力的","lab":"disapproving","sc":"sound","ex":{"en":"Her thin voice trailed off into silence.","cn":"她的声音越来越弱直至毫无声息。"}},{"en":"not sincere or enthusiastic","cn":"不真心实意的；冷淡的","sc":"smile","ex":{"en":"He gave a thin smile.","cn":"他淡然一笑。"}},{"en":"not very bright","cn":"微弱的；暗淡的","sc":"light","ex":{"en":"the thin grey light of dawn","cn":"浅灰色的晨曦"}},{"en":"of poor quality; without an important quality","cn":"质量差的；空乏的；拙劣的","sc":"poor quality","ex":{"en":"a thin excuse (= one that people are not likely to believe)","cn":"站不住脚的借口"}},{"en":"in a way that produces a thin piece or layer of something","cn":"薄薄地","ex":{"en":"Don't spread it too thin.","cn":"不要涂得太薄。"},"pos":"adverb"},{"en":"to make a liquid less thick or strong by adding water or another substance","cn":"（掺水等）使稀薄，使变淡","g":"[transitive]","sc":"liquid","ex":{"en":"Thin the paint with water.","cn":"用水把颜料调稀。"},"pos":"verb"},{"en":"to become less thick","cn":"变稀疏；变稀少","g":"[intransitive]","sc":"of hair","ex":{"en":"a middle-aged man with thinning hair","cn":"头发逐渐稀少的中年男子"},"pos":"verb"},{"en":"to become less thick or fewer in number; to make something less thick or fewer, for example by removing some things or people","cn":"（使）变稀薄，变稀疏，变少","g":"[intransitive, transitive]","sc":"become less thick","ex":{"en":"The clouds thinned and the moon shone through.","cn":"云层渐稀，透出了月光。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"窄的;细的","en":"Something that is thin is much narrower than it is long.","ex":{"en":"A thin cable carries the signal to a computer","cn":"一根细电缆将信号传送给一台计算机。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人、动物)瘦的","en":"A person or animal that is thin has no extra fat on their body .","ex":{"en":"He was a tall, thin man with grey hair","cn":"他是个瘦高个，头发灰白。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(纸、布等)薄的","en":"Something such as paper or cloth that is thin is flat and has only a very small distance between its two opposite surfaces.","ex":{"en":"...a small, blue-bound book printed in fine type on thin paper","cn":"一本用纸轻薄、字体精细的蓝皮小书"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(液体)稀的，淡的","en":"Liquids that are thin are weak and watery.","ex":{"en":"The soup was thin and clear, yet mysteriously rich","cn":"汤又稀又清，味道却出奇地浓。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人群、观众)稀少的，稀疏的","en":"A crowd or audience that is thin does not have many people in it.","ex":{"en":"The crowd, which had been thin for the first half of the race, had now grown considerably.","cn":"比赛前半段观众还稀稀拉拉的，这时明显增多了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(微笑)冷淡的，牵强的，不幽默的","en":"A thin smile is one that is not friendly or humorous.","ex":{"en":"All she could manage was a thin, wan smile.","cn":"她极力挤出了一丝勉强的苦笑。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣物)薄的，单薄的","en":"Thin clothes are made from light cloth and are not warm to wear.","ex":{"en":"Her gown was thin, and she shivered, partly from cold.","cn":"她的礼服很薄，浑身在发抖，一半是冻的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(论点、解释)浅薄的，不足信的，说服力差的","en":"If you describe an argument or explanation as thin, you mean that it is weak and difficult to believe.","ex":{"en":"However, the evidence is thin and, to some extent, ambiguous","cn":"然而，这个证据难以令人信服，而且有点模棱两可。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)尖声尖气的，尖细的","en":"A voice or sound that is thin is high-pitched and not very loud.","ex":{"en":"Her thin voice rose high in complaint.","cn":"她抱怨时抬高了尖细的嗓音。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(头发)稀疏的","en":"If someone's hair is described as thin, they do not have a lot of hair.","ex":{"en":"She had pale thin yellow hair she pulled back into a bun.","cn":"她把一头稀疏的浅黄色头发向后梳，挽成了个圆髻。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)变稀疏","en":"When you thin something or when it thins, it becomes less crowded because people or things have been removed from it.","ex":{"en":"It would have been better to have thinned the trees over several winters rather than all at one time","cn":"当初要是分几个冬天疏剪树木，会比一下子疏剪完效果好。"}},{"pos":"VERB 动词","cn":"使（调味汁或液体）变稀薄;使变淡","en":"To thin a sauce or liquid means to make it weaker and more watery by adding another liquid to it.","ex":{"en":"It may be necessary to thin the sauce slightly","cn":"可能有必要将酱汁稍稍稀释一下。"}},{"pos":"VERB 动词","cn":"(男子的头发)变稀疏，脱落","en":"If a man's hair is thinning, it has begun to fall out. thin on top→see: ;","ex":{"en":"His hair is thinning and his skin has lost all hint of youth.","cn":"他的头发开始脱落，皮肤也老化了。"}},{"pos":"PHRASE 短语","cn":"(耐心等)消磨掉，耗尽","en":"If someone's patience, for example, is wearing thin, they are beginning to become impatient or angry with someone.","ex":{"en":"Parliament has not yet begun to combat the deepening economic crisis, and public patience is wearing thin.","cn":"议会还没有着手应对日益严重的经济危机，公众日渐失去了耐心。"}},{"pos":"","cn":"","en":"on thin ice→see: ; thin air→see: ;"},{"pos":"","cn":"","en":"相关词组：thin down thin out"}]},"examples":[{"en":"Their arguments all sound a little thin to me.","cn":"他们的论据我听起来都觉得有点儿缺乏说服力。"},{"en":"They fought their way through where the smoke was thinner.","cn":"他们挣扎着从烟雾稀薄的地方逃了出去。"}]},"they'll":{"media":{"uk":"media/uk/they_ll_1_gb_1.mp3","us":"media/us/they_ll_1_us_1.mp3"},"oxford":{"phon":"ðeɪl","pos":"short form","senses":[{"en":"they will","cn":""}]},"collins":{"senses":[{"pos":"","cn":"(they will 的常用口语形式)","en":"They'll is the usual spoken form of 'they will'.","ex":{"en":"They'll probably be here Monday and Tuesday.","cn":"他们星期一和星期二可能会在这儿。"}}]},"examples":[{"en":"They’ll be tired after the long journey.","cn":"他们经过这长途旅行会很疲劳的。"}]},"thing":{"media":{"uk":"media/uk/thing__gb_1.mp3","us":"media/us/thing__us_1.mp3"},"oxford":{"phon":"θɪŋ","pos":"noun","senses":[{"en":"an object whose name you do not use because you do not need to or want to, or because you do not know it","cn":"东西；物","g":"[countable]","sc":"object","ex":{"en":"Can you pass me that thing over there?","cn":"把那边那个东西递给我好吗？"}},{"en":"an object that is not alive in the way that people and plants are","cn":"物件；物品；事物","g":"[countable]","sc":"object","ex":{"en":"Don't treat her like that—she's a person, not a thing!","cn":"别那样对待她，她是人，不是物件！"}},{"en":"objects, clothing or tools that belong to somebody or are used for a particular purpose","cn":"（个人的）用品，衣服；（某种）用具","g":"[plural]","lab":"rather informal","sc":"possessions/equipment","ex":{"en":"Shall I help you pack your things?","cn":"我帮你打点行装好吗？"}},{"en":"a fact, an event, a situation or an action; what somebody says or thinks","cn":"事实；事件；情况；行为；话语；想法","g":"[countable]","sc":"fact/event/situation/action","ex":{"en":"They talked about many things, like books, music and films.","cn":"他们谈了许多事，诸如书、音乐和电影。"}},{"en":"the general situation, as it affects somebody","cn":"形势；局面；情况；事态","g":"[plural]","lab":"rather informal","sc":"fact/event/situation/action","ex":{"en":"Things haven't gone entirely to plan.","cn":"事态没有完全按照计划发展。"}},{"en":"a quality or a concept","cn":"特征；属性；概念","g":"[countable]","sc":"quality/concept","ex":{"en":"Reality and truth are not the same thing.","cn":"现实和实情不是同一个概念。"}},{"en":"what is needed or socially acceptable","cn":"需要的东西；适当的东西；合适的东西","g":"[countable, usually singular]","sc":"what is needed/right","ex":{"en":"You need something to cheer you up—I know just the thing!","cn":"你需要点什么使你高兴起来，我知道什么正合你的需要！"}},{"en":"used to say that something is important or real","cn":"重要的事情；真实的事情","g":"[singular]","lab":"informal, humorous，，","sc":"something important","ex":{"en":"I don't understand why these corny films are still a thing in 2020.","cn":"我不明白为什么这些老掉牙的电影在 2020 年还受欢迎。"}},{"en":"used with negatives to mean ‘anything’ in order to emphasize what you are saying","cn":"任何东西（用于否定句，加强语气）","g":"[singular]","sc":"anything","ex":{"en":"I haven't got a thing to wear!","cn":"我没有一件可穿的衣服！"}},{"en":"all that can be described in a particular way","cn":"所有…的事物；凡是…的东西","g":"[plural]","lab":"formal","sc":"things of particular type","ex":{"en":"She loves all things Japanese.","cn":"凡是日本的东西她都喜欢。"}},{"en":"a living creature","cn":"生物；有生命的东西","g":"[countable]","sc":"creature","ex":{"en":"All living things are composed of cells.","cn":"所有的生物都由细胞组成。"}},{"en":"used to talk to or about a person or an animal, to show how you feel about them","cn":"（指人或动物，带感情色彩）人，家伙，东西","g":"[countable]","lab":"informal","sc":"person/animal","ex":{"en":"You silly thing!","cn":"你这个蠢货！"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(不能、不必、不愿指明的)东西，事物，特征，事情","en":"You can use thing to refer to any object, feature, or event when you cannot, need not, or do not want to refer to it more precisely.","ex":{"en":"'What's that thing in the middle of the fountain?' — 'Some kind of statue, I guess.'","cn":"“喷泉中间的那个是什么东西？”——“估计是塑像什么的吧。”"}},{"pos":"N-COUNT 可数名词","cn":"等等;…之类","en":"Thing is used in lists and descriptions to give examples or to increase the range of what you are referring to.","ex":{"en":"These are genetic disorders that only affect males normally. They are things like muscular dystrophy and haemophilia","cn":"这些遗传病通常只发生在男性身上，如肌肉萎缩、血友病等。"}},{"pos":"N-COUNT 可数名词","cn":"(用于形容词后，与其一起表示该形容词的意思)","en":"Thing is often used after an adjective, where it would also be possible just to use the adjective. For example, you can say it's a different thing instead of it's different .","ex":{"en":"Of course, literacy isn't the same thing as intelligence","cn":"当然，识字和智力是两码事。"}},{"pos":"N-SING 单数名词","cn":"(用于强调)任何事情，每件事","en":"Thing is often used instead of the pronouns 'anything,' or 'everything' in order to emphasize what you are saying.","ex":{"en":"It isn't going to solve a single thing","cn":"这什么问题也解决不了。"}},{"pos":"N-COUNT 可数名词","cn":"(尤用于否定句中，强调恶劣或困难)这种事，这种东西","en":"Thing is used in expressions such as such a thing or things like that, especially in negative statements, in order to emphasize the bad or difficult situation you are referring back to.","ex":{"en":"I don't believe he would tell Leo such a thing","cn":"我不信他会告诉利奥这种事。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指不太重要的)情况,形势,活动,想法","en":"You can use thing to refer in a vague way to a situation, activity, or idea, especially when you want to suggest that it is not very important.","ex":{"en":"I'm a bit unsettled tonight. This war thing's upsetting me","cn":"我今晚有点心神不定，这场争斗让我不安。"}},{"pos":"N-COUNT 可数名词","cn":"…之类的东西;类似于…的东西","en":"You can use thing when you are referring to something that you are uncertain or vague about, after mentioning something that it resembles or could possibly be.","ex":{"en":"She'd actually taken it home and she put it in this jar thing","cn":"她确实把它拿回了家，放在了一个罐子模样的东西里。"}},{"pos":"N-COUNT 可数名词","cn":"(用来表示将要提及重要事情或特别想要对方知道的情况)","en":"You often use thing to indicate to the person you are addressing that you are about to mention something important, or something that you particularly want them to know.","ex":{"en":"One thing I am sure of was that she was scared","cn":"有一点我能肯定，那就是她当时被吓到了。"}},{"pos":"N-COUNT 可数名词","cn":"(常用于指代刚提及的事，表示强调或提供更多信息)","en":"Thing is often used to refer back to something that has just been mentioned, either to emphasize it or to give more information about it.","ex":{"en":"Getting drunk is a thing all young men do","cn":"喝醉酒这种情况小伙子都会有。"}},{"pos":"N-COUNT 可数名词","cn":"(无生命的)物体，东西","en":"A thing is a physical object that is considered as having no life of its own.","ex":{"en":"It's not a thing, Beauchamp. It's a human being!","cn":"比彻姆，那不是一件东西，是一个人！"}},{"pos":"N-COUNT 可数名词","cn":"东西，玩意儿(表示蔑视或愤怒)","en":"Thing is used to refer to something, especially a physical object, when you want to express contempt or anger towards it.","ex":{"en":"This thing's virtually useless","cn":"这玩意儿简直一点用也没有。"}},{"pos":"N-COUNT 可数名词","cn":"家伙，东西（用以提及人或动物的某一特点，通常表示喜爱之情)","en":"You can call a person or an animal a particular thing when you want to mention a particular quality that they have and express your feelings towards them, usually affectionate feelings.","ex":{"en":"You really are quite a clever little thing","cn":"你真是个聪明的小家伙。"}},{"pos":"N-PLURAL 复数名词","cn":"衣物;财物;财产","en":"Your things are your clothes or possessions.","ex":{"en":"Sara told him to take all his things and not to return","cn":"萨拉叫他带着他的全部家当离开，再也别回来。"}},{"pos":"N-PLURAL 复数名词","cn":"(泛指)情况","en":"Things can refer to the situation or life in general and the way it is changing or affecting you.","ex":{"en":"Everyone agrees things are getting better","cn":"大家都认为，情况正在好转。"}},{"pos":"N-PLURAL 复数名词","cn":"物质生活;精神生活","en":"Things can refer to a particular aspect of life, such as the physical or spiritual aspect.","ex":{"en":"...a movement away from the things of this world to the things of the spirit","cn":"出世超凡"}},{"pos":"N-COUNT 可数名词","cn":"(难以言表的)可怕的事情，怪事，恐怖的事情","en":"You can refer to something that is too frightening, strange, or horrible to describe clearly as a thing .","ex":{"en":"...John W. Campbell, author of 'The Thing From Another World.'","cn":"约翰·W.坎贝尔，《外星来客》的作者"}},{"pos":"N-SING 单数名词","cn":"流行的东西;时尚","en":"If you say that something is the thing, you mean that it is fashionable or popular.","ex":{"en":"I feel under pressure to go out and get drunk because it's the thing to do","cn":"我感觉不得不出去喝他个一醉方休，因为流行这样。"}},{"pos":"PHRASE 短语","cn":"在各种情况下;总是","en":"In all things means in every situation and at all times.","ex":{"en":"Sara wished Franklin to follow family tradition, in this as in all things.","cn":"萨拉希望富兰克林在这件事上和所有其他事情一样，能遵循家庭传统。"}},{"pos":"PHRASE 短语","cn":"八面玲珑;四面讨好","en":"If you say that someone or something is trying to be all things to all men or to all people, you are criticizing them because they are trying to behave in a way that will please everyone, and this is impossible.","ex":{"en":"I realised I had a big problem. I wanted to be all things to all people","cn":"我意识到我有个大毛病，我总想不得罪任何人。"}},{"pos":"PHRASE 短语","cn":"做(正确或得体的)事","en":"If, for example, you do the right thing or do the decent thing in a situation, you do something which is considered correct or socially acceptable in that situation.","ex":{"en":"People want to do the right thing and buy 'green'","cn":"人们想要做正确的事，于是购买“绿色”产品。"}},{"pos":"PHRASE 短语","cn":"符合社会习俗的事","en":"If you say that something is the done thing, you mean it is the most socially acceptable way to behave.","ex":{"en":"It was not the done thing. In those days the man was supposed to be the provider.","cn":"那不符合社会习俗。在那个年代，养家的应该是男人。"}},{"pos":"PHRASE 短语","cn":"第一件事/最后一件事;一大早/临睡前","en":"If you do something first thing, you do it at the beginning of the day, before you do anything else. If you do it last thing, you do it at the end of the day, before you go to bed or go to sleep.","ex":{"en":"I'll go see her, first thing","cn":"我一早就去看她。"}},{"pos":"PHRASE 短语","cn":"对…很反感;对…有特别的感觉","en":"If you have a thing about someone or something, you have very strong feelings about them.","ex":{"en":"I had always had a thing about red hair","cn":"我一直很讨厌红头发。"}},{"pos":"PHRASE 短语","cn":"最好…，…较好(用来提出建议或评论)","en":"You say it is a good thing to do something to introduce a piece of advice or a comment on a situation or activity.","ex":{"en":"Can you tell me whether it is a good thing to prune an apple tree?","cn":"你能否告诉我该不该修剪苹果树？"}},{"pos":"PHRASE 短语","cn":"大肆渲染;小题大做;把事情闹大","en":"If you make a thing of something or make a thing about it, you talk about it or do it in an exaggerated way, so that it seems much more important than it really is.","ex":{"en":"Gossips made a big thing about him going on shopping trips with her","cn":"风言风语把他和她出去购物这件事闹得沸沸扬扬。"}},{"pos":"PHRASE 短语","cn":"(用于对比两种想法、行动、局势，强调第二种更困难、重要或极端)…是一回事","en":"You can say that the first of two ideas, actions, or situations is one thing when you want to contrast it with a second idea, action, or situation and emphasize that the second one is much more difficult, important, or extreme.","ex":{"en":"It was one thing to talk about leaving; it was another to physically walk out the door","cn":"说走容易，真要抬腿跨出门可就难了。"}},{"pos":"PHRASE 短语","cn":"一方面;一来","en":"You can say for one thing when you are explaining a statement or answering a question, to suggest that you are not giving the whole explanation or answer, and that there are other points that you could add to it.","ex":{"en":"She was a monster. For one thing, she really enjoyed cruelty","cn":"她是个恶魔。一方面，她确实以残忍为乐。"}},{"pos":"PHRASE 短语","cn":"各种原因;诸多事项","en":"You can use the expression 'one thing and another' to suggest that there are several reasons for something or several items on a list, but you are not going to explain or mention them all.","ex":{"en":"What with one thing and another, it was fairly late in the day when we returned to Shrewsbury","cn":"忙完这个又忙那个，等到我们回到什鲁斯伯里的时候，天色已经很晚了。"}},{"pos":"PHRASE 短语","cn":"没办法解释的事;赶巧发生","en":"If you say it is just one of those things you mean that you cannot explain something because it seems to happen by chance.","ex":{"en":"'I wonder why.' Mr. Dambar shrugged. 'It must be just one of those things, I guess.'","cn":"“我也不知道为啥，”丹巴先生耸了耸肩，“我想可能是赶巧了吧。”"}},{"pos":"PHRASE 短语","cn":"顺理成章;自然而然","en":"You say one thing led to another when you are explaining how something happened, but you do not really want to give the details or you think people will be able to imagine the details.","ex":{"en":"He came by on Saturday to see if she was lonely. One thing led to another and he stayed the night.","cn":"他星期六过来看看她是不是感到孤独。自然而然地，他就留下来过夜了。"}},{"pos":"PHRASE 短语","cn":"我行我素;特立独行","en":"If you do your own thing, you live, act, or behave in the way you want to, without paying attention to convention or depending on other people.","ex":{"en":"We accept the right of all men and women to do their own thing, however bizarre","cn":"我们承认所有人——无论男女——都有权以自己的方式去生活，不管其方式有多么怪异离奇。"}},{"pos":"PHRASE 短语","cn":"不复存在的事物;过去的东西","en":"If something is a thing of the past, it no longer exists or happens, or is being replaced by something new.","ex":{"en":"Painful typhoid injections are a thing of the past, thanks to the introduction of an oral vaccine","cn":"自从发明了口服疫苗后，令人痛苦的伤寒疫苗注射就成为了过去。"}},{"pos":"PHRASE 短语","cn":"幻视/幻听","en":"If you say that someone is seeing or hearing things, you mean that they believe they are seeing or hearing something that is not really there.","ex":{"en":"Dr Payne led Lana back into the examination room and told her she was seeing things","cn":"佩恩大夫把拉娜领回检查室，告诉她她有幻视。"}},{"pos":"PHRASE 短语","cn":"没有这回事;不可能的事","en":"You can say there is no such thing as something to emphasize that it does not exist or is not possible.","ex":{"en":"There really is no such thing as a totally risk-free industry","cn":"完全没有风险的行业是不存在的。"}},{"pos":"PHRASE 短语","cn":"原因是;情况是;问题是","en":"You say the thing is to introduce an explanation, comment, or opinion, that relates to something that has just been said. The thing is is often used to identify a problem relating to what has just been said.","ex":{"en":"'What does your market research consist of?' — 'Well, the thing is, it depends on our target age group.'","cn":"“你的市场调查有哪些内容？”“嗯，这个嘛，要视我们的目标年龄群体而定。”"}},{"pos":"PHRASE 短语","cn":"正是所要的;正是所需的","en":"If you say that something is just the thing or is the very thing, you are emphasizing that it is exactly what is wanted or needed.","ex":{"en":"Kiwi fruit are just the thing for a healthy snack","cn":"猕猴桃正是健康的小点心。"}},{"pos":"PHRASE 短语","cn":"十分了解;精通","en":"If you say that a person knows a thing or two about something or could teach someone a thing or two about it, you mean that they know a lot about it or are good at it.","ex":{"en":"Patricia Hewitt knows a thing or two about how to be well-organised","cn":"帕特里夏·休伊特很了解如何做到有条不紊。"}},{"pos":"","cn":"","en":"other things being equal→see: ; first things first→see: ; the real thing→see: ; the shape of things to come→see: ;"}]},"examples":[{"en":"I'm sorry my assignment isn't finished. The thing is, I've had a lot of other work this week.","cn":"对不起，我的任务没完成。主要原因是我这星期有许多其他工作要做。"},{"en":"He offered me a ride home one night, and, well, one thing led to another and now we're married!","cn":"一天晚上他让我搭车回家，唔，就这样自然发展，我们现在结婚了！"}]},"thinkings":{"lemma":"think","media":{"uk":"media/uk/thinking__gb_1.mp3","us":"media/us/thinking__us_1.mp3"}},"there's":{"media":{"uk":"media/uk/there_s_1_gb_1.mp3","us":"media/us/there_s_1_us_1.mp3"},"oxford":{"phon":"ðeəz","pos":"short form","senses":[{"en":"there is","cn":""},{"en":"there has","cn":""}]}},"thoroughly":{"media":{"uk":"media/uk/thoroughly__gb_1.mp3","us":"media/us/thoroughly__us_1.mp3"},"oxford":{"phon":"ˈθʌrəli","pos":"adverb","senses":[{"en":"very much; completely","cn":"非常；极其；彻底；完全","ex":{"en":"We thoroughly enjoyed ourselves.","cn":"我们玩得痛快极了。"}},{"en":"completely and with great attention to detail","cn":"彻底；仔细；缜密","ex":{"en":"Wash the fruit thoroughly before use.","cn":"把水果仔细清洗过后再用。"}}]},"examples":[{"en":"Wash the fruit thoroughly before use.","cn":"把水果仔细清洗过后再用。"},{"en":"The work had not been done very thoroughly.","cn":"这工作做得不太认真。"}]},"throat":{"oxford":{"phon":"θrəʊt","pos":"noun","senses":[{"en":"a passage in the neck through which food and air pass on their way into the body; the front part of the neck","cn":"咽喉；喉咙；颈前部","ex":{"en":"a sore throat","cn":"咽喉痛"}},{"en":"having the colour of throat mentioned; making a sound in the throat of the type mentioned","cn":"有…喉咙的；嗓子…的","ex":{"en":"a blue-throated macaw","cn":"一只蓝喉金刚鹦鹉"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"咽喉;喉咙;嗓子","en":"Your throat is the back of your mouth and the top part of the tubes that go down into your stomach and your lungs.","ex":{"en":"She had a sore throat","cn":"她嗓子疼。"}},{"pos":"N-COUNT 可数名词","cn":"喉部;颈前部","en":"Your throat is the front part of your neck.","ex":{"en":"His striped tie was loosened at his throat.","cn":"他的条纹领带松松地挂在脖子上。"}},{"pos":"PHRASE 短语","cn":"清嗓子","en":"If you clear your throat, you cough once in order to make it easier to speak or to attract people's attention.","ex":{"en":"Cross cleared his throat and spoke in low, polite tones.","cn":"克罗斯清了清嗓子，开始有礼貌地低声说话。"}},{"pos":"PHRASE 短语","cn":"向…反复灌输;向…不断强调;迫使…接受","en":"If you ram something down someone's throat or force it down their throat, you keep mentioning a situation or idea in order to make them accept it or believe it.","ex":{"en":"I've always been close to my dad but he's never rammed his career down my throat","cn":"我一直和爸爸很亲近，不过他从不强迫我继承他的事业。"}},{"pos":"PHRASE 短语","cn":"激烈争吵;凶猛打斗","en":"If two people or groups are at each other's throats, they are quarrelling or fighting violently with each other.","ex":{"en":"The idea that Billy and I are at each other's throats couldn't be further from the truth.","cn":"认为我和比利斗得你死我活的想法真是大错特错。"}},{"pos":"PHRASE 短语","cn":"使无法接受","en":"If something sticks in your throat, you find it unacceptable.","ex":{"en":"What sticks in my throat is that I wasn't able to win the trophy","cn":"令我耿耿于怀的是自己没能获奖。"}},{"pos":"","cn":"","en":"a lump in your throat→see: ;"}]},"media":{"uk":"media/uk/throat__gb_1.mp3","us":"media/us/throat__us_1.mp3","img":["media/ldoce/img/body.jpg"]},"examples":[{"en":"He held the knife to her throat.","cn":"他拿刀子顶着她的喉咙。"},{"en":"Their throats had been cut.","cn":"他们的咽喉被割断了。"}]},"than":{"media":{"uk":"media/uk/than__gb_1.mp3","us":"media/us/than__us_1.mp3"},"oxford":{"phon":"ðən","pos":"preposition, conjunction","senses":[{"en":"used to introduce the second part of a comparison","cn":"（用以引出比较的第二部分）比","ex":{"en":"I'm older than her.","cn":"我比她年龄大。"}},{"en":"used for comparing amounts, numbers, distances, etc.","cn":"（比较数量、距离等）多于，小于，少于","ex":{"en":"It never takes more than an hour.","cn":"所用的时间从不会超过一个小时。"}},{"en":"used in expressions showing that one thing happens straight after another","cn":"（表示一事紧跟另一事发生）就","ex":{"en":"No sooner had I sat down than there was a loud knock on the door.","cn":"我刚坐下就有人大声敲门。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"(用于形容词、副词的比较级之后，连接比较对象)比","en":"You use than after a comparative adjective or adverb in order to link two parts of a comparison.","ex":{"en":"The radio only weighs a few ounces and is smaller than a cigarette packet","cn":"这台收音机重量仅为几盎司，比香烟盒还小。"}},{"pos":"PREP 介词","cn":"(数目、数量、价值等)比…(多、少、重要或次要等)","en":"You use than when you are stating a number, quantity, or value approximately by saying that it is above or below another number, quantity, or value.","ex":{"en":"They talked on the phone for more than an hour.","cn":"他们在电话里谈了一个多小时。"}},{"pos":"CONJ-COORD 连词","cn":"与其说，而不是(连接对比的对象，以表示优先考虑等)","en":"You use than in order to link two parts of a contrast, for example in order to state a preference.","ex":{"en":"The arrangement was more a formality than a genuine partnership of two nations","cn":"这一协定与其说体现了两个国家之间真正的伙伴关系，还不如说是一种形式。"}},{"pos":"","cn":"","en":"easier said than done→see: ; less than→see: ; more than→see: ; more often than not→see: ; other than→see: ; rather than→see: ;"}]},"examples":[{"en":"I'd rather email than phone, if that's OK by you.","cn":"如果你认为可以的话，我想发电邮而不打电话。"},{"en":"You should know better than to behave like that.","cn":"你应当明白事理，不该那么不懂规矩。"}]},"thrown":{"lemma":"throw","media":{"uk":"media/uk/thrown__gb_1.mp3","us":"media/us/thrown__us_1.mp3"}},"thinner":{"oxford":{"phon":"ˈθɪnə(r)","pos":"noun","senses":[{"en":"a substance that is added to paint, varnish, etc. to make it less thick","cn":"（涂料、清漆等的）稀料，稀释剂"}]},"media":{"uk":"media/uk/thinner__gb_1.mp3","us":"media/us/thinner__us_1.mp3"}},"theoretically":{"media":{"uk":"media/uk/theoretically__gb_1.mp3","us":"media/us/theoretically__us_1.mp3"},"collins":{"senses":[{"pos":"ADV 副词","cn":"从理论上说;照理说","en":"You use theoretically to say that although something is supposed to be true or to happen in the way stated, it may not in fact be true or happen in that way.","ex":{"en":"Theoretically, the price is supposed to be marked on the shelf","cn":"照理说，价格应该标在货架上。"}}]},"examples":[{"en":"It is theoretically possible for him to overrule their decision, but highly unlikely.","cn":"按理说他可以否定他们的决定，但是可能性很小。"},{"en":"theoretically sound conclusions","cn":"理论上无懈可击的结论"}],"oxford":{"phon":"ˌθɪəˈretɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with the ideas and principles on which a particular subject is based, rather than with practice and experiment","cn":"理论上的","ex":{"en":"theoretically sound conclusions","cn":"理论上无懈可击的结论"}},{"en":"in a way that could possibly exist, happen or be true, although this is unlikely","cn":"理论上存在的；假设的","ex":{"en":"It is theoretically possible for him to overrule their decision, but highly unlikely.","cn":"按理说他可以推翻他们的决定，但可能性很小。"}}]}},"these":{"media":{"uk":"media/uk/these__gb_1.mp3","us":"media/us/these__us_1.mp3"},"collins":{"senses":[{"pos":"DET 限定词","cn":"（用于名词词组前，指代已提及的人或事物）这些","en":"You use these at the beginning of noun groups to refer to someone or something that you have already mentioned or identified.","ex":{"en":"Switch to an interest-paying current account and stay in credit. Most banks and larger building societies now offer these accounts","cn":"转成付息的活期存款账户，并保持账上有余额。多数银行和较大的购房互助会现在都能开立这种账户。"}},{"pos":"DET 限定词","cn":"(引出将要提及的人或事物)这些","en":"You use these to introduce people or things that you are going to talk about.","ex":{"en":"Your camcorder should have these basic features: autofocus, playback facility, zoom lens","cn":"你的便携式摄像机应该具备以下基本功能：自动聚焦、回放功能、变焦镜头。"}},{"pos":"DET 限定词","cn":"(口语中用来引出故事中的人或物)一些","en":"In spoken English, people use these to introduce people or things into a story.","ex":{"en":"I was on my own and these fellows came along towards me","cn":"我正一个人走着，一些家伙朝我走过来。"}},{"pos":"PRON 代词","cn":"这些，他们(用以说明或询问身份)","en":"You use these when you are identifying someone or asking about their identity.","ex":{"en":"These are my children.","cn":"这些都是我的孩子。"}},{"pos":"DET 限定词","cn":"这些(指离自己近的人或物，尤指所触碰或指向的人或物)","en":"You use these to refer to people or things that are near you, especially when you touch them or point to them.","ex":{"en":"What I try to do in putting these pictures up here is to show how varied children are in solving the problem","cn":"我把这些图片挂在这儿的目的是想展示一下孩子们解决这个问题的方法是多么千差万别。"}},{"pos":"DET 限定词","cn":"这些(用于指代认为谈话对象了解具体所指的事物，或确认双方所想的是相同的人或物)","en":"You use these when you refer to something which you expect the person you are talking to to know about, or when you are checking that you are both thinking of the same person or thing.","ex":{"en":"You know these last few months when we've been expecting it to warm up a little bit?","cn":"你知道最近这几个月我们一直盼望着天能暖和一点吧？"}},{"pos":"DET 限定词","cn":"目前;如今;这些日子","en":"You use these in the expression these days to mean 'at the present time'.","ex":{"en":"Living in Bootham these days can be depressing","cn":"如今住在布萨姆会让人心情抑郁。"}}]}},"theater":{"oxford":{"phon":"ˈθɪətə(r)","pos":"noun","senses":[{"en":"a building or an outdoor area where plays and similar types of entertainment are performed","cn":"戏院；剧场；露天剧场"},{"en":"a building in which films/movies are shown","cn":"电影院；影厅"}]}},"thousand":{"media":{"uk":"media/uk/thousand__gb_1.mp3","us":"media/us/thousand__us_1.mp3"},"oxford":{"phon":"ˈθaʊznd","pos":"number","senses":[{"en":"1 000","cn":"一千"},{"en":"a large number","cn":"数以千计的；成千上万的；许许多多的","lab":"usually informal","ex":{"en":"There were thousands of people there.","cn":"那里有成千上万的人。"}},{"en":"the numbers from 1 000 to 9 999","cn":"1 000 到 9 999 间的数目；千位数","ex":{"en":"The cost ran into the thousands.","cn":"成本达到千位数。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 1,000","en":"A thousand or one thousand is the number 1,000.","ex":{"en":"...five thousand acres","cn":"5,000 英亩"}},{"pos":"QUANT 数量词","cn":"数千;成千上万","en":"If you refer to thousands of things or people, you are emphasizing that there are very many of them.","ex":{"en":"Thousands of refugees are packed into overcrowded towns and villages","cn":"成千上万的难民涌入拥挤不堪的城镇和村庄。"}},{"pos":"","cn":"","en":"a thousand and one→see: ;"}]},"examples":[{"en":"There were thousands of people there.","cn":"那里有成千上万的人。"},{"en":"The cost ran into the thousands.","cn":"成本达到千位数。"}]},"three":{"media":{"uk":"media/uk/three__gb_1.mp3","us":"media/us/three__us_1.mp3"},"oxford":{"phon":"θriː","pos":"number","senses":[{"en":"3","cn":"三","ex":{"en":"There are only three cookies left.","cn":"只剩下三块饼干了。"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 3","en":"Three is the number 3.","ex":{"en":"We waited three months before going back to see the specialist.","cn":"我们等了 3 个月才回去见那位专家。"}}]},"examples":[{"en":"They’ve won their last three games.","cn":"他们赢了最近三场比赛。"},{"en":"We’d better go. It’s almost three (= three o'clock ) .","cn":"我们该走了。快3点了。"}]},"theoretical":{"media":{"uk":"media/uk/theoretical__gb_1.mp3","us":"media/us/theoretical__us_1.mp3"},"oxford":{"phon":"ˌθɪəˈretɪkl","pos":"adjective","senses":[{"en":"connected with the ideas and principles on which a particular subject is based, rather than with practice and experiment","cn":"理论上的","ex":{"en":"a theoretical approach","cn":"理论研究方法"}},{"en":"that could possibly exist, happen or be true, although this is unlikely","cn":"理论上存在的；假设的","ex":{"en":"It's a theoretical possibility.","cn":"这是理论上存在的可能性。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(研究、解释)理论的，理论性的","en":"A theoretical study or explanation is based on or uses the ideas and abstract principles that relate to a particular subject, rather than the practical aspects or uses of it.","ex":{"en":"...theoretical physics.","cn":"理论物理学"}},{"pos":"ADJ 形容词","cn":"理论上的;推想的","en":"If you describe a situation as a theoretical one, you mean that although it is supposed to be true or to exist in the way stated, it may not in fact be true or exist in that way.","ex":{"en":"This is certainly a theoretical risk but in practice there is seldom a problem","cn":"从理论上讲，这肯定是有风险的，可是实际上很少出问题。"}}]},"examples":[{"en":"It is theoretically possible for him to overrule their decision, but highly unlikely.","cn":"按理说他可以否定他们的决定，但是可能性很小。"},{"en":"The first year provides students with a sound theoretical basis for later study.","cn":"第一年为学生以后的学习奠定坚实的理论基础。"}]},"threading":{"lemma":"thread","media":{"uk":"media/ldoce/hwd/bre/f/ld5_threading.mp3","us":"media/ldoce/hwd/ame/f/ld5_threading.mp3"}},"thick":{"media":{"uk":"media/uk/thick__gb_1.mp3","us":"media/us/thick__us_1.mp3"},"oxford":{"phon":"θɪk","pos":"adjective","senses":[{"en":"having a larger distance between opposite sides or surfaces than other similar objects or than normal","cn":"厚的；粗的","sc":"distance between sides","ex":{"en":"a thick slice of bread","cn":"一片厚面包"}},{"en":"used to ask about or state the distance between opposite sides or surfaces","cn":"（询问或说明厚度）有…厚","sc":"distance between sides","ex":{"en":"How thick are the walls?","cn":"这些墙有多厚？"}},{"en":"growing closely together in large amounts or numbers","cn":"浓密的；稠密的；茂密的","sc":"hair/fur/trees","ex":{"en":"thick dark hair","cn":"浓密的黑发"}},{"en":"not flowing very easily","cn":"浓的；黏稠的","sc":"liquid","ex":{"en":"thick soup","cn":"浓汤"}},{"en":"difficult to see through; difficult to breathe in","cn":"能见度低的；浓的；阴霾的；浑浊的；不透气的","lab":"figurative","sc":"fog/smoke/air","ex":{"en":"The plane crashed in thick fog.","cn":"飞机在大雾中坠毁。"}},{"en":"having a large number of people or a large amount of something in one place","cn":"拥满；挤满；充满；弥漫","sc":"with large number/amount","ex":{"en":"The beach was thick with sunbathers.","cn":"海滩上密密麻麻都是晒太阳的人。"}},{"en":"an offensive way to describe somebody who is slow to learn or understand things","cn":"迟钝的；愚笨的","lab":"informal, offensive，，","sc":"stupid","ex":{"en":"I'm not completely thick, you know.","cn":"你知道，我还没有傻到家。"}},{"en":"easily recognized as being from a particular country or area","cn":"浓重的；明显的","lab":"sometimes disapproving","sc":"accent","ex":{"en":"a thick Brooklyn accent","cn":"浓重的布鲁克林口音"}},{"en":"deep and not as clear as normal, especially because of illness or emotion","cn":"嘶哑的，不清的（尤指因疾病或激动所致）","sc":"voice","ex":{"en":"His voice was thick with emotion.","cn":"他激动得连声音都嘶哑了。"}},{"en":"very friendly with somebody, especially in a way that makes other people suspect that something wrong, illegal or dishonest is involved in the situation","cn":"亲密的；十分友好的；（尤指）过于亲近的","lab":"informal","sc":"friendly with somebody","ex":{"en":"You seem to be very thick with the boss!","cn":"你好像和老板走得挺近的！"}},{"en":"in a way that produces a wide piece or deep layer of something","cn":"厚厚地","ex":{"en":"Make sure you cut the bread nice and thick.","cn":"你一定要把面包片切得厚厚的，规规整整的。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厚的;粗的","en":"Something that is thick has a large distance between its two opposite sides.","ex":{"en":"For breakfast I had a thick slice of bread and syrup","cn":"早餐我吃了一片厚厚的涂了糖浆的面包。"}},{"pos":"ADJ 形容词","cn":"宽的;深的","en":"You can use thick to talk or ask about how wide or deep something is.","ex":{"en":"The folder was two inches thick","cn":"那个文件夹有两英寸厚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"浓的;密的;密集的;茂密的","en":"If something that consists of several things is thick, it has a large number of them very close together.","ex":{"en":"She inherited our father's thick, wavy hair","cn":"她继承了我们父亲那头浓密的卷发。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"充满的;密布的","en":"If something is thick with another thing, the first thing is full of or covered with the second.","ex":{"en":"The air is thick with acrid smoke from the fires","cn":"空气中弥漫着火灾产生的刺鼻浓烟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服)厚的，厚重的，暖和的","en":"Thick clothes are made from heavy cloth, so that they will keep you warm in cold weather.","ex":{"en":"In the winter she wears thick socks, Wellington boots and gloves","cn":"冬天，她穿着厚袜子和橡胶雨靴，戴着手套。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(烟、雾、云)浓的，混浊的，能见度低的","en":"Thick smoke, fog, or cloud is difficult to see through.","ex":{"en":"The smoke was bluish-black and thick","cn":"那烟黑中带蓝，而且很浓。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(液体)浓的，稠的","en":"Thick liquids are fairly stiff and solid and do not flow easily.","ex":{"en":"They had to battle through thick mud to reach construction workers","cn":"他们只好挣扎着穿过厚厚的泥巴去找建筑工人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)不清楚的，沙哑的，低沉的","en":"If someone's voice is thick, they are not speaking clearly, for example because they are ill, upset, or drunk.","ex":{"en":"When he spoke his voice was thick with bitterness.","cn":"他说话时，声音低沉，充满痛苦。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(口音)重的，浓的","en":"A thick accent is very obvious and easy to identify.","ex":{"en":"He answered our questions in English but with a thick accent","cn":"他用英语回答了我们的问题，不过口音很重。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"笨的;蠢的","en":"If you describe someone as thick, you think they are stupid.","ex":{"en":"How could she have been so thick?","cn":"她怎么能蠢到那个地步？"}},{"pos":"PHRASE 短语","cn":"大量而迅速地;接二连三地","en":"If things happen thick and fast, they happen very quickly and in large numbers.","ex":{"en":"The rumours have been coming thick and fast","cn":"谣言接二连三地传来。"}},{"pos":"PHRASE 短语","cn":"积极从事;深度参与","en":"If you are in the thick of an activity or situation, you are very involved in it.","ex":{"en":"I enjoy being in the thick of things","cn":"我喜欢全身心投入到事情当中。"}},{"pos":"PHRASE 短语","cn":"不顾艰难险阻;历尽千辛万苦","en":"If you do something through thick and thin, you do it although the conditions or circumstances are very bad.","ex":{"en":"She'd stuck by Bob through thick and thin","cn":"她对鲍勃不离不弃，甘苦与共。"}},{"pos":"","cn":"","en":"to lay it on thick→see: ; a thick skin→see: ;"}]},"examples":[{"en":"When will you get it into your thick head that I don't want to see you again!","cn":"你那木头脑瓜什么时候才会明白我不想再见到你呢？"},{"en":"He's supported the team for over ten years through thick and thin.","cn":"十多年来，在任何情况下他都支持这个队。"}]},"that":{"media":{"uk":"media/uk/that__gb_1.mp3","us":"media/us/that__us_1.mp3"},"oxford":{"phon":"ðæt","pos":"determiner","senses":[{"en":"used for referring to a person or thing that is not near the speaker or as near to the speaker as another","cn":"（指较远的人或事物）那，那个","ex":{"en":"Look at that man over there.","cn":"瞧那边的那个男子。"}},{"en":"used for referring to somebody/something that has already been mentioned or is already known about","cn":"（指已提到过或已知的人或事物）那，那个","ex":{"en":"I was living with my parents at that time.","cn":"那时候我和父母住在一起。"}},{"en":"used for referring to a person or thing that is not near the speaker, or not as near to the speaker as another","cn":"（指较远的人或事物）那，那个","lab":"British English","ex":{"en":"Who's that?","cn":"那是谁？"},"pos":"pronoun"},{"en":"used for referring to somebody/something that has already been mentioned, or is already known about","cn":"（指已提到过或已知的人或事物）那，那个","ex":{"en":"What can I do about that?","cn":"那事我可怎么办？"},"pos":"pronoun"},{"en":"used for referring to people or things of a particular type","cn":"（特指）那，那种，那些","lab":"formal","ex":{"en":"Those present were in favour of change.","cn":"在座的人都赞成变革。"},"pos":"pronoun"},{"en":"used as a relative pronoun to introduce a part of a sentence which refers to the person, thing or time you have been talking about","cn":"（用作关系代词，引导从句）","ex":{"en":"Where's the letter that came yesterday?","cn":"昨天来的信在哪儿？"},"pos":"pronoun"},{"en":"used after some verbs, adjectives and nouns to introduce a new part of the sentence","cn":"（用于某些动词、形容词和名词后，引出从句）","ex":{"en":"She said (that) the story was true.","cn":"她说这件事是真的。"},"pos":"conjunction"},{"en":"used to express a result","cn":"（表示结果）如此…以致","ex":{"en":"She was so tired (that) she couldn’t think straight.","cn":"她累得昏头昏脑。"},"pos":"conjunction"},{"en":"used for expressing a hope or a wish","cn":"（表示希望或愿望）多么","lab":"literary","ex":{"en":"Oh that I could see him again!","cn":"啊，我多么想能再看到他！"},"pos":"conjunction"},{"en":"to such a degree; so","cn":"那样；那么","ex":{"en":"I can't walk that far (= as far as that).","cn":"我走不了那么远。"},"pos":"adverb"},{"en":"used when saying how much or showing how long, big, etc. something is with your hands","cn":"（以手势表示长度、大小等时用）那样，那么","ex":{"en":"It's about that long.","cn":"大约有那么长。"},"pos":"adverb"},{"en":"not very, or not as much as has been said","cn":"不很；不那么","ex":{"en":"It isn't all that cold.","cn":"天没那么冷。"},"pos":"adverb"},{"en":"used to emphasize how much","cn":"（用以强调程度）那么","lab":"British English, informal，，","ex":{"en":"I was that scared I didn't know what to do.","cn":"我非常害怕，不知如何是好。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PRON 代词","cn":"那，那个(指代前面句子里提到的)","en":"You use that to refer back to an idea or situation expressed in a previous sentence or sentences.","ex":{"en":"They said you particularly wanted to talk to me. Why was that?","cn":"他们说你特别想和我谈谈。为什么？"}},{"pos":"DET 限定词","cn":"那个人,那个(用来指代已经提到的人或物)","en":"You use that to refer to someone or something already mentioned.","ex":{"en":"The Commissioners get between £50,000 and 60,000 a year in various allowances. But that amount can soar to 90,000 a year","cn":"委员们每年领取的各种津贴在 5 万到 6 万英镑之间，但最高可达 9 万英镑。"}},{"pos":"DET 限定词","cn":"那，那个(指已经谈到过的特定时期)","en":"When you have been talking about a particular period of time, you use that to indicate that you are still referring to the same period. You use expressions such as that morning or that afternoon to indicate that you are referring to an earlier period of the same day.","ex":{"en":"The story was published in a Sunday newspaper later that week","cn":"这篇报道于那周晚些时候刊登在一份周日报纸上。"}},{"pos":"PRON 代词","cn":"(用于 that of, that which 等短语中引出有关上文提到的某事物的更多信息，而避免重复相关名词)","en":"You use that in expressions such as that of and that which to introduce more information about something already mentioned, instead of repeating the noun which refers to it.","ex":{"en":"A recession like that of 1973–1974 could put one in ten American companies into bankruptcy","cn":"像 1973–1974 年间那样的经济衰退能让 1/10 的美国公司破产。"}},{"pos":"PRON 代词","cn":"那个，那(用于对前述内容表示同意或作出应答的词和词组前)","en":"You use that in front of words or expressions which express agreement, responses, or reactions to what has just been said.","ex":{"en":"'She said she'd met you in England.' — 'That's true.'","cn":"“她说她在英格兰见过你。”——“是的。”"}},{"pos":"DET 限定词","cn":"那一个，那个(引出将要更加详细介绍的人或物)","en":"You use that to introduce a person or thing that you are going to give details or information about.","ex":{"en":"In my case I chose that course which I considered right","cn":"至于我呢，就选择了我认为正确的那条路线。"}},{"pos":"DET 限定词","cn":"那个(指代在时间、空间上离自己稍远的人或物，尤用于指示;有两个以上的事物时，that 指较远的那个)","en":"You use that when you are referring to someone or something which is a distance away from you in position or time, especially when you indicate or point to them. When there are two or more things near you, that refers to the more distant one.","ex":{"en":"Look at that guy. He's got red socks","cn":"你看那边那个家伙，他穿着双红袜子。"}},{"pos":"PRON 代词","cn":"(用于指明或询问身份)","en":"You use that when you are identifying someone or asking about their identity.","ex":{"en":"That's my wife you were talking to","cn":"刚才和你说话的人是我老婆。"}},{"pos":"DET 限定词","cn":"(不需明确指出的情况下谈话对方即可能知道所指的人或物)那个","en":"You can use that when you expect the person you are talking to to know what or who you are referring to, without needing to identify the particular person or thing fully.","ex":{"en":"I really thought I was something when I wore that hat and my patent leather shoes","cn":"我头戴那顶帽子，脚蹬漆皮鞋，当时感觉挺像那么回事儿。"}},{"pos":"ADV 副词","cn":"不太，不那么(坏、滑稽、昂贵等)","en":"If something is not that bad, funny, or expensive for example, it is not as bad, funny, or expensive as it might be or as has been suggested.","ex":{"en":"Not even Gary, he said, was that stupid","cn":"他说，就连加里也没有那么蠢。"}},{"pos":"ADV 副词","cn":"那么，那样(用于强调感情或品质的程度之深)","en":"You can use that to emphasize the degree of a feeling or quality.","ex":{"en":"I would have walked out, I was that angry","cn":"我差点中途退席，我太生气了。"}},{"pos":"PHRASE 短语","cn":"等等;诸如此类","en":"You use and all that or and that to refer generally to everything else which is associated with what you have just mentioned.","ex":{"en":"I hate to be nasty and all that","cn":"我不想讲些难听的话什么的。"}},{"pos":"PHRASE 短语","cn":"此外，而且(用于陈述之后，修饰或强调所说的话)","en":"You use at that after a statement which modifies or emphasizes what you have just said.","ex":{"en":"Success never seems to come but through hard work, often physically demanding work at that","cn":"不付出艰苦的努力似乎就不会取得成功，而且这一努力通常要劳其筋骨。"}},{"pos":"PHRASE 短语","cn":"就是说;即;换句话说","en":"You use that is or that is to say to indicate that you are about to express the same idea more clearly or precisely.","ex":{"en":"I am a disappointing, though generally dutiful, student. That is, I do as I'm told","cn":"我虽然总的来说循规蹈矩，但依然是个令人失望的学生，就是说，叫我做什么我就做什么。"}},{"pos":"PHRASE 短语","cn":"就这样，好了(表示不必再做什么或目的已经达到)","en":"You use that's it to indicate that nothing more needs to be done or that the end has been reached.","ex":{"en":"When he left the office, that was it, the workday was over.","cn":"他一离开办公室，就此打住，一天的工作就结束了。"}},{"pos":"CONVENTION 惯用语","cn":"对，是这样(表示同意、赞许)","en":"You use that's it to express agreement with or approval of what has just been said or done.","ex":{"en":"'You got married, right?' — 'Yeah, that's it.'","cn":"“你结婚了吧？”——“嗯，结了。”"}},{"pos":"PHRASE 短语","cn":"就那样(强调某事突然发生、立即做完或过程很简单，常指未加思考、讨论)","en":"You use just like that to emphasize that something happens or is done immediately or in a very simple way, often without much thought or discussion.","ex":{"en":"Just like that, I was in love","cn":"就那样，我恋爱了。"}},{"pos":"PHRASE 短语","cn":"就这样，就这么定了(表示无能为力、无话可说)","en":"You use that's that to say there is nothing more you can do or say about a particular matter.","ex":{"en":"'Well, if that's the way you want it,' he replied, tears in his eyes, 'I guess that's that.'","cn":"“好吧，如果那就是你想要的，”他两眼含泪说道，“我想那就这样吧。”"}},{"pos":"","cn":"","en":"like that→see: ; this and that→see: ; this and that→see: ; this→see: ;"},{"pos":"CONJ-SUBORD 连词","cn":"(用于动词、形容词、名词、短语之后，引导间接引语从句)","en":"You can use that after many verbs, adjectives, nouns, and expressions to introduce a clause in which you report what someone has said, or what they think or feel.","ex":{"en":"He called her up one day and said that he and his wife were coming to New York","cn":"有一天，他给她打电话，说他和妻子要来纽约。"}},{"pos":"CONJ-SUBORD 连词","cn":"(用于“it+系动词+形容词”结构之后，表示评论)","en":"You use that after 'it' and a link verb and an adjective to comment on a situation or fact.","ex":{"en":"It's interesting that you like him","cn":"你喜欢他，这真有意思。"}},{"pos":"PRON-REL 关系代词","cn":"(引导从句，以提供更多有关谈论对象的信息)","en":"You use that to introduce a clause which gives more information to help identify the person or thing you are talking about.","ex":{"en":"...pills that will make the problem disappear.","cn":"能消除该症状的药丸"}},{"pos":"CONJ-SUBORD 连词","cn":"(用在 so，such 之后，引出结果或影响)","en":"You use that after expressions with 'so' and 'such' in order to introduce the result or effect of something.","ex":{"en":"She became so nervous that she shook violently","cn":"她太紧张了，浑身抖得厉害。"}}]},"examples":[{"en":"Do you remember when we went to Norway? That was a good trip.","cn":"你记得我们什么时候去挪威吗？那次旅行真不错。"},{"en":"You'll find her very helpful — if she's not too busy, that is.","cn":"你会觉得她很肯帮忙，那是说如果她不太忙的话。"}]},"theatrical":{"media":{"uk":"media/uk/theatrical__gb_1.mp3","us":"media/us/theatrical__us_1.mp3"},"oxford":{"phon":"θiˈætrɪkl","pos":"adjective","senses":[{"en":"connected with the theatre","cn":"戏剧的；演剧的；剧场的","g":"[only before noun]","ex":{"en":"a theatrical agent","cn":"演员经纪人"}},{"en":"deliberately attracting attention or creating a particular effect in a way that seems false","cn":"演戏似的；夸张的；做作的","lab":"often disapproving","ex":{"en":"a theatrical gesture","cn":"夸张的姿势"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"剧场的;剧院的;戏剧的","en":"Theatrical means relating to the theatre.","ex":{"en":"These are the prizes given for the most outstanding British theatrical performances of the year.","cn":"这些奖项将要颁发给本年度英国最杰出的戏剧表演作品。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(行为)夸张的，做作的，戏剧性的","en":"Theatrical behaviour is exaggerated and unnatural, and intended to create an effect.","ex":{"en":"In a theatrical gesture Glass clamped his hand over his eyes.","cn":"格拉斯做了一个夸张的手势，用一只手将双眼紧紧捂上了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"盛大的;壮观的;有戏剧效果的","en":"Theatrical can be used to describe something that is grand and dramatic, as if it is part of a performance in a theatre.","ex":{"en":"There was a theatrical air about the whole scene which had a great appeal for me","cn":"整个场面很宏大，深深吸引住了我。"}},{"pos":"N-PLURAL 复数名词","cn":"(尤指业余的)戏剧表演，娱乐表演","en":"Theatricals are performances of plays and other entertainments, especially when they are done by actors who act as a hobby rather than a profession.","ex":{"en":"I always was good at amateur theatricals.","cn":"我一向擅长业余表演。"}}]},"examples":[{"en":"a theatrical gesture","cn":"戏剧性的姿势"},{"en":"a theatrical agent","cn":"演员经纪人"}]},"thickness":{"oxford":{"phon":"ˈθɪknəs","pos":"noun","senses":[{"en":"the size of something between opposite surfaces or sides","cn":"厚；厚度；粗","g":"[uncountable, countable]","ex":{"en":"Use wood of at least 12 mm thickness.","cn":"使用至少 12 毫米厚的木材。"}},{"en":"a layer of something","cn":"层","g":"[countable]","ex":{"en":"The jacket was lined with a double thickness (= two layers) of fabric.","cn":"这件短上衣有两层衬里。"}}]},"media":{"uk":"media/uk/thickness__gb_1.mp3","us":"media/us/thickness__us_1.mp3"},"examples":[{"en":"The board is available in four thicknesses.","cn":"现有四种不同厚度的木板可供使用。"},{"en":"Use wood of at least 12 mm thickness.","cn":"使用至少 12 毫米厚的木材。"}]},"thanksgiving":{"oxford":{"phon":"ˌθæŋksˈɡɪvɪŋ","pos":"noun","senses":[{"en":"a public holiday in the US (on the fourth Thursday in November) and in Canada (on the second Monday in October), originally to give thanks to God for the harvest and for health","cn":"感恩节（美国定为十一月的第四个星期四，加拿大定为十月的第二个星期一，均为公休日）","g":"[uncountable, countable]","ex":{"en":"We always eat turkey on Thanksgiving.","cn":"我们过感恩节时总是吃火鸡。"}},{"en":"the expression of thanks to God","cn":"感恩（于上帝）","g":"[uncountable]","lab":"formal"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"感恩节(美国的公共假日，在 11 月的第四个星期四)","en":"In the United States, Thanksgiving or Thanksgiving Day is a public holiday on the fourth Thursday in November. It was originally a day when people celebrated the end of the harvest and thanked God for it.","ex":{"en":"No matter where his business took him, he always managed to be home for Thanksgiving","cn":"不管因生意关系去了什么地方，他总要赶回家过感恩节。"}}]},"media":{"uk":"media/uk/thanksgiving__gb_1.mp3","us":"media/us/thanksgiving__us_1.mp3"},"examples":[{"en":"We always eat turkey on Thanksgiving.","cn":"我们过感恩节时总是吃火鸡。"},{"en":"Are you going home for Thanksgiving?","cn":"你回家过感恩节吗？"}]},"thoughtfulness":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is kind tries to help people and make them happy or comfortable, and shows that they care about them","cn":""},{"en":"friendly and kind. Nice is very common in everyday spoken English and is often used instead of kind","cn":""}]},"examples":[{"en":"Paul is very thoughtful.","cn":"","src":"ld"},{"en":"It was really thoughtful of you to remember my birthday.","cn":"","src":"ld"}],"media":{"uk":"media/uk/thoughtfulness__gb_1.mp3","us":"media/us/thoughtfulness__us_1.mp3"},"oxford":{"phon":"ˈθɔːtflnəs","pos":"noun","senses":[{"en":"the quality of being quiet, because you are thinking","cn":"沉思的；深思的；思考的","ex":{"en":"a state of thoughtfulness","cn":"一种深思熟虑的状态"}},{"en":"the quality of thinking about and caring for other people","cn":"体贴的；关心别人的；关切的","lab":"approving","ex":{"en":"his thoughtfulness for others","cn":"他为他人着想"}},{"en":"careful thought that is put into doing something","cn":"周到：做某事时要认真思考","ex":{"en":"They were impressed by the thoughtfulness of the project.","cn":"他们对该项目的深思熟虑印象深刻。"}}]}},"theatres":{"lemma":"theatre"},"thrived":{"lemma":"thrive"},"thumped":{"lemma":"thump"},"themes":{"lemma":"theme"},"thirds":{"lemma":"third"},"that's":{"collins":{"senses":[{"pos":"","cn":"(that is 的一种口语形式)","en":"That's is a spoken form of 'that is'."}]}},"thousands":{"lemma":"thousand"},"thirties":{"lemma":"thirty"},"threats":{"lemma":"threat"},"thinks":{"lemma":"think"},"thronged":{"lemma":"throng"},"thieves":{"lemma":"thief"},"theorists":{"lemma":"theorist"},"thickened":{"lemma":"thicken"},"theories":{"lemma":"theory"},"things":{"oxford":{"phon":"θɪŋ","pos":"noun","senses":[{"en":"an object whose name you do not use because you do not need to or want to, or because you do not know it","cn":"东西；物"},{"en":"an object that is not alive in the way that people and plants are","cn":"物件；物品；事物"}]}},"thickener":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"增稠剂;稠化剂","en":"A thickener is a substance that is added to a liquid in order to make it stiffer and more solid.","ex":{"en":"...cornstarch, used as a thickener","cn":"用来增稠的玉米面"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a substance used to thicken a liquid 〔","cn":"使液体变稠的〕增稠剂"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41thickener.mp3","us":"media/ldoce/hwd/ame/b/thickener.mp3"},"examples":[{"en":"paint thickeners","cn":"油漆稠化剂"}],"oxford":{"phon":"ˈθɪkənə(r)","pos":"noun","senses":[{"en":"a substance used to make a liquid thicker","cn":"增稠剂","ex":{"en":"paint thickeners","cn":"油漆稠化剂"}}]}},"throb":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(身体局部)抽动，阵痛","en":"If part of your body throbs, you feel a series of strong and usually painful beats there.","ex":{"en":"His head throbbed","cn":"他的头阵阵作痛。"}},{"pos":"VERB 动词","cn":"震动作响;有规律地颤动","en":"If something throbs, it vibrates and makes a steady noise.","ex":{"en":"The engines throbbed","cn":"发动机轰隆隆地震动着。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if part of your body hurts, it feels painful","cn":""},{"en":"to hurt with a continuous pain","cn":""},{"en":"to feel a bad pain that comes and goes again in a regular and continuous way","cn":""}]},"collocations":{"phrases":["ADJ. deep, heavy | dull | steady the steady throb of the engine","VERB + THROB feel, hear","PREP. ~ of a throb of pai n"]},"media":{"uk":"media/ldoce/hwd/bre/a/throb_n0205.mp3","us":"media/ldoce/hwd/ame/5/throb1.mp3"},"examples":[{"en":"My feet were throbbing after the long walk home.","cn":"我走了很长的路回到家后，双脚阵阵作痛。"},{"en":"My headache faded to a dull throbbing.","cn":"我的头痛逐渐减轻，后来变得微微抽痛。"}],"oxford":{"phon":"θrɒb","pos":"verb","senses":[{"en":"to feel a series of regular painful movements","cn":"（有规律地）抽动，抽痛","g":"[intransitive]","ex":{"en":"His head throbbed painfully.","cn":"他的头一抽一跳地痛。"}},{"en":"to beat or sound with a strong, regular rhythm","cn":"（强烈有节奏地）跳动，搏动，震响","g":"[intransitive]","lab":"figurative","ex":{"en":"The ship's engines throbbed quietly.","cn":"船上的发动机有节奏地轻轻震动。"}},{"en":"a feeling of pain that you experience as a series of strong beats","cn":"（一阵阵的）疼痛，抽痛","g":"[singular]","ex":{"en":"My headache faded to a dull throb.","cn":"我的头痛逐渐减轻，后来变得微微抽痛。"},"pos":"noun"},{"en":"a strong, regular beat","cn":"（强烈有规律的）跳动","g":"[countable, usually singular]","ex":{"en":"the throb of the machines","cn":"机器有节奏的颤动"},"pos":"noun"}]}},"thereon":{"collins":{"senses":[{"pos":"ADV 副词","cn":"在其上","en":"Thereon means on the object or surface just mentioned.","ex":{"en":"There was a card on each door with a guest's name inscribed thereon.","cn":"每扇门上都有张卡，上面印着客人的名字。"}},{"pos":"ADV 副词","cn":"就此;与此相关","en":"Thereon can be used to refer back to a thing that has previously been mentioned to show that the word just used relates to that thing.","ex":{"en":"You will, in addition, pay to the Bank any losses, costs, expenses or legal fees (including VAT thereon).","cn":"另外，你还须向银行支付所有损失、成本、花销和法律费用(包括与此相关的增值税)。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"on the thing that has just been mentioned","cn":"在其上"},{"en":"thereupon","cn":"随即﹐立即"}]},"media":{"uk":"media/ldoce/hwd/bre/b/ld41thereon.mp3","us":"media/ldoce/hwd/ame/3/thereon.mp3"},"examples":[{"en":"a meeting to discuss the annual accounts and the auditors' report thereon","cn":"讨论年度账目及其审计报告的会议"}],"oxford":{"phon":"ˌðeərˈɒn","pos":"adverb","senses":[{"en":"on the thing mentioned","cn":"在其上","ex":{"en":"a meeting to discuss the annual accounts and the auditors’ report thereon","cn":"讨论年度报表及其审计报告的会议"}}]}},"therapy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(非药物、非手术的)疗法，治疗","en":"Therapy is the treatment of someone with mental or physical illness without the use of drugs or operations.","ex":{"en":"In therapy, she began to let go of her obsession with Mike","cn":"在接受治疗的过程中，她开始逐渐从对迈克的迷恋中解脱出来。"}},{"pos":"N-VAR 可变名词","cn":"(针对某人特定病情的)治疗方案，治疗方法","en":"A therapy is a particular treatment of someone with a particular illness.","ex":{"en":"...hormonal therapies.","cn":"激素疗法"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical method of curing someone who is ill or injured, for example by means of drugs or an operation","cn":""},{"en":"a series of treatments for a problem, especially a mental one, usually without drugs or operations","cn":""},{"en":"the science of understanding illness and injury, and the methods used for treating them","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Therapy is the act of caring for someone, or the method of caring. If you have a rare disease, your doctor's therapy will hopefully cure you."}]},"collocations":{"phrases":["ADJ. alternative, complementary | behaviour, speech | aversion, occupational, regression, relaxation, shock, etc. | family, group They discu","QUANT. course","VERB + THERAPY need, require | be given, have, receive, undergo He will have to have shock therapy. | be in, go into I went into therapy bec","THERAPY + NOUN group, session","PHRASES a form of therapy the use of hypnosis as a form of therapy"]},"media":{"uk":"media/ldoce/hwd/bre/5/therapy0205.mp3","us":"media/ldoce/hwd/ame/3/therapy.mp3"},"examples":[{"en":"Most leukaemia patients undergo some sort of drug therapy (= treatment using drugs).","cn":"大多数白血病患者都会接受某种药物治疗。"},{"en":"alternative/complementary/natural therapies (= treatments that do not use traditional drugs)","cn":"替代/补充/自然疗法"}],"oxford":{"phon":"ˈθerəpi","pos":"noun","senses":[{"en":"the treatment of a physical problem or an illness","cn":"治疗；疗法","g":"[uncountable, countable]","lab":"British English","ex":{"en":"He is receiving therapy for cancer.","cn":"他正在接受癌症治疗。"}},{"en":"the treatment of problems with somebody's mental health by talking with them","cn":"心理治疗","g":"[uncountable]","ex":{"en":"She's in therapy.","cn":"她在接受心理治疗。"}}]}},"thyroid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"甲状腺","en":"Your thyroid or your thyroid gland is a gland in your neck that produces chemicals which control the way your body grows and functions."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an organ in your neck that produces substances that affect the way your body grows and the way you behave","cn":"甲状腺"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41thyroid.mp3","us":"media/ldoce/hwd/ame/5/thyroid.mp3"},"oxford":{"phon":"ˈθaɪrɔɪd","pos":"noun","senses":[{"en":"a small organ at the front of the neck that produces hormones that control the way in which the body grows and functions","cn":"甲状腺","ex":{"en":"an underactive/overactive thyroid","cn":"甲状腺功能低下/过度活跃"}}]}},"thoroughbred":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"纯种马","en":"A thoroughbred is a horse that has parents that are of the same high quality breed."},{"pos":"N-COUNT 可数名词","cn":"良种赛马","en":"A thoroughbred is a particular breed of racing horse.","ex":{"en":"...a thoroughbred stallion.","cn":"良种牡马"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a horse that has parents of the same very good breed","cn":"纯种马"},{"en":"someone who seems to do something naturally to a very high standard","cn":"天才"}]},"media":{"uk":"media/ldoce/hwd/bre/9/thoroughbred0205.mp3","us":"media/ldoce/hwd/ame/6/thoroughbred.mp3"},"examples":[{"en":"a thoroughbred mare","cn":"纯种母马"},{"en":"a thoroughbred stallion","cn":"一匹纯种种马"}],"oxford":{"phon":"ˈθʌrəbred","pos":"adjective","senses":[{"en":"of high quality, with parents that are both of the same type","cn":"纯种动物，良种动物（尤指马）","ex":{"en":"a thoroughbred mare","cn":"纯种母马"}},{"en":"an animal, especially a horse, of high quality, that has parents that are both of the same type","cn":"纯种动物，良种动物（尤指马）","pos":"noun"}]}},"thorax":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"胸部;胸腔;胸廓","en":"Your thorax is the part of your body between your neck and your waist."},{"pos":"N-COUNT 可数名词","cn":"(昆虫的)胸部，胸节","en":"An insect's thorax is the central part of its body to which the legs and wings are attached."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of your body between your neck and diaphragm (= area just above your stomach ) 〔","cn":"人的〕胸（部）﹐胸廓"},{"en":"the part of an insect’s body between its head and its abdomen 〔","cn":"昆虫的〕胸（节）"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41thorax.mp3","us":"media/ldoce/hwd/ame/e/thorax.mp3"},"oxford":{"phon":"ˈθɔːræks","pos":"noun","senses":[{"en":"the part of the body that is surrounded by the ribs, between the neck and the waist","cn":"胸；胸腔","lab":"anatomy"},{"en":"the middle section of an insect’s body, to which the legs and wings are attached","cn":"（昆虫的）胸，胸部"}]}},"thoughtful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"沉思的;默想的;认真思考的","en":"If you are thoughtful, you are quiet and serious because you are thinking about something.","ex":{"en":"Nancy, who had been thoughtful for some time, suddenly spoke","cn":"南希沉思了一会儿，突然开口说话了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"体贴入微的;考虑周到的","en":"If you describe someone as thoughtful, you approve of them because they remember what other people want, need, or feel, and try not to upset them.","ex":{"en":"...a thoughtful and caring man","cn":"体贴入微、关心他人的男人"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(书籍、电影、讲话等)严肃的，思想性强的","en":"If you describe something such as a book, film, or speech as thoughtful, you mean that it is serious and well thought out.","ex":{"en":"...a thoughtful and scholarly book.","cn":"一本兼具思想性和学术性的书"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is kind tries to help people and make them happy or comfortable, and shows that they care about them","cn":""},{"en":"friendly and kind. Nice is very common in everyday spoken English and is often used instead of kind","cn":""},{"en":"kind because you give people money, presents etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You are thoughtful if you consider how your actions and words will affect other people’s feelings. It is thoughtful to cook your friend's favorite dish when you invite him over for dinner."}]},"media":{"uk":"media/ldoce/hwd/bre/1/thoughtful0205.mp3","us":"media/ldoce/hwd/ame/2/thoughtful.mp3"},"examples":[{"en":"a player who has a thoughtful approach to the game","cn":"对这场比赛缜密研究过对策的运动员"},{"en":"She used the towel thoughtfully provided by her host.","cn":"她用了主人特意为她准备的毛巾。"}],"oxford":{"phon":"ˈθɔːtfl","pos":"adjective","senses":[{"en":"quiet, because you are thinking","cn":"沉思的；深思的；思考的","ex":{"en":"He looked thoughtful.","cn":"他一脸沉思的神情。"}},{"en":"showing that you think about and care for other people","cn":"体贴的；关心别人的；关切的","lab":"approving","ex":{"en":"The hotel manager was very kind and thoughtful.","cn":"酒店经理非常友善和周到。"}},{"en":"showing signs of careful thought","cn":"缜密思考过的；深思熟虑的","ex":{"en":"a player who has a thoughtful approach to the game","cn":"对这场比赛缜密研究过对策的运动员"}}]}},"thaw":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(冰雪等)融化，融解，解冻","en":"When ice, snow, or something else that is frozen thaws, it melts.","ex":{"en":"It's so cold the snow doesn't get a chance to thaw","cn":"天太冷了，雪根本化不了。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指冬末的)解冻时节，天气回暖期","en":"A thaw is a period of warmer weather when snow and ice melt, usually at the end of winter.","ex":{"en":"We slogged through the mud of an early spring thaw.","cn":"我们在初春解冻时节的泥泞中艰难行进。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(冷冻食品)解冻，融化","en":"When you thaw frozen food or when it thaws, you leave it in a place where it can reach room temperature so that it is ready for use.","ex":{"en":"Always thaw pastry thoroughly","cn":"每次都要保证油酥面团彻底解冻。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(关系)回暖，缓和，改善","en":"If something thaws relations between people or if relations thaw, they become friendly again after a period of being unfriendly.","ex":{"en":"At least this second meeting had helped to thaw the atmosphere","cn":"这第二次会议至少起到了缓和气氛的作用。"}},{"pos":"","cn":"","en":"相关词组：thaw out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if something solid melts or if heat melts it, it becomes liquid","cn":""},{"en":"if something solid dissolves or if you dissolve it, it is added to a liquid and mixed with it, so that it become liquid itself","cn":""},{"en":"if ice, snow, or a frozen lake or river thaws , it becomes a liquid because the temperature has become warmer","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"When things thaw , they're coming out of deep freeze and warming up. You can thaw a chicken, and a chilly friendship can thaw too."}]},"collocations":{"phrases":["ADV. completely Make sure the meat has thawed completely before cooking. | a little (figurative) Relations between the two countries thawed "]},"media":{"uk":"media/ldoce/hwd/bre/7/thaw_v0205.mp3","us":"media/ldoce/hwd/ame/9/thaw1.mp3"},"examples":[{"en":"I could feel my ears and toes start to thaw out.","cn":"我觉得耳朵和脚趾暖和过来了。"},{"en":"It's starting to thaw.","cn":"天气转暖，冰雪开始融化了。"}],"oxford":{"phon":"θɔː","pos":"verb","senses":[{"en":"to turn back into water after being frozen","cn":"（结冰后）解冻，融化，融解","g":"[intransitive]","ex":{"en":"The country was slowly thawing out after the long cold winter.","cn":"经过漫长寒冷的冬天后，这个国家正在慢慢解冻。"}},{"en":"when it thaws or is thawing, the weather becomes warm enough to melt snow and ice","cn":"天气暖和得使冰雪融化（或解冻）","g":"[intransitive]","ex":{"en":"It's starting to thaw.","cn":"冰雪开始融化了。"}},{"en":"to become, or to let frozen food become, soft or liquid ready for cooking","cn":"（使冷冻食品）化冻","g":"[intransitive, transitive]","ex":{"en":"Leave the meat to thaw completely before cooking.","cn":"让冻肉完全化冻后再烹煮。"}},{"en":"to become, or make something become, a normal temperature after being very cold","cn":"（使）回到正常温度，变暖","g":"[intransitive, transitive]","ex":{"en":"I could feel my ears and toes start to thaw out.","cn":"我觉得耳朵和脚趾暖和过来了。"}},{"en":"to become more friendly and less formal","cn":"变得友好（或随和、不拘束）","g":"[intransitive]","ex":{"en":"Relations between the two countries thawed a little after the talks.","cn":"谈判后两国关系缓和了些。"}},{"en":"a period of warmer weather following one of cold weather, causing snow and ice to melt","cn":"解冻时期；融化季节","g":"[countable, usually singular]","ex":{"en":"The river doubles in size during the spring thaw.","cn":"这条河的水量在春季解冻期会增加一倍。"},"pos":"noun"},{"en":"a situation in which the relations between two enemy countries become more friendly","cn":"（敌对国家之间）关系缓和","g":"[singular]","ex":{"en":"a thaw in relations with the West","cn":"与西方关系的解冻"},"pos":"noun"}]}},"thinker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"思考者;(尤指)思想家","en":"A thinker is a person who spends a lot of time thinking deeply about important things, especially someone who is famous for thinking of new or interesting ideas.","ex":{"en":"...some of the world's greatest thinkers.","cn":"世界上一些最伟大的思想家"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who thinks carefully about important subjects such as science or philosophy , especially someone who is famous for thinking of new ideas","cn":"思想家"},{"en":"a person who thinks in a particular way","cn":"独立思考的人/思想积极的人/思想自由的人等"}]},"vocab":{"pos":"n","senses":[{"en":"A thinker is just what it sounds like — a person who does a lot of thinking. If you're a thinker , it may take you a while to make an important decision."}]},"collocations":{"phrases":["ADJ. great, leading Einstein was one of the world's greatest thinkers. | deep, profound, serious | clear, logical | lateral | quick | creati","PREP. ~ on a leading thinker on constitutional law"]},"media":{"uk":"media/ldoce/hwd/bre/5/thinker0205.mp3","us":"media/ldoce/hwd/ame/3/laadthinker.mp3"},"examples":[{"en":"Einstein was one of the greatest thinkers of the 20th century.","cn":"爱因斯坦是 20 世纪最伟大的思想家之一。"},{"en":"a clear thinker","cn":"思路清晰的人"}],"oxford":{"phon":"ˈθɪŋkə(r)","pos":"noun","senses":[{"en":"a person who thinks seriously, and often writes about important things, such as philosophy or science","cn":"思想家","ex":{"en":"Einstein was one of the greatest thinkers of the 20th century.","cn":"爱因斯坦是 20 世纪最伟大的思想家之一。"}},{"en":"a person who thinks in a particular way","cn":"思想…的人","ex":{"en":"a clear thinker","cn":"思路清晰的人"}}]}},"thence":{"collins":{"senses":[{"pos":"ADV 副词","cn":"从那里;由此","en":"Thence means from a particular place, especially when you are giving directions about how to get somewhere.","ex":{"en":"I ran straight up to Columbia County, then turned East, came down the Harlem Valley and thence home","cn":"我一直跑到哥伦比亚县，然后向东转，沿着哈勒姆山谷，从那里回到家。"}},{"pos":"ADV 副词","cn":"然后，接着（指状态的变化）","en":"Thence is used to say that something changes from one state or condition to another.","ex":{"en":"...the conversion of sunlight into heat and thence into electricity.","cn":"将太阳能转化成热能，然后再转化成电能"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"from there or following that","cn":"从那里﹔然后"}]},"media":{"uk":"media/ldoce/hwd/bre/6/thence0205.mp3","us":"media/ldoce/hwd/ame/e/thence.mp3"},"examples":[{"en":"They made their way from Spain to France and thence to England.","cn":"他们从西班牙去了法国，再从那里去了英国。"},{"en":"He was promoted to manager, thence to a partnership in the firm.","cn":"他被提升为经理，然后又成了公司的合伙人。"}],"oxford":{"phon":"ðens","pos":"adverb","senses":[{"en":"from that place; following that","cn":"从那里；然后；随之","ex":{"en":"They made their way from Spain to France and thence to England.","cn":"他们从西班牙去了法国，再从那里去了英国。"}}]}},"throaty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(说话声或笑声)低沉的，沙哑的","en":"A throaty voice or laugh is low and rather rough."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not sounding soft or gentle, especially because the person speaking is angry or rude","cn":""},{"en":"deep and rough, as if the sounds are produced deep down in your throat","cn":""},{"en":"slightly rough, as though you have a sore throat, but also attractive and deep","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/throaty0205.mp3","us":"media/ldoce/hwd/ame/f/throaty.mp3"},"examples":[{"en":"the throaty roar of the engines","cn":"发动机的低沉轰鸣声"},{"en":"a throaty laugh","cn":"嘎嘎的笑声"}],"oxford":{"phon":"ˈθrəʊti","pos":"adjective","senses":[{"en":"sounding low and rough","cn":"声音低沉的；嘶哑的","ex":{"en":"a throaty laugh","cn":"嘎嘎的笑声"}}]}},"theocracy":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"僧侣政体;神权政体","en":"A theocracy is a society which is ruled by priests who represent a god.","ex":{"en":"...a medieval theocracy run by Buddhist monks.","cn":"中世纪僧侣掌权的神权政体"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a social system or state controlled by religious leaders","cn":"神权政治﹔神权政体"}]},"vocab":{"pos":"n","senses":[{"en":"When religious doctrine is the law of the land, most likely you're living in a theocracy . There's not a lot of room for dissent in theocracies, where priests are in charge and say they are speaking for God."}]},"media":{"uk":"media/ldoce/hwd/bre/e/theocracy0205.mp3","us":"media/ldoce/hwd/ame/6/laadtheocracy.mp3"},"examples":[{"en":"theocratic rule","cn":"神权统治"}],"oxford":{"phon":"θiˈɒkrəsi","pos":"noun","senses":[{"en":"government of a country by religious leaders","cn":"神权政治；僧侣政体","g":"[uncountable]"},{"en":"a country that is governed by religious leaders","cn":"神权国；神权政治国家","g":"[countable]"}]}},"throwaway":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"一次性的;用完即弃的","en":"A throwaway product is intended to be used only for a short time, and then to be thrown away.","ex":{"en":"Now they are producing throwaway razors.","cn":"他们正在生产一次性剃须刀。"}},{"pos":"ADJ 形容词","cn":"(讲话、动作)不经意的，随意的","en":"If you say that someone makes a throwaway remark or gesture, you mean that they make it in a casual way, although it may be important, or have some serious or humorous effect.","ex":{"en":"...a throwaway remark she later regretted","cn":"她脱口而出后就后悔的话"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that someone says or writes quickly, without thinking carefully about it","cn":"随口说出的话语﹔随意写下的内容"},{"en":"throwaway products have been produced cheaply so that you can throw them away after you have used them","cn":"用后即扔的﹐一次性使用的"},{"en":"used to show disapproval when talking about modern societies in which products are not made to last a long time","cn":"一次性物品充斥的社会〔含贬义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41throwaway.mp3","us":"media/ldoce/hwd/ame/1/throwaway.mp3"},"examples":[{"en":"She was very upset at what to him was just a throwaway remark.","cn":"对他来说这只是随口说说而已，而她听了却很不高兴。"},{"en":"We live in a throwaway society (= a society in which things are not made to last a long time).","cn":"我们生活在一次性物品充斥的社会。"}],"oxford":{"phon":"ˈθrəʊəweɪ","pos":"adjective","senses":[{"en":"something you say quickly without careful thought, sometimes in order to be funny","cn":"脱口而出的；顺嘴说出的；开玩笑的","ex":{"en":"She was very upset at what to him was just a throwaway remark.","cn":"对他来说这只是随口说说而已，而她听了却很不高兴。"}},{"en":"produced cheaply and intended to be thrown away after use","cn":"用后丢弃的；一次性使用的","ex":{"en":"throwaway products","cn":"一次性使用的产品"}}]}},"thorn":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(某些植物、树木上的)刺，棘刺","en":"Thorns are the sharp points on some plants and trees, for example on a rose bush.","ex":{"en":"Roses will always have thorns but with care they can be avoided.","cn":"玫瑰花上都有刺，不过只要小心就碰不到。"}},{"pos":"N-VAR 可变名词","cn":"荆棘;带刺的树;带刺小灌木","en":"A thorn or a thorn bush or a thorn tree is a bush or tree which has a lot of thorns on it.","ex":{"en":"...the shade of a thorn bush.","cn":"一丛荆棘下的阴凉"}},{"pos":"PHRASE 短语","cn":"肉中刺;长期困扰的问题","en":"If you describe someone or something as a thorn in your side or a thorn in your flesh, you mean that they are a continuous problem to you or annoy you.","ex":{"en":"She's a real thorn in his side","cn":"她真叫他头疼。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a sharp point that grows on the stem of a plant such as a rose 〔","cn":"玫瑰等植物茎上的〕刺"},{"en":"a bush or tree that has thorns","cn":"带刺的灌木﹐荆棘"},{"en":"someone or something that annoys you or causes problems for a long period of time","cn":"某人的肉中刺〔指长时间让你心烦或给你惹麻烦的人或事〕﹐使人苦恼[招来麻烦]的人[事]"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdethorn.mp3","us":"media/ldoce/hwd/ame/c/thorn.mp3"},"examples":[{"en":"a long, low hedge of thorns","cn":"一长排矮矮的荆棘树篱"},{"en":"He’s been a thorn in the side of the party leadership for years.","cn":"他多年来一直是该党领导人心头的一根刺。"}],"oxford":{"phon":"θɔːn","pos":"noun","senses":[{"en":"a small sharp, pointed part on the stem of some plants, such as roses","cn":"（玫瑰之类植物的）刺，棘刺"},{"en":"a tree or bush that has thorns","cn":"带刺的树；荆棘"},{"en":"the letter that was used in Old English and Icelandic to represent the sounds /θ/ and /ð/ and later written as th","cn":"刺形符，字母 ð（古英语和古冰岛语用的字母，表示 /θ/ 和 /ð/ 的发音，后书写为 th）"}]}},"thimble":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"顶针;针箍","en":"A thimble is a small metal or plastic object which you use to protect your finger when you are sewing."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small metal or plastic cap used to protect your finger when you are sewing","cn":"顶针﹐针箍"}]},"media":{"img":["media/ldoce/img/thimble.jpg"],"uk":"media/ldoce/hwd/bre/3/thimble0205.mp3","us":"media/ldoce/hwd/ame/7/thimble.mp3"},"oxford":{"phon":"ˈθɪmbl","pos":"noun","senses":[{"en":"a small metal or plastic object that you wear on the end of your finger to protect it when sewing","cn":"顶针；针箍"}]}},"therapeutic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人放松的;能解郁安神的","en":"If something is therapeutic, it helps you to relax or to feel better about things, especially about a situation that made you unhappy.","ex":{"en":"Astanga Yoga is a therapeutic physical exercise that focuses on breathing and relaxation.","cn":"八步功法瑜伽注重呼吸和放松，是一种舒缓身心的锻炼方法。"}},{"pos":"ADJ 形容词","cn":"治疗性的;有助于治疗的","en":"Therapeutic treatment is designed to treat an illness or to improve a person's health, rather than to prevent an illness.","ex":{"en":"...therapeutic drugs.","cn":"治疗性药物"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel calm and relaxed","cn":"使人镇静的﹐使人放松的"},{"en":"relating to the treatment or cure of an illness","cn":"治疗的"}]},"vocab":{"pos":"adj n","senses":[{"en":"Whether you’re talking about a therapeutic drug or a therapeutic exercise plan, something that is therapeutic helps to heal or to restore health."}]},"media":{"uk":"media/ldoce/hwd/bre/e/therapeutic0205.mp3","us":"media/ldoce/hwd/ame/6/therapeutic.mp3"},"examples":[{"en":"Painting can be very therapeutic.","cn":"绘画可以使人放松。"},{"en":"the therapeutic properties of herbs","cn":"草药的医疗效用"}],"oxford":{"phon":"ˌθerəˈpjuːtɪk","pos":"adjective","senses":[{"en":"helping to treat an illness","cn":"治疗的；医疗的；治病的","g":"[usually before noun]","ex":{"en":"the therapeutic benefits of herbs","cn":"草药的医疗益处"}},{"en":"helping you to relax","cn":"有助于放松精神的","ex":{"en":"Painting can be very therapeutic.","cn":"绘画可以使人完全放松。"}}]}},"thesaurus":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同义词典;分类词典","en":"A thesaurus is a reference book in which words with similar meanings are grouped together."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a book in which words are put into groups with other words that have similar meanings","cn":"同义词词典"}]},"vocab":{"pos":"n","senses":[{"en":"A thesaurus is a reference book (or a really cool website, like the Visual Thesaurus ) with an organized list of words and their synonyms."}]},"media":{"uk":"media/ldoce/hwd/bre/6/thesaurus0205.mp3","us":"media/ldoce/hwd/ame/a/thesaurus.mp3"},"oxford":{"phon":"θɪˈsɔːrəs","pos":"noun","senses":[{"en":"a book that lists words in groups that have similar meanings","cn":"类义词典；义类词典；同义词词典","ex":{"en":"I couldn’t find the word in the thesaurus.","cn":"我在同义词库中找不到这个词。"}}]}},"throwback":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"复古;回归","en":"If you say that something is a throwback to a former time, you mean that it is like something that existed a long time ago.","ex":{"en":"The hall is a throwback to another era with its old prints and stained-glass.","cn":"这个大厅的古老图案和彩色玻璃是对过去一个时代风格的回归。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is similar to something that existed in the past, or belongs to the past","cn":"复古的事物"}]},"media":{"uk":"media/ldoce/hwd/bre/c/throwback0205.mp3","us":"media/ldoce/hwd/ame/2/throwback.mp3"},"examples":[{"en":"The car's design is a throwback to the 1960s.","cn":"这种汽车的设计回到了 20 世纪 60 年代。"},{"en":"Her whole outfit was a throwback to the 1970s.","cn":"她的整套衣服透出了回归20世纪70年代的复古风格。"}],"oxford":{"phon":"ˈθrəʊbæk","pos":"noun","senses":[{"en":"a person or thing that is similar to somebody/something that existed in the past","cn":"返祖者；返祖；返祖型的东西","ex":{"en":"The car's design is a throwback to the 1960s.","cn":"这种汽车的设计回到了 20 世纪 60 年代。"}}]}},"throttle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"掐死;勒死;掐住…的脖子;使窒息","en":"To throttle someone means to kill or injure them by squeezing their throat or tightening something around it and preventing them from breathing.","ex":{"en":"The attacker then tried to throttle her with wire","cn":"然后袭击者企图用电线勒死她。"}},{"pos":"VERB 动词","cn":"阻挡;阻碍;压制;扼杀","en":"If you say that something or someone is throttling a process, institution, or group, you mean that they are restricting it severely or destroying it.","ex":{"en":"He said the overvaluation of sterling was throttling industry.","cn":"他认为英镑价值过高阻碍了工业发展。"}},{"pos":"N-COUNT 可数名词","cn":"(汽车、飞机的)节流阀，油门杆，油门踏板","en":"The throttle of a motor vehicle or aircraft is the device, lever, or pedal that controls the quantity of fuel entering the engine and is used to control the vehicle's speed.","ex":{"en":"He gently opened the throttle, and the ship began to ease forward","cn":"他轻轻松开油门杆，轮船开始缓缓前行。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"功率;马力","en":"Throttle is the power that is obtained by using a throttle.","ex":{"en":"...motor bikes revving at full throttle.","cn":"全速行驶的摩托车"}},{"pos":"PHRASE 短语","cn":"全速地;满怀热情地","en":"If you say that something is done at full throttle, you mean that it is done with great speed and enthusiasm.","ex":{"en":"He lived his life at full throttle.","cn":"他过着激情四射的生活。"}},{"pos":"","cn":"","en":"相关词组：throttle back"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to kill or injure someone by holding their throat very tightly so that they cannot breathe","cn":"掐﹐勒〔某人的脖子〕﹔掐死"},{"en":"to make it difficult or impossible for something to succeed","cn":"阻挡﹔压制﹔扼杀"},{"en":"to slow down the speed of an Internet connection","cn":"限制…的网速"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"The throttle of an engine controls the fuel going in, and if you're going at full throttle , you'd better hang onto your hat."}]},"media":{"uk":"media/ldoce/hwd/bre/a/throttle_v0205.mp3","us":"media/ldoce/hwd/ame/b/throttle1.mp3"},"examples":[{"en":"( humorous ) I like her, although I could cheerfully throttle her at times (= because she is annoying).","cn":"我喜欢她，虽然她有时烦得让人想把她掐死。"},{"en":"I throttled back as we approached the runway.","cn":"我们靠近跑道时，我减速了。"}],"oxford":{"phon":"ˈθrɒtl","pos":"verb","senses":[{"en":"to attack or kill somebody by pressing their throat in order to stop them from breathing","cn":"使窒息；掐死；勒死","lab":"humorous","ex":{"en":"He throttled the guard with his bare hands.","cn":"他徒手掐死了卫兵。"}},{"en":"a device that controls the amount of fuel that goes into the engine of a vehicle, for example the accelerator in a car","cn":"节流阀；节流杆；风门；风门杆","pos":"noun"}]}},"thankful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感激的;感谢的;欣慰的","en":"When you are thankful, you are very happy and relieved that something has happened.","ex":{"en":"Most of the time I'm just thankful that I've got a job","cn":"多数时候我只是庆幸自己有份工作。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling that you want to thank someone, especially because they have done something for you and helped you a lot","cn":""},{"en":"grateful that someone has done something, because if they had not done it the situation would have been much worse","cn":""},{"en":"to be grateful to someone for something that they have done for you, because you realize that they did not have to do it or that they made a big effort to do it for you","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"On Thanksgiving, we remember to be thankful , showing and feeling our thanks for the meal and company in front of us."}]},"collocations":{"phrases":["VERBS be, feel, seem","ADV. deeply, extremely, very | just I'm just thankful that my mother never lived to see this.","PREP. for We were thankful for the chance to rest."]},"media":{"uk":"media/ldoce/hwd/bre/c/thankful0205.mp3","us":"media/ldoce/hwd/ame/b/thankful.mp3"},"examples":[{"en":"I was thankful to see they'd all arrived safely.","cn":"看到他们都平安到达，我感到欣慰。"},{"en":"He wasn't badly hurt — that's something to be thankful for.","cn":"他的伤不重，这倒是值得庆幸。"}],"oxford":{"phon":"ˈθæŋkfl","pos":"adjective","senses":[{"en":"pleased about something good that has happened, or that something bad has not happened","cn":"感谢；感激；欣慰","ex":{"en":"I was thankful to see they'd all arrived safely.","cn":"看到他们都平安到达，我感到欣慰。"}}]}},"thrush":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"鸫","en":"A thrush is a fairly small bird with a brown back and a spotted breast."},{"pos":"N-UNCOUNT 不可数名词","cn":"鹅口疮;真菌性口炎;念珠菌性阴道炎","en":"Thrush is a medical condition caused by a fungus. It most often occurs in a baby's mouth or in a woman's vagina."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a brown bird with spots on its front","cn":"鸫"},{"en":"an infectious disease that can affect a person’s vagina or mouth","cn":"鹅口疮﹔念珠菌性阴道炎"}]},"media":{"uk":"media/ldoce/hwd/bre/4/thrush0205.mp3","us":"media/ldoce/hwd/ame/2/thrush1.mp3"},"examples":[{"en":"a song thrush","cn":"歌鸫"}],"oxford":{"phon":"θrʌʃ","pos":"noun","senses":[{"en":"a bird with a brown back and brown spots on its chest","cn":"鸫（一种背部为褐色、胸部有褐色斑点的鸟）","g":"[countable]","ex":{"en":"a song thrush","cn":"歌鸫"}},{"en":"a disease that affects the mouth and throat","cn":"鹅口疮；真菌性口炎","g":"[uncountable]"},{"en":"a disease that affects the vagina","cn":"念珠菌阴道炎","g":"[uncountable]","lab":"British English"}]}},"thud":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(重物撞击软物时的)沉闷声，低沉声","en":"A thud is a dull sound, such as that which a heavy object makes when it hits something soft.","ex":{"en":"She tripped and fell with a sickening thud","cn":"她绊了一下，重重地摔倒在地。"}},{"pos":"VERB 动词","cn":"发出沉重的声音;砰砰作响","en":"If something thuds somewhere, it makes a dull sound, usually when it falls onto or hits something else.","ex":{"en":"She ran up the stairs, her bare feet thudding on the wood","cn":"她光着脚噔噔地跑上木质楼梯。"}},{"pos":"VERB 动词","cn":"(心脏)咚咚跳，怦怦跳","en":"When your heart thuds, it beats strongly and rather quickly, for example because you are very frightened or very happy.","ex":{"en":"My heart had started to thud, and my mouth was dry","cn":"我的心开始咚咚跳，嘴里发干。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a loud sound caused especially when something hard or heavy hits something else","cn":""},{"en":"a very loud sound caused when something hits something else, especially when damage is caused","cn":""},{"en":"a quiet low sound made when a heavy object falls down onto surface","cn":""}]},"collocations":{"phrases":["ADJ. heavy, loud, resounding | dull, muffled, soft | sickening","VERB + THUD give She felt her heart give an extra thud. | hear | feel","PREP. with a ~ He hit the floor with a sickening thud.","PHRASES the thud of a heart, the thud of hooves"]},"media":{"uk":"media/ldoce/hwd/bre/e/thud_n0205.mp3","us":"media/ldoce/hwd/ame/4/thud1.mp3"},"examples":[{"en":"His head hit the floor with a dull thud.","cn":"他的头砰的一声撞在了地板上。"},{"en":"His arrow thudded into the target.","cn":"他的箭噗的一声射中靶子。"}],"oxford":{"phon":"θʌd","pos":"noun","senses":[{"en":"a sound like the one that is made when a heavy object hits something else","cn":"砰的一声；扑通一声","ex":{"en":"His head hit the floor with a dull thud.","cn":"他的头砰的一声撞在了地板上。"}},{"en":"to fall or hit something with a low, heavy sound","cn":"砰地落下；飕的一声击中","g":"[intransitive, transitive]","ex":{"en":"His arrow thudded into the target.","cn":"他的箭噗的一声射中靶子。"},"pos":"verb"},{"en":"to beat strongly","cn":"强有力地跳动；怦怦地跳","g":"[intransitive]","lab":"literary","ex":{"en":"She felt her heart thud wildly with fear.","cn":"她感到自己的心因恐惧而狂跳。"},"pos":"verb"}]}},"thundercloud":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雷雨云","en":"A thundercloud is a large dark cloud that is likely to produce thunder and lightning."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a white or grey mass in the sky that forms from very small drops of water","cn":""},{"en":"very thick cloud near the ground which is difficult to see through","cn":""},{"en":"light cloud near the ground that makes it difficult for you to see very far. Mist is usually not as thick as fog . You often get mist near areas of water or mountains","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41thundercloud.mp3","us":"media/ldoce/hwd/ame/6/thundercloud.mp3"},"oxford":{"phon":"ˈθʌndəklaʊd","pos":"noun","senses":[{"en":"a large dark cloud that produces thunder and lightning during a storm","cn":"雷雨云"}]}},"thresh":{"collins":{"senses":[{"pos":"VERB 动词","cn":"给(玉米、小麦、水稻等)脱粒;打谷","en":"When a cereal such as corn, wheat, or rice is threshed, it is beaten in order to separate the grains from the rest of the plant.","ex":{"en":"The corn was still sown, cut and threshed as it was a hundred years ago.","cn":"玉米的播种、收割、脱粒方法还和一百年前一样。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to separate grains of corn, wheat etc from the rest of the plant by beating it with a special tool or machine （","cn":"给）〔玉米﹑小麦等〕脱粒﹐打谷"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41thresh.mp3","us":"media/ldoce/hwd/ame/3/thresh.mp3"},"examples":[{"en":"a threshing machine","cn":"脱粒机"}],"oxford":{"phon":"θreʃ","pos":"verb","senses":[{"en":"to separate grains of rice, wheat, etc. from the rest of the plant using a machine or, especially in the past, by hitting it with a special tool","cn":"（用机器）使脱粒；（尤指旧时手持工具）打（稻、麦等）","g":"[transitive]","lab":"North American English"},{"en":"to move or make something move in a way that is violent or shows a loss of control","cn":"（使）剧烈扭动，翻滚","g":"[intransitive, transitive]"}]}},"threadbare":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(衣服、地毯等)破旧的，磨薄的，陈旧的","en":"Threadbare clothes, carpets, and other pieces of cloth look old, dull, and very thin, because they have been worn or used too much.","ex":{"en":"She sat cross-legged on a square of threadbare carpet.","cn":"她盘腿坐在一块破旧的方形地毯上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(活动、想法、论点)无力的，不充分的，陈旧乏味的","en":"If you describe an activity, an idea, or an argument as threadbare, you mean that it is very weak, or inadequate, or old and no longer interesting.","ex":{"en":"...the government's threadbare domestic policies.","cn":"政府陈腐的国内政策"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"clothes, books etc that look shabby are no longer in good condition because they are old and have been used a lot","cn":""},{"en":"something such as material or cloth that is worn is thinner or weaker in particular parts as a result of being used a lot over a long time","cn":""},{"en":"clothes or books that are tattered are old and torn","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Those jeans you wear every day that have holes in the knees and thin patches in the rear? They're threadbare . Threadbare means thin from overuse."}]},"collocations":{"phrases":["VERBS be | wear sth The carpets had worn rather threadbare.","ADV. a little, rather"]},"media":{"uk":"media/ldoce/hwd/bre/0/threadbare0205.mp3","us":"media/ldoce/hwd/ame/7/threadbare.mp3"},"examples":[{"en":"a threadbare carpet","cn":"磨薄了的地毯"},{"en":"a threadbare old sofa","cn":"一张破旧的沙发"}],"oxford":{"phon":"ˈθredbeə(r)","pos":"adjective","senses":[{"en":"old and thin because it has been used a lot","cn":"穿旧的；磨薄的；破旧的","ex":{"en":"a threadbare carpet","cn":"磨薄了的地毯"}},{"en":"that does not have much effect, especially because it has been used too much","cn":"老一套的；陈腐的"}]}},"thai":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"泰国的;泰国人的;泰语的;泰国文化的","en":"Thai means belonging or relating to Thailand, or to its people, language, or culture.","ex":{"en":"Thai food is terrific.","cn":"泰国菜棒极了。"}},{"pos":"N-COUNT 可数名词","cn":"泰国人","en":"A Thai is a citizen of Thailand, or a person of Thai origin."},{"pos":"N-UNCOUNT 不可数名词","cn":"泰语","en":"Thai is the language spoken in Thailand."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who comes from Thailand","cn":""},{"en":"the language of Thailand","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/lpd_thai.mp3","us":"media/ldoce/hwd/ame/f/thai_n.mp3"},"oxford":{"phon":"taɪ","pos":"noun, adjective","senses":[{"en":"(a person) from Thailand","cn":"泰国人；泰国的；泰国人的"}]}},"thrashing":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(运动员、运动队的)遭痛打，大败，惨败","en":"If one player or team gives another one a thrashing, they defeat them easily or by a large score.","ex":{"en":"Can the New Zealand bowlers fight back after their thrashing at Christchurch?","cn":"在克赖斯特彻奇遭遇惨败后，新西兰的投球手们还有还手之力吗？"}},{"pos":"N-COUNT 可数名词","cn":"(作为惩罚的)连续击打，接连殴打，痛打","en":"If someone gives someone else a thrashing, they hit them several times as a punishment.","ex":{"en":"If Sarah caught her, she would get a thrashing.","cn":"萨拉要是捉住她，会狠狠揍她一顿的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an occasion when you beat someone or are beaten violently as a punishment （","cn":"被）痛打"},{"en":"an occasion when you defeat someone or are defeated very easily in a game 〔","cn":"比赛中的〕大胜﹐大败"}]},"collocations":{"phrases":["ADJ. good, sound","VERB + THRASHING give | get He got a sound thrashing once his father found out. | deserve 2 defeat","VERB + THRASHING give | have, suffer, take The team suffered a 4-0 thrashing on Sunday.","PREP. ~ of Richmond clinched promotion with a 50-3 thrashing of Roundhay."]},"media":{"uk":"media/ldoce/hwd/bre/0/thrashing0205.mp3","us":"media/ldoce/hwd/ame/5/laadthrashing.mp3"},"examples":[{"en":"to give sb/get a thrashing","cn":"痛打某人一顿；挨了一顿痛打"},{"en":"If you speak to your mother like that again, you’ll get a thrashing .","cn":"你再那样跟你妈说话﹐就要挨揍了。"}],"oxford":{"phon":"ˈθræʃɪŋ","pos":"noun","senses":[{"en":"an act of hitting a person or an animal very hard, especially with a stick","cn":"棒打；殴打；痛打","ex":{"en":"to give somebody/get a thrashing","cn":"痛打某人一顿；挨了一顿痛打"}},{"en":"a severe defeat in a game","cn":"（比赛）大败，惨败","lab":"informal","ex":{"en":"The team suffered a 4-0 thrashing on Sunday.","cn":"星期天那个球队以 0 比 4 的比分大败。"}}]},"base":"thrash"},"thought-provoking":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(书籍、电影等)发人深省的，引人深思的","en":"If something such as a book or a film is thought-provoking, it contains interesting ideas that make people think seriously.","ex":{"en":"This is an entertaining yet thought-provoking film.","cn":"这部电影令人捧腹，却又发人深省。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making people think seriously about a particular subject","cn":"发人深省的﹐引人深思的"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld44thought-prov.mp3","us":"media/ldoce/hwd/ame/3/ld44thought-prov.mp3"},"examples":[{"en":"a thought-provoking article","cn":"发人深省的文章"}],"oxford":{"phon":"ˈθɔːt prəvəʊkɪŋ","pos":"adjective","senses":[{"en":"making people think seriously about a particular subject or issue","cn":"发人深省的；引人深思的","ex":{"en":"a brilliant and thought-provoking play","cn":"出色而引人思考的戏剧"}}]}},"thieving":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"偷窃;偷盗","en":"Thieving is the act of stealing things from people.","ex":{"en":"...an ex-con who says he's given up thieving.","cn":"自称已洗手不干的有盗窃前科的人"}},{"pos":"ADJ 形容词","cn":"偷窃的;意欲偷盗的","en":"Thieving means involved in stealing things or intending to steal something.","ex":{"en":"He vowed to wreak vengeance on his unfaithful, thieving wife.","cn":"他发誓要报复对自己不忠、爱偷东西的妻子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of stealing things","cn":"偷窃﹐偷窃行为"}]},"media":{"uk":"media/ldoce/hwd/bre/b/thieving0205.mp3","us":"media/ldoce/hwd/ame/c/ld44thieving.mp3"},"examples":[{"en":"( informal ) You've no right to take that, you thieving swine!","cn":"你没有权利把那拿走，你这个贪心的贼！"}],"oxford":{"phon":"ˈθiːvɪŋ","pos":"noun","senses":[{"en":"the act of stealing things","cn":"偷窃"},{"en":"used to describe somebody who steals things","cn":"偷窃","ex":{"en":"You've no right to take that, you thieving swine!","cn":"你无权拿走那东西，你这个贼胚！"},"pos":"adjective"}]}},"thunderclap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雷声;雷鸣","en":"A thunderclap is a short loud noise that you hear in the sky just after you see a flash of lightning."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a single loud noise of thunder 〔","cn":"一声〕响雷﹐霹雳"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41thunderclap.mp3","us":"media/ldoce/hwd/ame/f/thunderclap.mp3"},"examples":[{"en":"A thunderclap exploded above us.","cn":"一声霹雳在我们头顶炸响。"}],"oxford":{"phon":"ˈθʌndəklæp","pos":"noun","senses":[{"en":"a loud crash made by thunder","cn":"雷声；霹雳","ex":{"en":"We counted the time between the lightning flash and the thunderclap.","cn":"我们计算了闪电和雷鸣之间的时间。"}}]}},"therein":{"collins":{"senses":[{"pos":"ADV 副词","cn":"在那里;在其中","en":"Therein means contained in the place that has been mentioned.","ex":{"en":"By burning tree branches, pine needles, and pine cones, many not only warm their houses but improve the smell therein.","cn":"许多人在家里烧树枝、松针和松果，不但给房子取暖，还改善了屋里的气味。"}},{"pos":"ADV 副词","cn":"其中(指和刚提及的事情有关)","en":"Therein means relating to something that has just been mentioned.","ex":{"en":"Afternoon groups relate to the specific addictions and problems therein.","cn":"下午的小组谈到具体的上瘾病例以及其中的问题。"}},{"pos":"PHRASE 短语","cn":"此即，缘此(用以说明某事是由某种情况导致)","en":"When you say therein lies a situation or problem, you mean that an existing situation has caused that situation or problem.","ex":{"en":"Santa Maria di Castellabate is barely mentioned in guidebooks; therein lies its charm.","cn":"卡斯特拉巴泰的圣玛丽亚在旅行指南里鲜有被提及，而它的魅力正在于此。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in that place, or in that piece of writing","cn":"在那里﹔在那篇文章[那本书]里"},{"en":"used to say that something is caused by or comes from a particular situation","cn":"这恰恰是…所在﹐…正在于此〔用以说明缘起〕"}]},"media":{"uk":"media/ldoce/hwd/bre/d/therein0205.mp3","us":"media/ldoce/hwd/ame/9/therein.mp3"},"examples":[{"en":"The insurance policy covers the building and any fixtures contained therein.","cn":"保险单为这座大楼及其中所有的设施保了险。"},{"en":"He works extremely hard and therein lies the key to his success.","cn":"他工作极其努力，这就是他成功的关键。"}],"oxford":{"phon":"ˌðeərˈɪn","pos":"adverb","senses":[{"en":"in the place, object, document, etc. mentioned","cn":"在那里，在其中（指提及的地点、物体、文件等）","ex":{"en":"The insurance policy covers the building and any fixtures contained therein.","cn":"保险单为这座大楼及其中所有的设施保了险。"}}]}},"thyme":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"百里香(一种调料)","en":"Thyme is a type of herb used in cooking."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant used for giving food a special taste","cn":"百里香〔用作调味品〕"}]},"media":{"uk":"media/ldoce/hwd/bre/2/thyme0205.mp3","us":"media/ldoce/hwd/ame/7/thyme.mp3","img":["media/thumb/thyme.jpg"]},"oxford":{"phon":"taɪm","pos":"noun","senses":[{"en":"a plant with small leaves that have a sweet smell and are used in cooking as a herb","cn":"百里香（一种植物，叶小，有香味，可作烹饪调味品）"}]}},"three-dimensional":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"三维的(缩略形式为 3-D)","en":"A three-dimensional object is solid rather than flat, because it can be measured in three different directions, usually the height, length, and width. The abbreviation 3-D can also be used.","ex":{"en":"...a three-dimensional model.","cn":"三维模型"}},{"pos":"ADJ 形容词","cn":"(照片、图像、电影)三维的，有立体感的(缩略形式为 3-D)","en":"A three-dimensional picture, image, or film looks as though it is deep or solid rather than flat. The abbreviation 3-D can also be used.","ex":{"en":"...new software, which generates both two-dimensional drawings and three-dimensional images.","cn":"既能制作二维图形、又能制作三维图像的新软件"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(虚构的人物)栩栩如生的，逼真的，鲜活的","en":"If you describe fictional characters as three-dimensional you mean that they seem real and natural.","ex":{"en":"She emerges as a full, three-dimensional character in a way that few horror genre heroines ever do.","cn":"她作为一个丰满而又鲜活的人物形象展现在读者面前，之前的恐怖体裁作品中，很少有女主人公给人这种感觉。"}},{"pos":"ADJ 形容词","cn":"(艺术、设计)立体的(缩略形式为 3-D)","en":"Three-dimensional art or design is produced by carving or shaping stone, wood, clay, or other materials. The abbreviation 3-D can also be used.","ex":{"en":"...a degree in three-dimensional art.","cn":"立体艺术专业学位"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having, or seeming to have, length, depth, and height","cn":"三维的﹐立体的"},{"en":"a three-dimensional character in a book, film etc seems like a real person 〔","cn":"书﹑电影等中的人物〕有立体感的﹐逼真的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/three_dimensio0205.mp3","us":"media/ldoce/hwd/ame/5/three-dimensional.mp3"},"examples":[{"en":"three-dimensional objects","cn":"立体物体"},{"en":"a three-dimensional structure","cn":"三维结构"}],"oxford":{"phon":"ˌθriː daɪˈmenʃənl","pos":"adjective","senses":[{"en":"having, or appearing to have, length, width and depth","cn":"三维的；立体的；三度空间的；有立体感的","ex":{"en":"three-dimensional objects","cn":"立体物体"}}]}},"thither":{"collins":{"senses":[{"pos":"ADV 副词","cn":"到那里;向那边","en":"Thither means to the place that has already been mentioned. hither and thither→see: ;","ex":{"en":"They have dragged themselves thither for shelter.","cn":"他们费力地挪动到那边躲避。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"in that direction","cn":"向那边﹐到那边"}]},"vocab":{"pos":"adv","senses":[{"en":"Use the word thither when you need a colorful way to say \"over there.\" For example, you might point across the street and say, \"Let's go thither , to the ice cream shop.\""}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41thither.mp3","us":"media/ldoce/hwd/ame/b/ld44thither.mp3"},"oxford":{"phon":"ˈðɪðə(r)","pos":"adverb","senses":[{"en":"to or towards that place","cn":"到那里；向那里"}]}},"thin-skinned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"脸皮薄的;敏感的;易生气的","en":"If you say that someone is thin-skinned, you mean that they are easily upset by criticism or unpleasantness.","ex":{"en":"Some fear he is too thin-skinned to survive the rough-and-tumble of a presidential campaign.","cn":"有人担心他脸皮太薄，经受不住总统选举的激烈竞争。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"too easily offended or upset by criticism","cn":"脸皮薄的﹐一批评就生气的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be thin-skinned is to be sensitive, especially to criticism and slights. Thin-skinned people are quick to take offense."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41thin-skinned.mp3","us":"media/ldoce/hwd/ame/f/thin-skinned.mp3"},"oxford":{"phon":"ˌθɪn ˈskɪnd","pos":"adjective","senses":[{"en":"easily upset by criticism or offensive remarks","cn":"脸皮薄的；（对批评或冒犯的语言）易生气的"},{"en":"having a thin skin","cn":"皮薄的"}]}},"thicket":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"小树丛;灌木丛","en":"A thicket is a small group of trees or bushes which are growing closely together.","ex":{"en":"...a bamboo thicket.","cn":"竹丛"}},{"pos":"N-COUNT 可数名词","cn":"乱糟糟的一团(思想、事件)","en":"If you refer to a thicket of ideas or events, you mean that there a lot of them together, and often that they are confusing or difficult to identify.","ex":{"en":"The novel is a thicket of literary references","cn":"这本小说纯粹是由一堆文学参考书胡乱拼凑而成。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very large area of land with a lot of trees growing closely together","cn":""},{"en":"an area of land covered with a lot of trees, that is smaller than a forest","cn":""},{"en":"an area of land that is covered with trees – used especially for describing the type of land in an area","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A thicket refers to a dense growth of bushes or trees — what you try to avoid by tending to the plants in your backyard."}]},"media":{"uk":"media/ldoce/hwd/bre/5/thicket0205.mp3","us":"media/ldoce/hwd/ame/c/thicket.mp3"},"oxford":{"phon":"ˈθɪkɪt","pos":"noun","senses":[{"en":"a group of bushes or small trees growing closely together","cn":"灌木丛；树丛","ex":{"en":"a dense thicket of bamboo","cn":"茂密的竹丛"}},{"en":"a large number of things that are not easy to understand or separate","cn":"错综复杂；盘根错节","ex":{"en":"He spent the morning trying to work his way through a thicket of statistics.","cn":"他花了一上午的时间试图研究一堆统计数据。"}}]}},"threesome":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"三人一组","en":"A threesome is a group of three people."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a group of three people or things","cn":"三人一组﹔三件一套"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41threesome.mp3","us":"media/ldoce/hwd/ame/d/threesome.mp3"},"oxford":{"phon":"ˈθriːsəm","pos":"noun","senses":[{"en":"a group of three people","cn":"三人一组；三人小组","g":"[countable + singular or plural verb]","ex":{"en":"They became an inseparable threesome.","cn":"他们成了形影不离的三人组。"}},{"en":"an occasion when three people have sex together","cn":"三人性爱","g":"[countable]"}]}},"thuggery":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"罪行;粗暴行径","en":"Thuggery is rough, violent behaviour."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"violent behaviour in which people fight and attack others","cn":"暴行"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41thuggery.mp3","us":"media/ldoce/hwd/ame/4/ld41thuggery.mp3"},"examples":[{"en":"the problem of football thuggery","cn":"足球暴力的问题"}],"oxford":{"phon":"ˈθʌɡəri","pos":"noun","senses":[{"en":"violent, usually criminal, behaviour","cn":"暴行；罪恶行径","ex":{"en":"shoplifting, vandalism and petty thuggery","cn":"入店行窃、破坏公物和小规模暴行"}}]}},"theocratic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"僧侣政体的;神权政体的","en":"A theocratic society is ruled by priests who represent a god.","ex":{"en":"It is a movement that threatens the choice of the people and threatens to install a theocratic state.","cn":"这是场威胁到人民选择权的运动，是场有可能建立神权政体的运动。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a social system or state controlled by religious leaders","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/theocracy0205.mp3","us":"media/ldoce/hwd/ame/6/laadtheocracy.mp3"},"examples":[{"en":"theocratic rule","cn":"神权统治"}],"oxford":{"phon":"ˌθiːəˈkrætɪk","pos":"adjective","senses":[{"en":"connected with the government of a country by religious leaders","cn":"神权政治；僧侣政体","ex":{"en":"theocratic rule","cn":"神权统治"}}]}},"thrombosis":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"血栓形成","en":"Thrombosis is the formation of a blood clot in a person's heart or in one of their blood vessels, which can cause death.","ex":{"en":"It is generally accepted that thinning of the blood reduces the chances of thrombosis.","cn":"一般认为，稀释血液可降低血栓形成的可能性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a serious medical problem caused by a clot forming in your blood that prevents the blood from flowing normally","cn":"血栓形成"}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41thrombosis.mp3","us":"media/ldoce/hwd/ame/3/thrombosis.mp3"},"oxford":{"phon":"θrɒmˈbəʊsɪs","pos":"noun","senses":[{"en":"a serious condition caused by a blood clot (= a thick mass of blood) forming in a blood vessel (= tube) or in the heart","cn":"血栓形成"}]}},"thereafter":{"collins":{"senses":[{"pos":"ADV 副词","cn":"之后;此后;随后","en":"Thereafter means after the event or date mentioned.","ex":{"en":"Inflation will fall and thereafter so will interest rates","cn":"通货膨胀率将下跌，随后利率也将下降。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"use this to talk about a new arrangement that is going to start now and then continue in the future","cn":""},{"en":"use this to say that a new rule or arrangement will start at a particular time and will continue from then","cn":""},{"en":"after a particular time or date","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld42thereafter.mp3","us":"media/ldoce/hwd/ame/a/ld42thereafter.mp3"},"examples":[{"en":"She married at 17 and gave birth to her first child shortly thereafter.","cn":"她 17 岁结婚，之后不久便生了第一个孩子。"},{"en":"10,000 men had volunteered by the end of September; thereafter, approximately 1,000 men enlisted each month.","cn":"到9月底时已有10,000人志愿参军。此后﹐每个月差不多有1,000人应征入伍。"}],"oxford":{"phon":"ˌðeərˈɑːftə(r)","pos":"adverb","senses":[{"en":"after the time or event mentioned","cn":"之后；此后；以后","ex":{"en":"She married at 17 and gave birth to her first child shortly thereafter.","cn":"她 17 岁结婚，之后不久便生了第一个孩子。"}}]}},"thermoplastic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"热塑性塑料","en":"Thermoplastic materials are types of plastic which becomes soft when they are heated and hard when they cool down."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plastic that is soft and bendable when heated but hard when cold","cn":"热塑性塑料〔加热时柔软可弯曲但冷却后坚硬的塑料〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41thermoplastic.mp3","us":"media/ldoce/hwd/ame/1/thermoplastic.mp3"},"oxford":{"phon":"ˌθɜːməʊˈplæstɪk","pos":"noun","senses":[{"en":"a plastic material that can be easily shaped and bent when it is heated, and that becomes hard when it is cooled","cn":"热塑性塑料"}]}},"thespian":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"演员","en":"A thespian is an actor or actress."},{"pos":"ADJ 形容词","cn":"戏剧的;剧院的","en":"Thespian means relating to drama and the theatre."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an actor – sometimes used humorously","cn":"演员〔有时为幽默用法〕"}]},"vocab":{"pos":"n adj","senses":[{"en":"Thespian is a fancy word for actor. Since this word is related to Thespis, the guy who first took the stage in Ancient Greece, you can feel real scholarly using the word thespian ."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thespian.mp3","us":"media/ldoce/hwd/ame/2/thespian.mp3"},"examples":[{"en":"a distinguished thespian","cn":"一位知名的演员"}],"oxford":{"phon":"ˈθespiən","pos":"noun","senses":[{"en":"an actor","cn":"演员"},{"en":"connected with acting, drama and the theatre","cn":"演员","ex":{"en":"Her popularity owed much to her thespian talents.","cn":"她的受欢迎很大程度上归功于她的戏剧天赋。"},"pos":"adjective"}]}},"thereby":{"collins":{"senses":[{"pos":"ADV 副词","cn":"因此;由此;从而","en":"You use thereby to introduce an important result or consequence of the event or action you have just mentioned.","ex":{"en":"Our bodies can sweat, thereby losing heat by evaporation","cn":"我们的身体能出汗，由此可以蒸发散热。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"with the result that something else happens","cn":"因此﹐由此"}]},"vocab":{"pos":"adv","senses":[{"en":"The adverb thereby shows cause and effect: \"She forgot to tie her shoes, thereby tripping and falling down the stairs.\""}]},"media":{"uk":"media/ldoce/hwd/bre/8/thereby0205.mp3","us":"media/ldoce/hwd/ame/d/thereby.mp3"},"examples":[{"en":"Regular exercise strengthens the heart, thereby reducing the risk of heart attack.","cn":"经常锻炼可以增强心脏机能，从而减少心脏病发作的危险。"},{"en":"He became a citizen in 1978, thereby gaining the right to vote.","cn":"他在1978年成为公民﹐由此获得了投票权。"}],"oxford":{"phon":"ˌðeəˈbaɪ","pos":"adverb","senses":[{"en":"used to introduce the result of the action or situation mentioned","cn":"因此；由此；从而","ex":{"en":"Regular exercise strengthens the heart, thereby reducing the risk of heart attack.","cn":"经常锻炼可以增强心脏机能，从而减少心脏病发作的危险。"}}]}},"throw-in":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(足球或橄榄球比赛中的)掷边线球，掷界外球","en":"When there is a throw-in in a football or rugby match, the ball is thrown back onto the field after it has been kicked off it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an action in which someone throws the ball back onto the field in a game of football 〔","cn":"足球的〕掷界外球"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41throw-in.mp3","us":"media/ldoce/hwd/ame/d/laadthrow-in.mp3"},"examples":[{"en":"Beckham will take the throw-in .","cn":"贝克汉姆来掷这个界外球。"}],"oxford":{"phon":"ˈθrəʊ ɪn","pos":"noun","senses":[{"en":"the act of throwing the ball back onto the playing field after it has gone outside the area","cn":"掷界外球；掷边线球"}]}},"thirteenth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第十三","en":"The thirteenth item in a series is the one that you count as number thirteen."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 13","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thirteen.mp3","us":"media/ldoce/hwd/ame/8/thirteen.mp3"},"examples":[{"en":"They’ve only sold thirteen tickets so far.","cn":""},{"en":"When it happened, I was thirteen (= 13 years old ) .","cn":""}],"oxford":{"phon":"ˌθɜːˈtiːnθ","pos":"noun","senses":[{"en":"each of thirteen equal parts of something","cn":"三分之一"},{"en":"13th","cn":"十三","pos":"ordinal number"}]}},"thermostat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"温度自动调节器;恒温器","en":"A thermostat is a device that switches a system or motor on or off according to the temperature. Thermostats are used, for example, in central heating systems and fridges."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an instrument used for keeping a room or a machine at a particular temperature","cn":"恒温器"}]},"vocab":{"pos":"n v","senses":[{"en":"If your house is always too cold in the winter, you might need to adjust the thermostat , or the dial that controls the indoor temperature."}]},"media":{"uk":"media/ldoce/hwd/bre/4/thermostat_las3_br.mp3","us":"media/ldoce/hwd/ame/8/thermostat.mp3"},"oxford":{"phon":"ˈθɜːməstæt","pos":"noun","senses":[{"en":"a device that measures and controls the temperature of a machine or room, by switching the heating or cooling system on and off as necessary","cn":"温控器；恒温器"}]}},"thoughtless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不顾及他人的;欠考虑的","en":"If you describe someone as thoughtless, you are critical of them because they forget or ignore other people's wants, needs, or feelings.","ex":{"en":"...a small minority of thoughtless and inconsiderate people","cn":"一小群只顾自己、不顾别人的人"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not thinking about the effects of your actions on other people","cn":""},{"en":"someone who is tactless carelessly says or does things that are likely to upset someone, without realizing what they are doing","cn":""},{"en":"behaving in a way that is likely to upset someone, or not seeming to care about someone’s feelings. Insensitive is rather a formal word","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/thoughtless0205.mp3","us":"media/ldoce/hwd/ame/c/thoughtless.mp3"},"examples":[{"en":"a thoughtless remark","cn":"欠考虑的话"},{"en":"It was thoughtless of her not to tell you where she was going.","cn":"她没告诉你她要去哪儿﹐这有点欠考虑。"}],"oxford":{"phon":"ˈθɔːtləs","pos":"adjective","senses":[{"en":"not caring about the possible effects of your words or actions on other people","cn":"粗心大意的；欠考虑的；轻率的","ex":{"en":"a thoughtless remark","cn":"欠考虑的话"}}]}},"thundery":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"要打雷的;将要有雷电的","en":"When the weather is thundery, there is a lot of thunder, or there are heavy clouds which make you think that there will be thunder soon.","ex":{"en":"Thundery weather is forecast","cn":"天气预报说会有雷雨。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"thundery weather is the type of weather that comes before a thunderstorm 〔","cn":"天气〕要打雷的﹐雷暴前的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41thundery.mp3","us":"media/ldoce/hwd/ame/3/thundery.mp3"},"oxford":{"phon":"ˈθʌndəri","pos":"adjective","senses":[{"en":"with thunder; suggesting that thunder is likely","cn":"有雷的；可能要打雷的","ex":{"en":"thundery rain","cn":"雷雨"}}]}},"thoroughfare":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大道;大街;通衢","en":"A thoroughfare is a main road in a town or city which usually has shops along it and a lot of traffic.","ex":{"en":"...a busy thoroughfare.","cn":"繁忙的大街"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the main road through a place such as a city or village","cn":"大街﹐大道"},{"en":"a written sign used to tell people that they cannot go on a particular road or path","cn":"此路不通﹐禁止通行〔标牌用语〕"}]},"vocab":{"pos":"n","senses":[{"en":"A thoroughfare is a public road that can get you from one place to another. When it snows, plows try to remove the snow from the thoroughfares so the school busses can take everyone to school. You’re welcome."}]},"media":{"uk":"media/ldoce/hwd/bre/4/thoroughfare0205.mp3","us":"media/ldoce/hwd/ame/9/thoroughfare.mp3"},"examples":[{"en":"The motel was off the main thoroughfare .","cn":"那家汽车旅馆远离大路。"}],"oxford":{"phon":"ˈθʌrəfeə(r)","pos":"noun","senses":[{"en":"a public road or street used by traffic, especially a main road in a city or town","cn":"大街；大道；通衢"}]}},"thrilling":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"扣人心弦的;激动人心的;引人入胜的","en":"Something that is thrilling is very exciting and enjoyable.","ex":{"en":"Our wildlife trips offer a thrilling encounter with wildlife in its natural state.","cn":"野生动物园之旅使我们得以接触自然状态下的野生动物，让人感觉很刺激。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very exciting","cn":""},{"en":"a gripping film, story etc is very exciting and interesting","cn":""},{"en":"used about something that is exciting to watch or hear about as it happens","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/brelasdethrilling.mp3","us":"media/ldoce/hwd/ame/8/laadthrilling.mp3"},"examples":[{"en":"a thrilling experience/finish","cn":"激动人心的经历/结局"},{"en":"a thrilling 3–2 victory","cn":"比分为3比2的激动人心的胜利"}],"oxford":{"phon":"ˈθrɪlɪŋ","pos":"adjective","senses":[{"en":"exciting and a lot of fun","cn":"惊险的；紧张的；扣人心弦的；令人兴奋不已的","ex":{"en":"a thrilling experience/finish","cn":"激动人心的经历／结局"}}]},"base":"thrill"},"thenceforth":{"collins":{"senses":[{"pos":"ADV 副词","cn":"从那时起;从此","en":"Thenceforth means starting from a particular time in the past that you have mentioned.","ex":{"en":"My life was totally different thenceforth.","cn":"从此，我的生活彻底改变了。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"starting from that time","cn":"从那时起"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41thenceforth.mp3","us":"media/ldoce/hwd/ame/7/thenceforth.mp3"},"oxford":{"phon":"ˌðensˈfɔːθ","pos":"adverb","senses":[{"en":"starting from that time","cn":"从那时起；此后","ex":{"en":"Thenceforth he became known as the Lord Protector.","cn":"从那时起，他被称为护国公。"}}]}},"throw":{"collins":{"senses":[{"pos":"VERB 动词","cn":"扔;抛;投;掷","en":"When you throw an object that you are holding, you move your hand or arm quickly and let go of the object, so that it moves through the air.","ex":{"en":"He spent hours throwing a tennis ball against a wall","cn":"他好几个小时都对着一堵墙掷网球。"}},{"pos":"VERB 动词","cn":"急伸，猛动(身体或某部位)","en":"If you throw your body or part of your body into a particular position or place, you move it there suddenly and with a lot of force.","ex":{"en":"She threw her arms around his shoulders","cn":"她一把搂住他的肩膀。"}},{"pos":"VERB 动词","cn":"(随手)抛，丢，扔","en":"If you throw something into a particular place or position, you put it there in a quick and careless way.","ex":{"en":"He struggled out of his bulky jacket and threw it on to the back seat","cn":"他费劲脱下他那件笨重的夹克，随手把它扔在后座上。"}},{"pos":"VERB 动词","cn":"摔;掼;抛","en":"To throw someone into a particular place or position means to force them roughly into that place or position.","ex":{"en":"He threw me to the ground and started to kick","cn":"他把我摔倒在地，开始用脚踢。"}},{"pos":"VERB 动词","cn":"把…投进(监狱)","en":"If you say that someone is thrown into prison, you mean that they are put there by the authorities, especially if this seems unfair or cruel.","ex":{"en":"Those two should have been thrown in jail","cn":"那两个人早就应该抓去坐牢。"}},{"pos":"VERB 动词","cn":"(马)甩落，掀掉(骑手)","en":"If a horse throws its rider, it makes him or her fall off, by suddenly jumping or moving violently.","ex":{"en":"The horse reared, throwing its rider and knocking down a youth standing beside it.","cn":"那匹马尥了个蹶子，把骑手掀下马，还撞倒了旁边站着的一个小伙子。"}},{"pos":"VERB 动词","cn":"使处境不利;使进展不顺","en":"If a person or thing is thrown into an unpleasant situation or state, something causes them to be in that situation or state.","ex":{"en":"Abidjan was thrown into turmoil because of a protest by taxi drivers","cn":"出租车司机的抗议使得阿比让陷入了混乱。"}},{"pos":"VERB 动词","cn":"投下，洒下，抛下(光线或影子)","en":"If something throws light or a shadow on a surface, it causes that surface to have light or a shadow on it.","ex":{"en":"The sunlight is white and blinding, throwing hard-edged shadows on the ground.","cn":"阳光明亮刺眼，在地上投下轮廓分明的影子。"}},{"pos":"VERB 动词","cn":"把(怀疑)加(于)","en":"If something throws doubt on a person or thing, it causes people to doubt or suspect them.","ex":{"en":"This new information does throw doubt on their choice","cn":"这个新信息确实使人们对他们的选择产生了怀疑。"}},{"pos":"VERB 动词","cn":"飞快(看)一眼;迅速(笑)一下","en":"If you throw a look or smile at someone or something, you look or smile at them quickly and suddenly.","ex":{"en":"Emily turned and threw her a suggestive grin.","cn":"埃米莉转过头，冲她意味深长地一笑。"}},{"pos":"VERB 动词","cn":"投入;投身(于)","en":"If you throw yourself, your energy, or your money into a particular job or activity, you become involved in it very actively or enthusiastically.","ex":{"en":"She threw herself into a modelling career","cn":"她投身于模特事业。"}},{"pos":"VERB 动词","cn":"突然发怒;大发雷霆","en":"If you throw a fit or a tantrum, you suddenly start to behave in an uncontrolled way.","ex":{"en":"I used to get very upset and scream and swear, throwing tantrums all over the place.","cn":"以前，我动不动就发脾气，大喊大叫，还骂人。"}},{"pos":"VERB 动词","cn":"使吃惊;使迷惑不解","en":"If something such as a remark or an experience throws you, it surprises you or confuses you because it is unexpected.","ex":{"en":"The professor rather threw me by asking if I went in for martial arts","cn":"教授问我是否爱好武术，这个问题让我吃了一惊。"}},{"pos":"VERB 动词","cn":"打(一拳)","en":"If you throw a punch, you punch someone.","ex":{"en":"Everything was fine until someone threw a punch.","cn":"开头还好好的，后来不知是谁动了拳头。"}},{"pos":"VERB 动词","cn":"(通常在家里)进行，举办(聚会)","en":"When someone throws a party, they organize one, usually in their own home.","ex":{"en":"Why not throw a party for your friends?","cn":"干吗不在家里为你的朋友们搞个聚会？"}},{"pos":"VERB 动词","cn":"按，拨动(开关)","en":"When someone throws a switch, they turn it on or off.","ex":{"en":"Prince Edward threw the switch to light the illuminations.","cn":"爱德华王子按动开关亮起彩灯。"}},{"pos":"VERB 动词","cn":"故意输掉(比赛)","en":"In sports, if a player throws a game or contest, they lose it as a result of a deliberate action or intention.","ex":{"en":"...offering him a bribe to throw the game.","cn":"向他行贿，叫他故意输掉比赛"}},{"pos":"N-COUNT 可数名词","cn":"沙发套;床罩","en":"A throw is a light rug, blanket, or cover for a sofa or bed."},{"pos":"PHRASE 短语","cn":"单价;每个的价格","en":"If things cost a particular amount of money a throw, they cost that amount each.","ex":{"en":"Most applications software for personal computers cost over $500 a throw.","cn":"个人电脑使用的多数应用软件的单价为 500 多美元。"}},{"pos":"PHRASE 短语","cn":"向…投怀送抱;向…献媚","en":"If someone throws themselves at you, they make it very obvious that they want to begin a relationship with you, by behaving as though they are sexually attracted to you.","ex":{"en":"I'll say you started it, that you threw yourself at me.","cn":"我觉得是你主动向我投怀送抱。"}},{"pos":"","cn":"","en":"to throw the baby out with the bath water→see: ; to throw the book at someone→see: ; to throw someone in at the deep end→see: ; to throw down the gauntlet→see: ; to throw up your hands→see: ; to throw light on something→see: ; to throw in your lot with someone→see: ; to throw money at something→see: ; to throw good money after bad→see: ; to throw a spanner in the works→see: ; a stone's throw→see: ; to throw in the towel→see: ; to throw your weight about→see: ; to throw a wrench→see: ;"},{"pos":"","cn":"","en":"相关词组：throw around throw aside throw away throw back throw down throw in throw off throw out throw together throw up"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something such as a ball or stone move quickly through the air using your hand","cn":"投﹐扔"},{"en":"to throw something, especially in a careless way without using much effort","cn":"轻抛"},{"en":"to throw something with a lot of force","cn":"用力投掷"}]},"vocab":{"pos":"1 v n 2 v n 3 v 4 v ","senses":[{"en":"When you throw a ball, you toss it using your hand. When you throw a party, you buy some food and drinks, then invite your friends over."}]},"collocations":{"phrases":["ADV. angrily | casually He threw the keys casually down on the table. | aside, away, back, down, out She threw her head back and laughed.","VERB + THROW be ready to, be tempted to, want to | threaten to He threatened to throw her in the river if she screamed. | be going to","PREP. at He threw a stone at the window. | in/into I just wanted to throw myself into his arms and cry. | to She threw the ball to him. | to","PHRASES throw sth open He threw the double doors open in a dramatic gesture."]},"media":{"uk":"media/ldoce/hwd/bre/a/throw_n0205.mp3","us":"media/ldoce/hwd/ame/0/throw1.mp3"},"examples":[{"en":"You can have the piano for $200, and I'll throw in the stool as well.","cn":"你花 200 元就可以买走这架钢琴，另外奉送这张琴凳。"},{"en":"Our calculations of the cost of our trip were thrown out by changes in the exchange rate.","cn":"我们旅行费用的预算因为汇率变动而完全打乱了。"}],"oxford":{"phon":"θrəʊ","pos":"verb","senses":[{"en":"to send something from your hand through the air by moving your hand or arm quickly","cn":"投；掷；抛；扔","g":"[transitive, intransitive]","lab":"especially British English","sc":"with hand","ex":{"en":"Practise throwing and catching.","cn":"练习抛和接。"}},{"en":"to put something in a particular place quickly and carelessly","cn":"摔；丢；扔","g":"[transitive]","sc":"put carelessly","ex":{"en":"Just throw your bag down over there.","cn":"把你的袋子就扔到那边吧。"}},{"en":"to move something/somebody suddenly and with force","cn":"猛推；使劲撞","g":"[transitive]","lab":"figurative","sc":"move with force","ex":{"en":"The boat was thrown onto the rocks.","cn":"那条船触礁了。"}},{"en":"to move your body or part of it quickly or suddenly","cn":"猛动（头、臂、腿）；挺起（胸）；仰起（头）；挥动（拳头、手臂）","g":"[transitive]","sc":"part of body","ex":{"en":"He threw back his head and roared with laughter.","cn":"他猛地仰起头哈哈大笑起来。"}},{"en":"to make somebody fall quickly or violently to the ground","cn":"使迅猛地摔倒在地","g":"[transitive]","sc":"make somebody fall","ex":{"en":"Two riders were thrown (= off their horses) in the second race.","cn":"有两名骑手在第二场赛马中从马上摔了下来。"}},{"en":"to make somebody/something be in a particular state","cn":"使处于，使陷入（某种状态）","g":"[transitive, usually passive]","sc":"into particular state","ex":{"en":"Hundreds were thrown out of work.","cn":"数以百计的人遭到解雇。"}},{"en":"to direct something at somebody/something","cn":"把…对准；向…作出；对…施加","g":"[transitive]","sc":"direct something at somebody/something","ex":{"en":"to throw doubt on the verdict","cn":"对裁断产生怀疑"}},{"en":"to make somebody feel upset, confused, or surprised","cn":"使心烦意乱；使困惑；使惊奇","g":"[transitive]","lab":"informal","sc":"upset","ex":{"en":"The news of her death really threw me.","cn":"她的噩耗确实令我震惊。"}},{"en":"to roll a dice or let it fall after shaking it; to obtain a particular number in this way","cn":"掷（色子）；掷出（色子的点数）","g":"[transitive]","sc":"dice","ex":{"en":"Throw the dice!","cn":"掷色子！"}},{"en":"to make a clay pot, dish, etc. on a potter’s wheel","cn":"（在陶钧上）把…拉制成坯","g":"[transitive]","lab":"specialist","sc":"clay pot","ex":{"en":"a hand-thrown vase","cn":"手工拉制的陶瓶"}},{"en":"to send light or shade onto something","cn":"照射（光线）；投射（阴影）","g":"[transitive]","sc":"light/shade","ex":{"en":"The trees threw long shadows across the lawn.","cn":"树木在草坪上投下长长的影子。"}},{"en":"to make your voice sound as if it is coming from another person or place","cn":"使变音；使嗓音听起来像来自他人（或别处）","g":"[transitive]","sc":"your voice"},{"en":"to hit somebody with your fist","cn":"挥拳猛击；出拳","g":"[transitive]","sc":"a punch"},{"en":"to move a switch to operate something","cn":"按动，扳动，推动（开关）","g":"[transitive]","sc":"switch/handle"},{"en":"to have a sudden period of angry behaviour, violent emotion, etc.","cn":"突然发作（脾气等）","g":"[transitive]","sc":"angry behaviour","ex":{"en":"She'll throw a fit if she finds out.","cn":"她要是发现了，一定会大发雷霆。"}},{"en":"to give a party","cn":"举行聚会","g":"[transitive]","lab":"informal","sc":"a party","ex":{"en":"They threw a party for him on his birthday.","cn":"他们在他生日那天为他办了一个生日会。"}},{"en":"to deliberately lose a game or contest that you should have won","cn":"故意输掉（本应获胜的比赛或竞赛）","g":"[transitive]","lab":"informal","sc":"in sports/competitions","ex":{"en":"He was accused of having thrown the game.","cn":"他被指责故意放水，输掉了这场比赛。"}},{"en":"the act of throwing something, especially a ball or dice","cn":"抛；扔；摔；投（球）；掷（色子）","ex":{"en":"a well-aimed throw","cn":"准确的投掷"},"pos":"noun"},{"en":"the distance that something is thrown","cn":"投掷的距离","ex":{"en":"a javelin throw of 57 metres","cn":"57 米远的标枪投掷"},"pos":"noun"},{"en":"a loose cloth cover that can be placed over a sofa, etc.","cn":"（沙发等的）套，罩","pos":"noun"}]}},"thou":{"collins":{"senses":[{"pos":"PRON-SING 单数型代词","cn":"你，汝，尔(旧用词，现亦用于诗歌或宗教类语境，用作主语)","en":"Thou is an old-fashioned, poetic, or religious word for 'you' when you are talking to only one person. It is used as the subject of a verb."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a thousand or a thousandth","cn":"一千﹔一千分之一"},{"en":"a word meaning ‘you’, used as the subject of a sentence","cn":"汝﹐尔〔用作主语〕"}]},"vocab":{"pos":"n","senses":[{"en":"The word thou , used in place of \"you,\" is not used much in modern language. In fact, with its Biblical feeling, it’s most often used in religious contexts. Otherwise, it might be used as slang for thousand ."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld44thou.mp3","us":"media/ldoce/hwd/ame/3/ld44thou.mp3"},"examples":[{"en":"They paid about sixty-nine thou for it.","cn":"他们买它花了大约69,000块。"}],"oxford":{"phon":"ðaʊ","pos":"pronoun","senses":[{"en":"a word meaning ‘you’, used when talking to only one person who is the subject of the verb","cn":"（用作第二人称单数动词的主语）你，汝，尔"}]}},"throne":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(君王的)宝座，御座","en":"A throne is a decorative chair used by a king, queen, or emperor on important official occasions."},{"pos":"N-SING 单数名词","cn":"王位;皇位","en":"You can talk about the throne as a way of referring to the position of being king, queen, or emperor.","ex":{"en":"...the Queen's 50th anniversary on the throne.","cn":"女王登基 50 周年纪念日"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special chair used by a king or queen at important ceremonies 〔","cn":"君王的〕宝座﹐御座"},{"en":"the position and power of being a king or queen","cn":"王位﹐帝位﹔王权﹐君权"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"The oversized, bejeweled chair on which a king or queen sits is called a throne ."}]},"collocations":{"phrases":["ADJ. empty, unoccupied, vacant | imperial, papal, royal","VERB + THRONE ascend, assume, come to, gain, inherit, succeed to, take Elizabeth I came to the throne in 1558. | seize, usurp | occupy | giv","PREP. on the ~ Queen Victoria remained on the throne for over sixty years.","PHRASES sb's accession to the throne, a claimant/pretender to the throne a claimant to the vacant Spanish throne | sb's claim/right to the t"]},"media":{"uk":"media/ldoce/hwd/bre/d/throne0205.mp3","us":"media/ldoce/hwd/ame/1/throne.mp3"},"examples":[{"en":"Queen Elizabeth came/succeeded to the throne in 1952.","cn":"伊丽莎白女王于 1952 年即位/登基。"},{"en":"when Henry VIII was on the throne (= was king)","cn":"亨利八世在位时"}],"oxford":{"phon":"θrəʊn","pos":"noun","senses":[{"en":"a special chair used by a king or queen to sit on at ceremonies","cn":"（国王、女王的）御座，宝座","g":"[countable]","ex":{"en":"He sat very upright in his chair, as if he were a king on his throne.","cn":"他端坐在椅子上，像个坐在宝座上的国王。"}},{"en":"the position of being a king or queen","cn":"王位；王权；帝位","g":"[singular]","ex":{"en":"Queen Elizabeth came/succeeded to the throne in 1952.","cn":"伊丽莎白女王于 1952 年即位／登基。"}}]}},"thermodynamics":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"热力学","en":"Thermodynamics is the branch of physics that is concerned with the relationship between heat and other forms of energy."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the science that deals with the relationship between heat and other forms of energy","cn":"热力学"}]},"media":{"uk":"media/ldoce/hwd/bre/0/thermodynamics0205.mp3","us":"media/ldoce/hwd/ame/2/thermodynamics.mp3"},"examples":[{"en":"the laws of thermodynamics","cn":"热力学定律"}],"oxford":{"phon":"ˌθɜːməʊdaɪˈnæmɪks","pos":"noun","senses":[{"en":"the science that deals with the relations between heat and other forms of energy","cn":"热力学","ex":{"en":"the laws of thermodynamics","cn":"热力学定律"}}]}},"thwart":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使受挫;阻碍;阻挠","en":"If you thwart someone or thwart their plans, you prevent them from doing or getting what they want.","ex":{"en":"The accounting firm deliberately destroyed documents to thwart government investigators","cn":"会计事务所故意毁坏文件，阻挠政府调查工作。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to use something such as a law or an official order to prevent someone from doing something that they have been planning to do","cn":""},{"en":"to try to prevent someone from doing something by deliberately making it much more difficult for them","cn":""},{"en":"to prevent someone from doing something, especially something that they very much want to do because it is personally important to them","cn":""}]},"vocab":{"pos":"1 v 2 n","senses":[{"en":"A villain's worst nightmare is the superhero who always seems to thwart his efforts, preventing him from carrying out his plans to take over the world."}]},"collocations":{"phrases":["ADV. easily | constantly Plans to expand the company have been constantly thwarted.","VERB + THWART attempt to, try to","PREP. in They were thwarted in their attempt to gain overall control of the company."]},"media":{"uk":"media/ldoce/hwd/bre/9/thwart0205.mp3","us":"media/ldoce/hwd/ame/b/thwart1.mp3"},"examples":[{"en":"She was thwarted in her attempt to take control of the party.","cn":"她控制这个政党的企图受阻了。"},{"en":"to thwart sb's plans","cn":"阻挠某人的计划"}],"oxford":{"phon":"θwɔːt","pos":"verb","senses":[{"en":"to prevent somebody from doing what they want to do","cn":"阻止；阻挠；对…构成阻力","ex":{"en":"to thwart somebody’s plans","cn":"阻挠某人的计划"}}]}},"thirteen":{"collins":{"senses":[{"pos":"NUM 数词","cn":"(数字) 13","en":"Thirteen is the number 13."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 13","cn":"十三"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thirteen.mp3","us":"media/ldoce/hwd/ame/8/thirteen.mp3"},"examples":[{"en":"They’ve only sold thirteen tickets so far.","cn":"到目前为止他们仅仅售出13张票。"},{"en":"When it happened, I was thirteen (= 13 years old ) .","cn":"那事发生时﹐我13岁。"}],"oxford":{"phon":"ˌθɜːˈtiːn","pos":"number","senses":[{"en":"13","cn":"十三"}]}},"theoretician":{"lemma":"theorist"},"thankless":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(工作、任务)吃力不讨好的，劳而无功的","en":"If you describe a job or task as thankless, you mean that it is hard work and brings very few rewards.","ex":{"en":"Soccer referees have a thankless task.","cn":"足球裁判的工作吃力不讨好。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a thankless job is difficult and you do not get any praise for doing it","cn":"吃力不讨好的﹐徒劳无功的"},{"en":"a thankless person is not grateful 〔","cn":"人〕不知感激的﹐忘恩负义的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/thankless0205.mp3","us":"media/ldoce/hwd/ame/b/thankless.mp3"},"examples":[{"en":"Sometimes being a mother and a housewife felt like a thankless task.","cn":"做母亲和家庭主妇有时使人觉得好像是个受累不讨好的差使。"},{"en":"Cooking every day is a thankless task.","cn":"每天做饭是一件费力不讨好的事。"}],"oxford":{"phon":"ˈθæŋkləs","pos":"adjective","senses":[{"en":"unpleasant or difficult to do and unlikely to bring you any rewards or thanks from anyone","cn":"让人不领情的；徒劳无益的；吃力不讨好的","ex":{"en":"Sometimes being a mother and a housewife felt like a thankless task.","cn":"做母亲和家庭主妇有时使人觉得好像是个受累不讨好的差使。"}}]}},"thesis":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"命题;论点","en":"A thesis is an idea or theory that is expressed as a statement and is discussed in a logical way.","ex":{"en":"This thesis does not stand up to close inspection.","cn":"这个命题经不起仔细推敲。"}},{"pos":"N-COUNT 可数名词","cn":"论文;学位论文","en":"A thesis is a long piece of writing based on your own ideas and research that you do as part of a university degree, especially a higher degree such as a PhD.","ex":{"en":"He was awarded his PhD for a thesis on industrial robots.","cn":"他凭一篇研究工业机器人的论文获得博士学位。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of writing written by a student as part of a course of study","cn":""},{"en":"an essay written by a someone who has studied a subject as part of their research. Paper is also used about an essay that you have to write for a class at school, especially in American English","cn":""},{"en":"a long essay written as part of a university degree","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A thesis is the most important or foundational idea of an argument. If you write a paper with the central thesis that girls are yucky, you'll need to back that up with cooties-based research."}]},"collocations":{"phrases":["ADJ. doctoral, MA, Master's, MSc, PhD, etc. | chemistry, geology, etc. | research","VERB + THESIS work on | complete, do, write (up) | submit | publish","THESIS + NOUN research, title, topic","PREP. by ~ She completed an MSc by thesis. | in a/the ~ research presented in a thesis | ~ about/on He's doing a doctoral thesis on the earl","ADJ. basic, central, main","VERB + THESIS prove, support The results of the experiment support his central thesis. | disprove | advance He advanced the thesis that too ","PREP. ~ about a thesis about the effects of new technology on skills"]},"media":{"uk":"media/ldoce/hwd/bre/d/thesis0205.mp3","us":"media/ldoce/hwd/ame/8/thesis.mp3"},"examples":[{"en":"These latest findings support the thesis that sexuality is determined by nature rather than choice.","cn":"这些最新发现证实了性别特征取决于自然而不是选择这一论点。"},{"en":"Cynthia’s still working on her thesis.","cn":"辛西娅还在写论文。"}],"oxford":{"phon":"ˈθiːsɪs","pos":"noun","senses":[{"en":"a long piece of writing completed by a student as part of a university degree, based on their own research","cn":"论文；毕业论文；学位论文","ex":{"en":"Students must submit a thesis on an agreed subject within four years.","cn":"学生必须在四年内就通过的题目上交一篇毕业论文。"}},{"en":"a statement or an opinion that is discussed in a logical way and presented with evidence in order to prove that it is true","cn":"命题；论题","ex":{"en":"The basic thesis of the book is fairly simple.","cn":"该书的基本论题相当简单。"}}]}},"thunderstorm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雷暴;雷雨","en":"A thunderstorm is a storm in which there is thunder and lightning and a lot of heavy rain."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/thunderstorm0205.mp3","us":"media/ldoce/hwd/ame/f/thunderstorm.mp3"},"oxford":{"phon":"ˈθʌndəstɔːm","pos":"noun","senses":[{"en":"a storm with thunder and lightning and usually very heavy rain","cn":"雷雨；雷暴；雷雨交加","ex":{"en":"He slept well, unaware of the thunderstorms which filled the night.","cn":"他睡得很好，没有意识到整夜的雷雨。"}}]}},"throughput":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(组织、系统在一定时间内的)工作量，生产量，吞吐量","en":"The throughput of an organization or system is the amount of things it can do or deal with in a particular period of time.","ex":{"en":"...technologies which will allow us to get much higher throughput","cn":"能让我们大幅提高工作效率的技术"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of work, goods, or people that are dealt with in a particular period of time 〔","cn":"在一定时间内的〕工作量﹐吞吐量﹐接待人数"},{"en":"throughput of an airport with a weekly throughput of 100,000 passengers","cn":"每周旅客吞吐量为10万人的一个机场 high/low throughput a large store with a high throughput of goods 货物流量大的大商店"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun throughput to talk about how fast communication can travel over a channel, from input to output."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41throughput.mp3","us":"media/ldoce/hwd/ame/a/throughput.mp3"},"oxford":{"phon":"ˈθruːpʊt","pos":"noun","senses":[{"en":"the amount of work that is done, or the number of people that are dealt with, in a particular period of time","cn":"（某一时期内的）生产量，接待人数","ex":{"en":"high/low throughput","cn":"高/低吞吐量"}}]}},"thunderbolt":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"雷电；霹雳","en":"A thunderbolt is a flash of lightning, accompanied by thunder, which strikes something such as a building or a tree."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a flash of lightning which hits a person or thing and kills or destroys them 〔","cn":"击中某人或某物的〕雷电﹐霹雳"},{"en":"a sudden event or piece of news that shocks you","cn":"晴天霹雳般的事件﹔令人震惊的消息"}]},"media":{"uk":"media/ldoce/hwd/bre/b/thunderbolt0205.mp3","us":"media/ldoce/hwd/ame/f/thunderbolt.mp3"},"examples":[{"en":"The news hit them like a thunderbolt (= was very shocking).","cn":"这个消息犹如晴天霹雳使他们大为震惊。"},{"en":"The idea hit her like a thunderbolt.","cn":"这个想法让她大吃一惊。"}],"oxford":{"phon":"ˈθʌndəbəʊlt","pos":"noun","senses":[{"en":"a flash of lightning that comes at the same time as the noise of thunder and that hits something","cn":"雷电；霹雳","lab":"figurative","ex":{"en":"The news hit them like a thunderbolt (= was very shocking).","cn":"这个消息犹如晴天霹雳使他们大为震惊。"}}]}},"thrifty":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"节俭的;节省的;节约的","en":"If you say that someone is thrifty, you are praising them for saving money, not buying unnecessary things, and not wasting things.","ex":{"en":"My mother taught me to be thrifty.","cn":"我妈妈教我生活要节俭。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"spending money carefully and cleverly so that nothing is wasted and you can manage with the money you have","cn":""},{"en":"spending money only on things that are necessary or cheap because you want your money to last as long as possible","cn":""},{"en":"spending money carefully and sensibly so that you do not spend more than necessary","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Being thrifty means being careful of your money and how you spend it. Think twice before you spend, but if you must shop, hitting the sales and using coupons are good ways to be thrifty ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41thrifty.mp3","us":"media/ldoce/hwd/ame/d/thrifty.mp3"},"examples":[{"en":"hard-working, thrifty people","cn":"勤劳节俭的人们"}],"oxford":{"phon":"ˈθrɪfti","pos":"adjective","senses":[{"en":"careful about spending money and not wasting things","cn":"节约的；节俭的","ex":{"en":"He was brought up to be thrifty and never to get into debt.","cn":"他从小就被教导勤俭节约，绝不欠债。"}}]}},"thereof":{"collins":{"senses":[{"pos":"ADV 副词","cn":"其;在其中","en":"Thereof is used after a noun to relate that noun to a situation or thing that you have just mentioned.","ex":{"en":"...his belief in God — or the lack thereof.","cn":"他对上帝的信仰——或者不信仰"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"relating to something that has just been mentioned","cn":"其﹔在其中"}]},"media":{"uk":"media/ldoce/hwd/bre/0/thereof0205.mp3","us":"media/ldoce/hwd/ame/c/thereof.mp3"},"examples":[{"en":"Is the property or any part thereof used for commercial activity?","cn":"这一财产或其中任何部分是用于商业活动吗？"},{"en":"States differ in standards for products and the labelling thereof.","cn":"各州的产品标准不同﹐标签的标注也不同。"}],"oxford":{"phon":"ˌðeərˈɒv","pos":"adverb","senses":[{"en":"of the thing mentioned","cn":"在其中；由此","ex":{"en":"Is the property or any part thereof used for commercial activity?","cn":"这一财产或其中任何部分有用于商业活动吗？"}}]}},"thoracic":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"胸的;胸腔的;胸廓的","en":"Thoracic means relating to or affecting your thorax.","ex":{"en":"...diseases of the thoracic area.","cn":"胸部疾病"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of your body between your neck and diaphragm (= area just above your stomach )","cn":""},{"en":"the part of an insect’s body between its head and its abdomen","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Thoracic is a medical word for things pertaining to the thorax area of your body: your chest."}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41thorax.mp3","us":"media/ldoce/hwd/ame/e/thorax.mp3"},"oxford":{"phon":"θɔːˈræsɪk","pos":"adjective","senses":[{"en":"connected with a person's thorax (= the part of the body that is surrounded by the ribs, between the neck and the waist)","cn":"胸；胸腔","lab":"anatomy","ex":{"en":"to undergo thoracic surgery","cn":"接受胸外科手术"}},{"en":"connected with an insect's thorax (= the middle section of its body, to which the legs and wings are attached)","cn":"（昆虫的）胸，胸部","ex":{"en":"Each of the three thoracic segments bears a pair of legs.","cn":"三个胸节各有一对足。"}}]}},"therm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"撒姆(热量单位)","en":"A therm is a measurement of heat."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a unit for measuring heat, especially when calculating amounts of gas used","cn":"撒姆〔热量单位﹐尤用于计算煤气使用量〕"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41therm.mp3","us":"media/ldoce/hwd/ame/0/laadtherm.mp3"},"examples":[{"en":"UK gas was selling for as little as 6p a therm.","cn":"英国煤气每一撒姆只卖六便士。"}],"oxford":{"phon":"θɜːm","pos":"noun","senses":[{"en":"a unit of heat, used in Britain for measuring a gas supply","cn":"撒姆（英国用以计量煤气的热量单位）"}]}},"thruway":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"高速公路","en":"A thruway is a wide road that is specially designed so that a lot of traffic can move along it very quickly. It is usually divided along the middle, so that traffic travelling in one direction is separated from the traffic travelling in the opposite direction."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wide road for fast traffic that you pay to use 〔","cn":"需要付费的〕高速公路"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41thruway.mp3","us":"media/ldoce/hwd/ame/b/laadthruway.mp3"},"examples":[{"en":"the New York State Thruway","cn":"纽约州直达高速公路"}],"oxford":{"phon":"ˈθruːweɪ","pos":"noun","senses":[{"en":"used in the names of some freeways (= important roads across or between states)","cn":"（用于某些跨州或州际高速公路的名称中）过境道路，直达道路","ex":{"en":"the New York State Thruway","cn":"纽约州直达高速公路"}}]}},"thereabouts":{"collins":{"senses":[{"pos":"PHRASE 短语","cn":"(数量、日期等)大约，上下，左右","en":"You add or thereabouts after a number or date to indicate that it is approximate.","ex":{"en":"He told us that her age was forty-eight or thereabouts","cn":"他告诉我们她的年龄在48岁上下。"}}]},"ldoce":{"phon":"hwd","pos":"adverb","senses":[{"en":"a little later or a little earlier than a particular time or date","cn":""},{"en":"a little later or a little earlier than a particular time or date. Approximately is a little more formal than about or around and is used especially in written English","cn":""},{"en":"at a time in the past - use this when you do not know exactly when or it is not important exactly when","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/thereabouts0205.mp3","us":"media/ldoce/hwd/ame/1/thereabouts.mp3"},"examples":[{"en":"They paid $100 000 or thereabouts for the house.","cn":"他们买那房子花了大约 10 万元。"},{"en":"He comes from Leeds or thereabouts.","cn":"他是利兹或其附近的人。"}],"oxford":{"phon":"ˌðeərəˈbaʊts","pos":"adverb","senses":[{"en":"near the place mentioned","cn":"在那附近","ex":{"en":"He comes from Leeds or thereabouts.","cn":"他是利兹或其周边的人。"}},{"en":"used to say that a particular number, quantity, time, etc. is not exact","cn":"（数量、时间等）大约，左右，上下","ex":{"en":"They paid $100 000 or thereabouts for the house.","cn":"他们买那房子花了大约 10 万美元。"}}]}},"thalidomide":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"酞胺哌啶酮，反应停(原为孕妇用药，被发现会导致胎儿四肢畸形后停用)","en":"Thalidomide is a drug which used to be given to pregnant women, before it was discovered that it resulted in babies being born with wrongly shaped arms and legs."},{"pos":"ADJ 形容词","cn":"(由于母亲怀孕期间服用了反应停导致的)四肢畸形的","en":"Thalidomide is used to describe someone whose arms and legs are wrongly shaped because their mother took thalidomide when she was pregnant.","ex":{"en":"...the special needs of thalidomide children.","cn":"四肢畸形儿童的特殊需要"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a drug given to people to make them calm, until it was discovered that it harmed the development of the arms and legs of unborn babies","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thalidomide.mp3","us":"media/ldoce/hwd/ame/6/thalidomide.mp3"},"oxford":{"phon":"θəˈlɪdəmaɪd","pos":"noun","senses":[{"en":"a sedative drug that was given in the past to pregnant women before it was discovered that it harmed their babies, especially in the development of their arms and legs","cn":"酞胺呱啶酮，反应停（一种镇定药，20 世纪 60 年代发现孕妇服用后会导致胎儿四肢畸形而被禁用）"}]}},"thick-skinned":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厚脸皮的;不知羞耻的","en":"If you say that someone is thick-skinned, you mean that they are not easily upset by criticism or unpleasantness.","ex":{"en":"He was thick-skinned enough to cope with her taunts.","cn":"他脸皮厚，不怕她嘲弄。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not easily offended by other people’s criticism or insults","cn":"厚脸皮的﹐受得起批评[羞辱]的"}]},"vocab":{"pos":"adj","senses":[{"en":"To be thick-skinned is to not be bothered by criticism and rejection. When you're thick-skinned , you're mentally tough."}]},"media":{"uk":"media/ldoce/hwd/bre/1/thick_skinned0205.mp3","us":"media/ldoce/hwd/ame/c/thick-skinned.mp3"},"examples":[{"en":"a thick-skinned insurance salesman","cn":"一位厚脸皮的保险推销员"}],"oxford":{"phon":"ˌθɪk ˈskɪnd","pos":"adjective","senses":[{"en":"not easily upset by criticism or unkind comments","cn":"厚脸皮的；不计较脸面的；（对批评或侮辱）不易生气的","ex":{"en":"You have to be pretty thick-skinned to do this job.","cn":"你脸皮必须够厚才能干这份工作。"}},{"en":"having a thick skin","cn":"皮厚的","ex":{"en":"a thick-skinned variety of grape","cn":"厚皮葡萄品种"}}]}},"throughway":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a thruway 〔","cn":"需要付费的〕高速公路"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41throughway.mp3","us":"media/ldoce/hwd/ame/b/laadthruway.mp3"},"oxford":{"phon":"ˈθruːweɪ","pos":"noun","senses":[{"en":"used in the names of some freeways (= important roads across or between states)","cn":"（用于某些跨州或州际高速公路的名称中）过境道路，直达道路"}]}},"thrall":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"控制;奴役;束缚","en":"If you say that someone is in thrall to a person or thing, you mean that they are completely in their power or are greatly influenced by them.","ex":{"en":"He is not in thrall to the media","cn":"他不受制于媒体。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"controlled or strongly influenced by someone or something","cn":"在某人/某事的奴役[束缚﹐控制]之下"}]},"vocab":{"pos":"n","senses":[{"en":"When you're in thrall to someone, you are under their control in some way. If you're being held as a hostage, you're in thrall to your captor."}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thrall.mp3","us":"media/ldoce/hwd/ame/e/thrall.mp3"},"examples":[{"en":"We have a congress that is in thrall to special interest groups.","cn":"我们的国会受制于一些特殊利益集团。"}]},"thumbtack":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"图钉","en":"A thumbtack is a short pin with a broad flat top which is used for fastening papers or pictures to a board, wall, or other surface."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short pin with a flat top that is used for fixing notices on walls","cn":"图钉﹐按钉"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41thumbtack.mp3","us":"media/ldoce/hwd/ame/e/thumbtack.mp3"},"oxford":{"phon":"ˈθʌmtæk","pos":"noun","senses":[{"en":"a short pin with a large round, flat head, used especially for fastening paper to a board or wall","cn":"图钉"}]}},"thousandth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第一千","en":"The thousandth item in a series is the one that you count as number one thousand.","ex":{"en":"The magazine has just published its six thousandth edition.","cn":"这本杂志刚刚出版了第 6,000 期。"}},{"pos":"FRACTION 分数词","cn":"千分之一","en":"A thousandth is one of a thousand equal parts of something.","ex":{"en":"...a dust particle weighing only a thousandth of a gram.","cn":"重量仅有千分之一克的灰尘微粒"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 1,000","cn":""},{"en":"an extremely large number of things or people","cn":""},{"en":"the number 1,000","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thousand.mp3","us":"media/ldoce/hwd/ame/8/l3thousand.mp3"},"examples":[{"en":"the city's thousandth anniversary","cn":"这座城市的一千周年纪念"},{"en":"a/one thousandth of a second","cn":"千分之一秒"}],"oxford":{"phon":"ˈθaʊznθ","pos":"ordinal number","senses":[{"en":"1 000th","cn":"第一千","ex":{"en":"the city’s thousandth anniversary","cn":"这座城市的一千周年纪念"}},{"en":"each of one thousand parts of something","cn":"千分之一","ex":{"en":"a/one thousandth of a second","cn":"千分之一秒"},"pos":"noun"}]}},"thermos":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"保温瓶;暖水瓶;冰瓶","en":"A Thermos ,Thermos flask, or in American English Thermos bottle, is a container which is used to keep hot drinks hot or cold drinks cold. It has two thin shiny glass walls with no air between them."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a special container like a bottle, that keeps drinks hot or cold","cn":"膳魔师保温杯[瓶]"}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdethermos.mp3","us":"media/ldoce/hwd/ame/f/laadthermos.mp3","img":["media/ldoce/img/thermos.jpg"]},"oxford":{"phon":"ˈθɜːməs","pos":"noun","senses":[{"en":"a particular kind of vacuum flask (= a container like a bottle with double walls with a vacuum between them, used for keeping liquids hot or cold)","cn":"膳魔师保温（或保冷）瓶"}]}},"thumbnail":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拇指甲","en":"Your thumbnail is the nail on your thumb."},{"pos":"ADJ 形容词","cn":"简要的;概括的;简略的","en":"A thumbnail sketch or account is a very short description of an event, idea, or plan which gives only the main details."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a short description that gives only the main facts about a person, thing, or event","cn":"简略的描述"},{"en":"the nail on your thumb","cn":"拇指甲"},{"en":"a small picture of a document on a computer screen, showing you what it will look like when you print it 〔","cn":"计算机屏幕上显示的〕缩略图"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41thumbnail.mp3","us":"media/ldoce/hwd/ame/6/thumbnail1.mp3"},"examples":[{"en":"a thumbnail sketch of recent political events in America","cn":"对美国最近政治事件的简略描述"},{"en":"Click on the thumbnails to view a larger version of each image.","cn":"点击缩略图﹐可以看到每个图像的大图。"}],"oxford":{"phon":"ˈθʌmneɪl","pos":"noun","senses":[{"en":"the nail on the thumb","cn":"拇指指甲"},{"en":"a very small picture on a computer screen that shows you what a larger picture looks like, or what a page of a document will look like when you print it","cn":"索引图像；（打印预览）缩略图","lab":"computing"}]}},"thrum":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(机器、引擎)嗡嗡响，发出沉闷声","en":"When something such as a machine or engine thrums, it makes a low beating sound.","ex":{"en":"The air-conditioner thrummed.","cn":"空调嗡嗡作响。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make a low sound like the sound of an engine","cn":"发低沉的嗡嗡声"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41thrum.mp3","us":"media/ldoce/hwd/ame/4/thrum.mp3"},"examples":[{"en":"The engine thrummed into life.","cn":"引擎轰轰地发动了起来。"}]},"thermonuclear":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(武器、设备)热核的","en":"A thermo-nuclear weapon or device is one which uses the high temperatures that result from a nuclear reaction in order to cause it to explode."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"thermonuclear weapons use a nuclear reaction, involving the splitting of atoms, to produce very high temperatures and a very powerful explosion","cn":"热核的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/thermonuclear0205.mp3","us":"media/ldoce/hwd/ame/1/thermonuclear.mp3"},"examples":[{"en":"a thermonuclear device","cn":"热核装置"}],"oxford":{"phon":"ˌθɜːməʊˈnjuːkliə(r)","pos":"adjective","senses":[{"en":"connected with nuclear reactions that only happen at very high temperatures","cn":"热核的","ex":{"en":"a thermonuclear reaction","cn":"热核反应。"}}]}},"threshold":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"门槛;门口","en":"The threshold of a building or room is the floor in the doorway, or the doorway itself.","ex":{"en":"He stopped at the threshold of the bedroom","cn":"他在卧室门口停住了。"}},{"pos":"N-COUNT 可数名词","cn":"(某事发生或改变的)界限，阈，起始点","en":"A threshold is an amount, level, or limit on a scale. When the threshold is reached, something else happens or changes.","ex":{"en":"She has a low threshold of boredom and needs the constant stimulation of physical activity","cn":"她容易厌倦，需要时常进行活动来刺激一下。"}},{"pos":"PHRASE 短语","cn":"在…开端;将要经历;面临着","en":"If you are on the threshold of something exciting or new, you are about to experience it.","ex":{"en":"We are on the threshold of a new era in astronomy.","cn":"我们很快就将迎来天文学的新纪元。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the smallest amount or number of something","cn":""},{"en":"the minimum number or amount is the smallest number or amount that is possible or allowed","cn":""},{"en":"the least amount of something that is allowed within a range","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"A threshold is what you step across when you enter a room. A threshold takes you from one place into another, and when you're about to start something new, you're also on a threshold."}]},"collocations":{"phrases":["VERB + THRESHOLD cross","PREP. across/over the ~ He hesitated before stepping across the threshold. | on the ~ She stood on the threshold, unsure whether to enter. 2","ADJ. high, low | maximum, minimum | critical | earnings, tax | boredom, pain She has an extremely low boredom threshold.","VERB + THRESHOLD have | reach The number of people with the disease is reaching a critical threshold. | cross, exceed | set They earn wages ","THRESHOLD + NOUN level, value Below a certain threshold level a person will not be able to detect sound.","PREP. above/below a/the ~ Her wages are below the income tax threshold."]},"media":{"uk":"media/ldoce/hwd/bre/1/threshold0205.mp3","us":"media/ldoce/hwd/ame/2/threshold.mp3"},"examples":[{"en":"She felt as though she was on the threshold of a new life.","cn":"她觉得好像就要开始新生活了。"},{"en":"My earnings are just above the tax threshold (= more than the amount at which you start paying tax).","cn":"我的收入刚刚超过征税起点。"}],"oxford":{"phon":"ˈθreʃhəʊld","pos":"noun","senses":[{"en":"the floor or ground at the bottom of a doorway, considered as the entrance to a building or room","cn":"门槛；门口","ex":{"en":"He stepped across the threshold.","cn":"他迈过门槛。"}},{"en":"the level at which something starts to happen or have an effect","cn":"阈；界；起始点","ex":{"en":"He has a low boredom threshold (= he gets bored easily).","cn":"他极易感到乏味。"}},{"en":"the point just before a new situation, period of life, etc. begins","cn":"开端；起点；入门","g":"[usually singular]","ex":{"en":"She felt as though she was on the threshold of a new life.","cn":"她觉得好像就要开始新生活了。"}}]}},"theologian":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"神学家;神学研究人员","en":"A theologian is someone who studies the nature of God, religion, and religious beliefs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who has studied theology","cn":"神学家﹐神学研究者"}]},"vocab":{"pos":"n","senses":[{"en":"A college student who majors in religion may decide to become a theologian , or an expert in the study of religion."}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41theologian.mp3","us":"media/ldoce/hwd/ame/b/theologian.mp3"},"oxford":{"phon":"ˌθiːəˈləʊdʒən","pos":"noun","senses":[{"en":"a person who studies theology","cn":"神学家；神学研究者"}]}},"thoroughgoing":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"完全的;十足的","en":"You use thoroughgoing to emphasize that someone or something is fully or completely the type of person or thing specified.","ex":{"en":"...a thoroughgoing conservative.","cn":"不折不扣的保守派"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"仔细的;彻底的","en":"If you describe a piece of work as thoroughgoing, you approve of it because it has been carefully and thoroughly put together.","ex":{"en":"...a thoroughgoing review of prison conditions.","cn":"对监狱环境的一次彻底检查"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very thorough and careful","cn":"彻底的﹔仔细的"},{"en":"a thoroughgoing action or quality is complete","cn":"完全的﹐十足的"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41thoroughgoing.mp3","us":"media/ldoce/hwd/ame/1/thoroughgoing.mp3"},"examples":[{"en":"a thoroughgoing revision of the text","cn":"对文本认真仔细的校订"},{"en":"a thoroughgoing commitment to change","cn":"对变革的全面承诺"}],"oxford":{"phon":"ˌθʌrəˈɡəʊɪŋ","pos":"adjective","senses":[{"en":"very careful and complete; looking at every detail","cn":"彻底的；仔细的","ex":{"en":"a thoroughgoing revision of the text","cn":"对文本认真仔细的校订"}},{"en":"complete","cn":"完全的；全面的；彻底的","ex":{"en":"a thoroughgoing commitment to change","cn":"对变革的全面承诺"}}]}},"thistle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蓟(叶片带刺、开紫色花的野生植物)","en":"A thistle is a wild plant which has leaves with sharp points and purple flowers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wild plant which has leaves with sharp points and purple or white furry flowers","cn":"蓟〔一种叶片带刺﹑开紫色或白色毛茸状花朵的野生植物〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/thistle0205.mp3","us":"media/ldoce/hwd/ame/a/thistle.mp3","img":["media/thumb/thistle.jpg"]},"oxford":{"phon":"ˈθɪsl","pos":"noun","senses":[{"en":"a wild plant with leaves with sharp points and purple, yellow or white flowers made up of a mass of narrow petals pointing upwards. The thistle is the national symbol of Scotland.","cn":"蓟（野生植物，叶有刺，花呈紫色、黄色或白色，为苏格兰民族象征）"}]}},"throes":{"collins":{"senses":[{"pos":"N-PLURAL 复数名词","cn":"(尤指最后阶段的)困境,痛苦","en":"If someone is experiencing something very unpleasant or emotionally painful, you can say that they are in the throes of it, especially when it is in its final stages.","ex":{"en":"...when the country was going through the final throes of civil war.","cn":"当时这个国家正处在内战最后的痛苦关头"}},{"pos":"PREP-PHRASE 短语介词","cn":"正忙于…;处于…困境之中","en":"If you are in the throes of doing or experiencing something, especially something difficult, you are busy doing it or are deeply involved in it.","ex":{"en":"The country is in the throes of a general election","cn":"该国正忙于大选。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to experience physical or emotional pain when something bad happens to you","cn":""},{"en":"to experience pain or have difficult or unpleasant experiences over a long period - use this especially about people who are brave and patient","cn":""},{"en":"to experience a lot of problems in your life over a long period of time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Did your team just lose the Super Bowl or the World Series? You're probably in the throes of despair — experiencing intense feelings of suffering and agitation."}]},"media":{"uk":"media/ldoce/hwd/bre/e/throes0205.mp3","us":"media/ldoce/hwd/ame/1/throes.mp3"},"examples":[{"en":"The creature went into its death throes.","cn":"这小生命到了临终疼痛阶段。"},{"en":"The country was in the throes of revolutionary change.","cn":"国家正处于革命动荡中。"}],"oxford":{"phon":"θrəʊz","pos":"noun","senses":[{"en":"violent pains, especially at the moment of death","cn":"（尤指死亡时的）剧痛","ex":{"en":"The creature went into its death throes.","cn":"这个生命到了临终疼痛阶段。"}}]}},"thematic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"主题的;专题的;主旨的","en":"Thematic means concerned with the subject or theme of something, or with themes and topics in general.","ex":{"en":"...assembling this material into thematic groups.","cn":"按主题将这些材料整理分类"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to a particular theme , or organized according to a theme","cn":"主题的﹔专题的﹔题目的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"When you visit a museum and the cat paintings are grouped together in one room, and the fruit paintings in another, you could conclude that the curator favors a thematic arrangement, meaning grouped by topic, rather than chronologically or by artist."}]},"media":{"uk":"media/ldoce/hwd/bre/0/thematic0205.mp3","us":"media/ldoce/hwd/ame/e/laadthematic.mp3"},"examples":[{"en":"The books have been grouped thematically.","cn":"这些书籍已按专题进行了分类。"},{"en":"the thematic structure of a text","cn":"文本的主题结构"}],"oxford":{"phon":"θɪˈmætɪk","pos":"adjective","senses":[{"en":"connected with the theme or themes of something","cn":"题目的；主题的","ex":{"en":"the thematic structure of a text","cn":"文本的主题结构"}}]}},"thwack":{"collins":{"senses":[{"pos":"N-COUNT; SOUND 可数名词；声音词","cn":"撞击声;拍打声","en":"A thwack is a sound made when two solid objects hit each other hard.","ex":{"en":"I listened to the thwack of the metal balls","cn":"我听着金属球相撞的声音。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a short loud sound like something hitting a hard surface","cn":"拍打（声）﹔重击（声）"}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41thwack.mp3","us":"media/ldoce/hwd/ame/1/ld41thwack.mp3"},"examples":[{"en":"the thwack of bat on ball","cn":"球拍击球"}],"oxford":{"phon":"θwæk","pos":"noun","senses":[{"en":"the action of hitting somebody/something hard, making a short loud sound; the short loud sound made by this action","cn":"重击；拍打；使劲打","ex":{"en":"She gave him a playful thwack on the arm.","cn":"她顽皮地拍了一下他的手臂。"}},{"en":"to hit somebody/something hard, making a short, loud sound","cn":"重击；拍打；使劲打","pos":"verb"}]}},"thickset":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗壮的;壮实的","en":"A man who is thickset is broad and heavy, with a solid-looking body.","ex":{"en":"He was of middle height, thick-set.","cn":"他中等个头，身体壮实。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a wide strong body 〔","cn":"身体〕粗壮的﹐壮实的"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41thickset.mp3","us":"media/ldoce/hwd/ame/1/thickset.mp3"},"examples":[{"en":"a short thickset man","cn":"一个膀阔腰圆的矮个子男人"}],"oxford":{"phon":"θɪkˈset","pos":"adjective","senses":[{"en":"having a strong, heavy body","cn":"身体粗壮的；膀阔腰圆的；虎背熊腰的","ex":{"en":"He has the same thickset build as his father.","cn":"他和他父亲一样粗壮。"}}]}},"thrash":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(在比赛、竞赛中)轻松击败，以大比分战胜","en":"If one player or team thrashes another in a game or contest, they defeat them easily or by a large score.","ex":{"en":"Second-placed Rangers thrashed St Johnstone 5-nil.","cn":"排名第二的流浪者队以 5: 0 大胜圣约翰斯通队。"}},{"pos":"VERB 动词","cn":"(作为惩罚)连续击打，接连殴打，痛打","en":"If you thrash someone, you hit them several times as a punishment.","ex":{"en":"'Liar!' Sarah screamed, as she thrashed the child. 'You stole it.'","cn":"“叫你撒谎！”萨拉一边揍着孩子，一边尖叫道，“就是你偷的。”"}},{"pos":"V-ERG 及物/不及物动词","cn":"猛烈摆动;翻来覆去;剧烈扭动(四肢)","en":"If someone thrashes about, or thrashes their arms or legs about, they move in a wild or violent way, often hitting against something. You can also say that someone's arms or legs thrash about .","ex":{"en":"Many of the crew died a terrible death as they thrashed about in shark-infested waters","cn":"很多船员在鲨鱼成群的水域中拼命挣扎，死状惨不忍睹。"}},{"pos":"VERB 动词","cn":"连续击打;猛烈抽打","en":"If a person or thing thrashes something, or thrashes at something, they hit it continually in a violent or noisy way.","ex":{"en":"...a magnificent paddle-steamer on the mighty Mississippi, her huge wheel thrashing the muddy water","cn":"广阔的密西西比河上行驶着一艘豪华庞大的明轮船，她巨大的轮子拍打着浑浊的河水"}},{"pos":"N-COUNT 可数名词","cn":"派对;聚会","en":"A thrash is a party.","ex":{"en":"Harry always invited Charlie when he threw a thrash in his office.","cn":"哈里在办公室开派对时总不忘叫上查利。"}},{"pos":"","cn":"","en":"相关词组：thrash out"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get more points, votes etc than someone. Beat is used especially in spoken English","cn":""},{"en":"to beat someone. Defeat is more formal than beat and is used especially in writing","cn":""},{"en":"to defeat someone completely in a game","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 v","senses":[{"en":"When you thrash someone, you beat them — literally, with your fists, or figuratively, by winning a game or competition."}]},"collocations":{"phrases":["ADV. soundly That boy deserves to be soundly thrashed!","PREP. with He thrashed the poor servant with his stick. 2 move your arms and legs in an uncontrolled way","ADV. helplessly, violently, wildly | about, around The cow fell on its side and thrashed about wildly. 3 defeat sb easily in a game","ADV. soundly The visiting side were soundly thrashed."]},"media":{"uk":"media/ldoce/hwd/bre/5/thrash_n0205.mp3","us":"media/ldoce/hwd/ame/9/thrash.mp3"},"examples":[{"en":"Someone was thrashing around in the water, obviously in trouble.","cn":"有人在水里乱扑腾，显然遇到了危险。"},{"en":"Scotland thrashed England 5–1.","cn":"苏格兰队以 5:1 大胜英格兰队。"}],"oxford":{"phon":"θræʃ","pos":"verb","senses":[{"en":"to hit a person or an animal many times with a stick, etc. as a punishment","cn":"（作为惩罚用棍子等）抽打，连续击打","g":"[transitive]","ex":{"en":"My father used to thrash me if I got home late.","cn":"如果我回家晚了，我父亲就会打我。"}},{"en":"to move or make something move in a way that is violent or shows a loss of control","cn":"（使）激烈扭动，翻来覆去","g":"[intransitive, transitive]","ex":{"en":"Someone was thrashing around in the water, obviously in trouble.","cn":"有人在水里乱扑腾，显然遇到了危险。"}},{"en":"to defeat somebody very easily in a game","cn":"（在比赛中）轻易击败，一举战胜","g":"[transitive]","lab":"informal, especially British English，，","ex":{"en":"Scotland thrashed England 5–1.","cn":"苏格兰队以 5:1 大胜英格兰队。"}},{"en":"a type of loud rock music","cn":"快节奏重金属摇滚乐","g":"[uncountable]","pos":"noun"},{"en":"a party with music and dancing","cn":"载歌载舞的聚会","g":"[countable]","lab":"old-fashioned, informal，，","pos":"noun"}]}},"thirdly":{"collins":{"senses":[{"pos":"ADV 副词","cn":"第三(点)","en":"You use thirdly when you want to make a third point or give a third reason for something.","ex":{"en":"First of all, there are not many of them, and secondly, they have little money and, thirdly, they have few big businesses.","cn":"首先，他们人数不多;第二，他们钱很少;第三，他们没有几家大企业。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"coming after two other things in a series","cn":""},{"en":"used when you have failed to do something twice and hope to be successful the third time","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld42third.mp3","us":"media/ldoce/hwd/ame/2/third.mp3"},"examples":[{"en":"Thirdly, I would like to say that …","cn":"第三，我想说 …"},{"en":"in the third century","cn":""}],"oxford":{"phon":"ˈθɜːdli","pos":"adverb","senses":[{"en":"used to introduce the third of a list of points you want to make in a speech or piece of writing","cn":"（用于讲话或文章中列举事项）第三，第三点","ex":{"en":"Thirdly, I would like to say that…","cn":"第三，我想说…"}}]}},"thunderous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)轰隆隆的，低沉的，低吼的","en":"If you describe a noise as thunderous, you mean that it is very loud and deep.","ex":{"en":"The audience responded with thunderous applause.","cn":"观众报以雷鸣般的掌声。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely loud and deep in sound","cn":""},{"en":"so loud that you cannot hear anything else","cn":""},{"en":"so loud that your ears feel uncomfortable","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/f/thunderous0205.mp3","us":"media/ldoce/hwd/ame/9/thunderous.mp3"},"examples":[{"en":"his thunderous expression","cn":"他那气势汹汹的表情"},{"en":"thunderous applause","cn":"雷鸣般的掌声"}],"oxford":{"phon":"ˈθʌndərəs","pos":"adjective","senses":[{"en":"very loud","cn":"雷鸣般的；非常响亮的","ex":{"en":"thunderous applause","cn":"雷鸣般的掌声"}},{"en":"looking very angry","cn":"怒容满面的；面色阴沉的；怒气冲冲的","ex":{"en":"his thunderous expression","cn":"他那气势汹汹的表情"}}]}},"thermometer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"温度计;体温表;寒暑表","en":"A thermometer is an instrument for measuring temperature. It usually consists of a narrow glass tube containing a thin column of a liquid which rises and falls as the temperature rises and falls."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of equipment that measures the temperature of the air, of your body etc","cn":"温度计﹐寒暑表﹔体温计"}]},"vocab":{"pos":"n","senses":[{"en":"A thermometer is a tool that measures temperature — how hot or cold something is. Thermometers are used to see if you have a fever or tell you how cold it is outside."}]},"collocations":{"phrases":["ADJ. accurate | clinical | digital, mercury | rectal | meat, sugar Check that the roast is cooked right through, using a meat thermometer.","VERB + THERMOMETER read","THERMOMETER + VERB measure sth","THERMOMETER + NOUN reading","PREP. on a/the ~ the reading on the thermometer"]},"media":{"uk":"media/ldoce/hwd/bre/2/thermometer0205.mp3","us":"media/ldoce/hwd/ame/f/thermometer.mp3"},"examples":[{"en":"a thermometer reading","cn":"温度计读数"},{"en":"The thermometer registered over 100º C.","cn":"温度计显示高于100摄氏度。"}],"oxford":{"phon":"θəˈmɒmɪtə(r)","pos":"noun","senses":[{"en":"an instrument used for measuring the temperature of the air, a person’s body, etc.","cn":"温度计；寒暑表；体温计","ex":{"en":"a thermometer reading","cn":"温度计读数"}}]}},"thug":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"恶棍;凶手;罪犯","en":"You can refer to a violent person or criminal as a thug .","ex":{"en":"...the cowardly thugs who mug old people.","cn":"抢劫老人的胆小恶棍"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man, especially a criminal, who has rough manners and uses violent methods","cn":""},{"en":"if you call a man a brute , you mean he is cruel and violent and does not care if he hurts people","cn":""},{"en":"a violent young man, often a member of a group, who enjoys causing damage and hurting people, especially in public places","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A thug is a bad guy or a bully, especially a violent one. A thug might break into someone's house, push its owners around, and steal their TV."}]},"collocations":{"phrases":["ADJ. teenage, young | vicious | armed, knife-wielding | racist | football, soccer","QUANT. gang He was beaten up by a gang of thugs."]},"media":{"uk":"media/ldoce/hwd/bre/3/thug0205.mp3","us":"media/ldoce/hwd/ame/6/thug.mp3"},"examples":[{"en":"thuggish brutality","cn":"残忍的暴行"},{"en":"a gang of thugs","cn":"一伙暴徒"}],"oxford":{"phon":"θʌɡ","pos":"noun","senses":[{"en":"a violent person, especially a criminal","cn":"恶棍；暴徒；罪犯","ex":{"en":"He was beaten up by a gang of thugs.","cn":"他让一伙流氓给暴打了一顿。"}}]}},"thirst":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"渴;口渴","en":"Thirst is the feeling that you need to drink something.","ex":{"en":"Coca is well-known for reducing hunger, thirst and fatigue","cn":"人们都知道可乐能消饿、止渴和解乏。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"干渴;缺水","en":"Thirst is the condition of not having enough to drink.","ex":{"en":"They died of thirst on the voyage.","cn":"他们在航行途中因缺水而死亡。"}},{"pos":"N-SING 单数名词","cn":"渴望;渴求","en":"A thirst for something is a very strong desire for that thing.","ex":{"en":"Children show a real thirst for learning.","cn":"孩子们对于学习表现出真诚的渴望。"}},{"pos":"VERB 动词","cn":"渴望;渴求","en":"If you say that someone thirsts for something, you mean that they have a strong desire for it.","ex":{"en":"We all thirst for the same things.","cn":"我们都渴望得到同样的东西。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to take liquid into your mouth and swallow it","cn":""},{"en":"to have a drink of something","cn":""},{"en":"to drink a small amount or a single mouthful of something","cn":""}]},"collocations":{"phrases":["ADJ. great, intense, raging, terrible, unquenchable","VERB + THIRST suffer from Many of the refugees were suffering badly from thirst. | quench, slake | die of | work up After walking five miles","ADJ. great, unquenchable He has an unquenchable thirst for knowledge.","VERB + THIRST have | satisfy","PREP. ~ for"]},"media":{"uk":"media/ldoce/hwd/bre/2/thirst_v0205.mp3","us":"media/ldoce/hwd/ame/5/thirst1.mp3"},"examples":[{"en":"She woke up with a raging thirst and a headache.","cn":"她醒来后，感到头痛，口渴难忍。"},{"en":"Thousands are dying of thirst.","cn":"成千上万的人都干渴得奄奄一息。"}],"oxford":{"phon":"θɜːst","pos":"noun","senses":[{"en":"the feeling of needing or wanting a drink","cn":"口渴；干渴感","g":"[uncountable, singular]","ex":{"en":"He quenched his thirst with a long drink of cold water.","cn":"他喝了好多冷水解渴。"}},{"en":"the state of not having enough water to drink","cn":"渴；干渴","g":"[uncountable]","ex":{"en":"Thousands are dying of thirst.","cn":"成千上万的人都干渴得奄奄一息。"}},{"en":"a strong desire for something","cn":"渴望；渴求","g":"[singular]","ex":{"en":"a thirst for knowledge","cn":"如饥似渴的求知欲"}},{"en":"to be thirsty","cn":"渴；想喝水","pos":"verb"}]}},"thumping":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极大的;了不起的;严重的","en":"Thumping is used to emphasize that something is very great or severe.","ex":{"en":"The Right has a thumping majority","cn":"右派占绝大多数。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very big or great","cn":"非常大的﹐极大的"},{"en":"thumping music has a strong loud beat 〔","cn":"音乐〕节奏有力声音响亮的"},{"en":"a very bad headache","cn":"极度头疼"}]},"media":{"uk":"media/ldoce/hwd/bre/7/thumping0205.mp3","us":"media/ldoce/hwd/ame/f/laadthumping1.mp3"},"examples":[{"en":"( BrE ) He told us a thumping great lie.","cn":"他对我们撒了一个弥天大谎。"},{"en":"a thumping majority","cn":"压倒的多数"}],"oxford":{"phon":"ˈθʌmpɪŋ","pos":"adverb","senses":[{"en":"very big; very good","cn":"很大的；巨大的","ex":{"en":"He told us a thumping great lie.","cn":"他对我们撒了个弥天大谎。"}},{"en":"very big","cn":"很大的；巨大的","ex":{"en":"a thumping majority","cn":"压倒的多数"},"pos":"adjective"}]},"base":"thump"},"theorize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"从理论上说明;建立理论","en":"If you theorize that something is true or theorize about it, you develop an abstract idea or set of ideas about something in order to explain it.","ex":{"en":"Police are theorizing that the killers may be posing as hitchhikers","cn":"警方推测那些杀手可能会假装成搭便车的人。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to think of a possible explanation for an event or fact","cn":"建立理论﹔从理论上说明"}]},"media":{"uk":"media/ldoce/hwd/bre/c/theorize0205.mp3","us":"media/ldoce/hwd/ame/9/theorize.mp3"},"examples":[{"en":"The study theorizes about the role of dreams in peoples' lives.","cn":"这项研究从理论上说明了梦在人们一生中的作用。"},{"en":"Researchers theorize that there was once a common language for all humanity.","cn":"研究者提出一种理论﹐称人类曾使用同一种语言。"}],"oxford":{"phon":"ˈθɪəraɪz","pos":"verb","senses":[{"en":"to suggest facts and ideas to explain something; to form a theory or theories about something","cn":"从理论上说明；形成理论；理论化","ex":{"en":"The study theorizes about the role of dreams in peoples' lives.","cn":"这项研究从理论上说明了梦在人们生活中的作用。"}}]}},"thriller":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"惊险小说(或电影、戏剧)","en":"A thriller is a book, film, or play that tells an exciting fictional story about something such as criminal activities or spying.","ex":{"en":"...a tense psychological thriller.","cn":"扣人心弦的心理惊悚片"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a series of images that tell a story and are shown in a cinema or on television","cn":""},{"en":"a film – used especially by people who make films or by critics","cn":""},{"en":"a very successful film","cn":""}]},"collocations":{"phrases":["ADJ. gripping | best-selling | comedy, erotic, mystery, political, psychological, sci-fi/science fiction, spy a gripping political thriller","VERB + THRILLER publish, write She had always wanted to write a spy thriller. | read","THRILLER + NOUN writer","PREP. in a/the ~ one of the characters in the thriller | ~ by a new thriller by this American writer"]},"media":{"uk":"media/ldoce/hwd/bre/6/thriller0205.mp3","us":"media/ldoce/hwd/ame/9/thriller.mp3"},"oxford":{"phon":"ˈθrɪlə(r)","pos":"noun","senses":[{"en":"a book, play or film with an exciting story, especially one about crime or spying","cn":"（尤指关于罪案或间谍的）惊险小说（或戏剧、电影）","ex":{"en":"a spy thriller","cn":"惊险间谍小说(或电影等)"}}]}},"thrift":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"节俭;节省;节约","en":"Thrift is the quality and practice of being careful with money and not wasting things.","ex":{"en":"They were rightly praised for their thrift and enterprise.","cn":"他们勤俭节约，积极进取，得到了当之无愧的赞扬。"}},{"pos":"N-COUNT 可数名词","cn":"储蓄银行","en":"A thrift or a thrift institution is a kind of savings bank."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"wise and careful use of money, so that none is wasted","cn":"节省﹐节俭"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Thrift means being very careful about how much money you spend. Reusing the same tea bag ten times so as not to waste money is a kind of thrift ."}]},"media":{"uk":"media/ldoce/hwd/bre/5/thrift0205.mp3","us":"media/ldoce/hwd/ame/f/thrift.mp3"},"oxford":{"phon":"θrɪft","pos":"noun","senses":[{"en":"the habit of saving money and spending it carefully so that none is wasted","cn":"节约；节俭","lab":"approving"},{"en":"a wild plant with bright pink flowers that grows by the sea","cn":"海石竹（海边野生植物，花鲜艳，呈粉红色）"}]}},"thunderstruck":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"极其惊讶的;震惊的","en":"If you say that someone is thunderstruck, you mean that they are extremely surprised or shocked."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely surprised or shocked","cn":"大吃一惊的﹐目瞪口呆的"}]},"vocab":{"pos":"adj","senses":[{"en":"When you’re thunderstruck , you’re dumbfounded by something. Only something very shocking can leave you thunderstruck . If you walk by a statue in the park and it starts talking to you, you’ll probably be thunderstruck ."}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41thunderstruck.mp3","us":"media/ldoce/hwd/ame/5/thunderstruck.mp3"},"examples":[{"en":"Jeff looked thunderstruck when he saw me.","cn":"杰夫见到我时惊得目瞪口呆。"}],"oxford":{"phon":"ˈθʌndəstrʌk","pos":"adjective","senses":[{"en":"extremely surprised and shocked","cn":"大吃一惊"}]}},"thrust":{"collins":{"senses":[{"pos":"VERB 动词","cn":"猛推;猛塞;刺;戳","en":"If you thrust something or someone somewhere, you push or move them there quickly with a lot of force.","ex":{"en":"They thrust him into the back of a jeep","cn":"他们把他硬塞进吉普车后座。"}},{"pos":"VERB 动词","cn":"挤;推;扎","en":"If you thrust your way somewhere, you move there, pushing between people or things which are in your way.","ex":{"en":"She thrust her way into the crowd","cn":"她一头扎进人群。"}},{"pos":"VERB 动词","cn":"露在外面;凸出来","en":"If something thrusts up or out of something else, it sticks up or sticks out in a noticeable way.","ex":{"en":"An aerial thrust up from the grass verge","cn":"一根天线在草地边上竖立着。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(车辆等的)推力，反压力，侧向压力","en":"Thrust is the power or force that is required to make a vehicle move in a particular direction.","ex":{"en":"It provides the thrust that makes the craft move forward.","cn":"它提供了飞机前进所需的推力。"}},{"pos":"N-SING 单数名词","cn":"(活动、思想的)要点，主要内容，要旨","en":"The thrust of an activity or of an idea is the main or essential things it expresses.","ex":{"en":"The real thrust of the film is its examination of New York's Hasidic community","cn":"这部电影的真正要旨是它审视了纽约的哈西德教徒。"}},{"pos":"","cn":"","en":"cut and thrust→see: ;"},{"pos":"","cn":"","en":"相关词组：thrust upon"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to move something to a particular place","cn":""},{"en":"to put something somewhere carefully","cn":""},{"en":"to put someone or something down carefully on a flat surface","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 v 4 n","senses":[{"en":"To thrust is to push forward quickly and forcibly, like the way a pirate would plunge or thrust a sword into his enemy."}]},"collocations":{"phrases":["ADV. deep/deeply | hard | suddenly She suddenly thrust out her arm. | aside, away, back, forward, out","PREP. at He thrust a piece of paper at me. | into She thrust her hands deep into her pockets.","PHRASES thrust your way She thrust her way through the dense undergrowth."]},"media":{"uk":"media/ldoce/hwd/bre/6/thrust_n0205.mp3","us":"media/ldoce/hwd/ame/a/thrust1.mp3"},"examples":[{"en":"She was annoyed at having three extra guests suddenly thrust on her.","cn":"突然又来了三位不速之客要她接待，她感到很恼火。"},{"en":"She thrust past him angrily and left.","cn":"她气呼呼地从他身旁挤过去走了。"}],"oxford":{"phon":"θrʌst","pos":"verb","senses":[{"en":"to push something/somebody suddenly or violently in a particular direction; to move quickly and suddenly in a particular direction","cn":"猛推；冲；搡；挤；塞","g":"[transitive, intransitive]","lab":"figurative","ex":{"en":"He thrust the baby into my arms and ran off.","cn":"他把婴儿往我怀里一塞就跑了。"}},{"en":"to make a sudden, strong forward movement at somebody with a weapon, etc.","cn":"刺；戳","g":"[intransitive, transitive]","ex":{"en":"He thrust at me with a knife.","cn":"他拿刀向我刺来。"}},{"en":"the main point of an argument, a policy, etc.","cn":"（论据、政策等的）要点，要旨，重点","g":"[singular]","ex":{"en":"The thrust of his argument was that change was needed.","cn":"他的论据要点是改革是必要的。"},"pos":"noun"},{"en":"a sudden, strong movement that pushes something/somebody forward","cn":"猛推；刺；戳；插","g":"[countable]","ex":{"en":"He killed her with a thrust of the knife.","cn":"他把她一刀刺死了。"},"pos":"noun"},{"en":"the force that is produced by an engine to push a plane, rocket, etc. forward","cn":"（发动机推动飞机、火箭等的）推力，驱动力","g":"[uncountable]","lab":"specialist","pos":"noun"}]}},"thatcher":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"盖茅草(或稻草、芦苇)屋顶的人","en":"A thatcher is a person whose job is making roofs from straw or reeds."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is making roofs from dried straw , reed s , leaves etc","cn":"盖茅草屋顶的人"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41thatcher.mp3","us":"media/ldoce/hwd/ame/f/ld41thatcher.mp3"},"oxford":{"phon":"ˈθætʃə(r)","pos":"noun","senses":[{"en":"a person whose job is thatching roofs","cn":"盖茅草屋顶的人"}]}},"three-cornered":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(争端、竞赛、比赛等)三角的，三人的，三方的","en":"If you describe something such as a disagreement, competition, or game as three-cornered, you mean that it involves three people, groups, or teams.","ex":{"en":"...the three-cornered struggle between employers and male and female workers.","cn":"雇主、男员工和女员工之间的三角纠纷"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having three corners","cn":"三角的﹐有三个角的"},{"en":"a competition which involves three people or groups","cn":"三方竞争/角逐"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41three-cornered.mp3","us":"media/ldoce/hwd/ame/9/three-cornered.mp3"},"examples":[{"en":"a three-cornered contest","cn":"三方竞争"},{"en":"a three-cornered hat","cn":"三角帽"}],"oxford":{"phon":"ˌθriː ˈkɔːnəd","pos":"adjective","senses":[{"en":"having three corners","cn":"三角形的；有三个角的；三隅的","ex":{"en":"a three-cornered hat","cn":"三角帽"}},{"en":"involving three people or groups","cn":"涉及三人的；三者的；三方的","ex":{"en":"a three-cornered contest","cn":"三方竞争"}}]}},"thatch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"茅草屋顶;稻草屋顶;芦苇屋顶","en":"A thatch or a thatch roof is a roof made from straw or reeds.","ex":{"en":"They would live in a small house with a green door and a new thatch.","cn":"他们将住在一所新苫顶的绿门小房子里。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(用来盖屋顶的)茅草,稻草，芦苇","en":"Thatch is straw or reeds used to make a roof.","ex":{"en":"Thatch is naturally warm in winter and cool in summer.","cn":"茅草料天生冬暖夏凉。"}},{"pos":"N-SING 单数名词","cn":"(尤指浓密蓬乱的)头发","en":"You can refer to someone's hair as their thatch of hair, especially when it is very thick and untidy.","ex":{"en":"Teddy ran thick fingers through his unruly thatch of hair.","cn":"特迪用自己的粗手指头捋了一下浓密蓬乱的头发。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"straw , reed s , leaves etc used to make a roof, or the roof made of them 〔","cn":"用来盖屋顶的〕茅草﹐稻草﹐芦苇﹔茅草屋顶"},{"en":"a thick untidy pile of hair on someone’s head","cn":"浓密的乱发"},{"en":"a thatched roof is made with dried straw , reed s , leaves etc","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/a/thatch0205.mp3","us":"media/ldoce/hwd/ame/d/thatch1.mp3"},"examples":[{"en":"The thatch was badly damaged in the storm.","cn":"茅草屋顶在暴风雨中遭到严重破坏。"},{"en":"They live in a thatched cottage.","cn":"他们住在茅舍里。"}],"oxford":{"phon":"θætʃ","pos":"noun","senses":[{"en":"dried straw, reeds, etc. used for making a roof; a roof made of this material","cn":"（用作屋顶的）茅草；茅草屋顶；草屋顶","g":"[uncountable, countable]","ex":{"en":"a roof made of thatch","cn":"茅草屋顶"}},{"en":"thick hair on somebody’s head","cn":"浓密的头发","g":"[singular]","lab":"informal","ex":{"en":"He had a thatch of thick brown hair.","cn":"他有一头浓密的棕色头发。"}},{"en":"to cover the roof of a building with thatch","cn":"用茅草盖屋顶","pos":"verb"}]}},"thump":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(常指用拳头)猛击，重击，捶打","en":"If you thump something, you hit it hard, usually with your fist.","ex":{"en":"He thumped my shoulder affectionately, nearly knocking me over","cn":"他亲热地捶了一下我的肩膀，差点把我打倒。"}},{"pos":"VERB 动词","cn":"(用拳头)打击，捶打","en":"If you thump someone, you attack them and hit them with your fist.","ex":{"en":"Don't say it serves me right or I'll thump you.","cn":"别说我活该，不然让你尝尝我的拳头。"}},{"pos":"V-ERG 及物/不及物动词","cn":"重重地摔出;沉闷地撞击","en":"If you thump something somewhere or if it thumps there, it makes a loud, dull sound by hitting something else.","ex":{"en":"She thumped her hand on the witness box","cn":"她抬手重重地砸在证人席上。"}},{"pos":"VERB 动词","cn":"(心脏)怦怦跳，咚咚跳","en":"When your heart thumps, it beats strongly and quickly, usually because you are afraid or excited.","ex":{"en":"My heart was thumping wildly but I didn't let my face show any emotion.","cn":"我的心在狂跳不已，但是我仍面不改色。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to hit someone quickly and hard with your hand, a stick etc","cn":""},{"en":"to hit someone deliberately many times, especially very hard","cn":""},{"en":"to hit someone with your hand or a weapon. Strike is more formal than hit and is mainly used in written English","cn":""}]},"collocations":{"phrases":["ADJ. good, heavy, loud | muffled","VERB + THUMP give sb/sth She gave the television a good thump, and the picture came back. | hear","PREP. with a ~ The sack of wheat hit the ground with a loud thump."]},"media":{"uk":"media/ldoce/hwd/bre/4/thump_las3_br.mp3","us":"media/ldoce/hwd/ame/e/thump1.mp3"},"examples":[{"en":"There was a thump as the truck hit the bank.","cn":"卡车撞在马路边坡上，发出砰的一声巨响。"},{"en":"He thumped the report down on my desk.","cn":"他嘭的一声把报告摔在我的办公桌上。"}],"oxford":{"phon":"θʌmp","pos":"verb","senses":[{"en":"to hit somebody/something hard, especially with your closed hand","cn":"重击；狠打；（尤指用拳）捶击","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"He thumped the table angrily.","cn":"他愤怒地用拳捶击桌子。"}},{"en":"to fall on or hit a surface hard, with a loud sound; to make something do this","cn":"（使）撞击，嘭地发出闷响","g":"[intransitive, transitive]","ex":{"en":"A bird thumped against the window.","cn":"一只鸟儿咚的一声撞在窗上。"}},{"en":"to beat strongly","cn":"强有力地跳动；怦怦地跳","g":"[intransitive]","ex":{"en":"My heart was thumping with excitement.","cn":"我激动得心怦怦跳。"}},{"en":"the sound of something heavy hitting the ground or another object","cn":"重击声；碰撞声","ex":{"en":"There was a thump as the truck hit the bank.","cn":"卡车撞在马路边坡上，发出砰的一声巨响。"},"pos":"noun"},{"en":"an act of hitting somebody/something hard","cn":"重击；捶击","lab":"informal","ex":{"en":"She gave him a thump on the back.","cn":"她在他背上重重打了一拳。"},"pos":"noun"}]}},"theology":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"神学;宗教学","en":"Theology is the study of the nature of God and of religion and religious beliefs.","ex":{"en":"...questions of theology.","cn":"神学问题"}},{"pos":"N-COUNT 可数名词","cn":"宗教观念(或信仰)","en":"A theology is a particular set of religious beliefs and ideas.","ex":{"en":"...cults, sects and bizarre theologies.","cn":"异教、宗派及稀奇古怪的宗教信仰"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the study of religion and religious ideas and beliefs","cn":"神学"},{"en":"a particular system of religious beliefs and ideas","cn":"宗教信仰体系"}]},"vocab":{"pos":"n","senses":[{"en":"Theology is the study of religion, plain and simple. Of course, religion isn’t simple, so theology covers a lot of subjects, like rituals, divine beings, the history of religions, and the concept of religious truth."}]},"collocations":{"phrases":["ADJ. dogmatic, liberal, natural, practical, systematic | ecumenical | traditional | eastern, western | Christian, Hindu, etc. | Catholic, Pr"]},"media":{"uk":"media/ldoce/hwd/bre/0/theology0205.mp3","us":"media/ldoce/hwd/ame/7/theology.mp3"},"examples":[{"en":"( NAmE ) a theological seminary","cn":"神学（修）院"},{"en":"( BrE ) a theological college","cn":"神学院"}],"oxford":{"phon":"θiˈɒlədʒi","pos":"noun","senses":[{"en":"the study of religion and beliefs","cn":"神学；宗教学；宗教信仰学","g":"[uncountable]","ex":{"en":"a degree in theology","cn":"神学学位"}},{"en":"a set of religious beliefs","cn":"宗教信仰","g":"[countable]","ex":{"en":"the theologies of the East","cn":"东方的种种宗教信仰"}}]}},"theorem":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(数学、逻辑上的)定理","en":"A theorem is a statement in mathematics or logic that can be proved to be true by reasoning."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement, especially in mathematics, that you can prove by showing that it has been correctly developed from facts 〔","cn":"尤指数学中的〕定理"}]},"vocab":{"pos":"n","senses":[{"en":"A theorem is a proposition or statement that can be proven to be true every time. In mathematics, if you plug in the numbers, you can show a theorem is true."}]},"media":{"uk":"media/ldoce/hwd/bre/2/theorem0205.mp3","us":"media/ldoce/hwd/ame/2/theorem.mp3"},"oxford":{"phon":"ˈθɪərəm","pos":"noun","senses":[{"en":"a rule or principle, especially in mathematics, that can be proved to be true","cn":"（尤指数学）定理","ex":{"en":"a mathematical theorem","cn":"数学定理"}}]}},"thicken":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"(使)(液体)变浓稠","en":"When you thicken a liquid or when it thickens, it becomes stiffer and more solid.","ex":{"en":"Thicken the broth with the cornflour","cn":"加玉米面使汤变稠。"}},{"pos":"VERB 动词","cn":"变密集;变浓密","en":"If something thickens, it becomes more closely grouped together or more solid than it was before.","ex":{"en":"The crowds around him began to thicken","cn":"他四周的人群密集起来。"}},{"pos":"PHRASE 短语","cn":"情况愈发复杂起来","en":"People sometimes say 'the plot thickens' when a situation or series of events is getting more and more complicated and mysterious.","ex":{"en":"'Find anything?' he asked. 'Yeah. The plot thickens,' I said.","cn":"“有什么发现没有？”他问。“嗯，情况越来越复杂了，”我说。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if a liquid thickens or you thicken it, it becomes more solid and does not flow very easily","cn":""},{"en":"if a liquid sets , for example some types of food or plastics, it becomes solid or almost solid after a period of time","cn":""},{"en":"if blood clots , it becomes thicker and more solid","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/2/thicken0205.mp3","us":"media/ldoce/hwd/ame/4/thicken.mp3"},"examples":[{"en":"Stir until the sauce has thickened.","cn":"不停地搅拌酱汁，直到搅稠为止。"},{"en":"It was a dangerous journey through thickening fog.","cn":"旅途中雾越来越大，险象环生。"}],"oxford":{"phon":"ˈθɪkən","pos":"verb","senses":[{"en":"to become thicker; to make something thicker","cn":"（使）变厚，变浓，变稠","ex":{"en":"Stir until the sauce has thickened.","cn":"不停地搅拌酱汁，直到搅稠为止。"}}]}},"therapist":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(专科的)治疗专家","en":"A therapist is a person who is skilled in a particular type of therapy.","ex":{"en":"My therapist helped me feel my anger.","cn":"我的治疗专家帮助我感受自己的怒气。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a doctor who is trained to treat people with mental illnesses","cn":""},{"en":"a scientist who studies and is trained in psychology (= the study of the mind )","cn":""},{"en":"a humorous word for a psychiatrist","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An expert at a specific kind of healing practice is called a therapist . A massage therapist is trained to soothe sore muscles, for example."}]},"collocations":{"phrases":["ADJ. trained | experienced | beauty, occupational, sex, speech • Note at DOCTOR • Note at JOB"]},"media":{"uk":"media/ldoce/hwd/bre/e/therapist0205.mp3","us":"media/ldoce/hwd/ame/6/therapist.mp3"},"examples":[{"en":"a speech therapist","cn":"语言治疗师"},{"en":"a beauty therapist","cn":"美容师"}],"oxford":{"phon":"ˈθerəpɪst","pos":"noun","senses":[{"en":"a specialist who treats a particular type of illness or problem, or who uses a particular type of treatment","cn":"（某治疗法的）治疗专家","ex":{"en":"a speech therapist","cn":"语言治疗师"}},{"en":"a person who is trained to treat somebody who has problems with their mental health by talking with them","cn":"心理治疗师"}]}},"thigh":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大腿;股","en":"Your thighs are the top parts of your legs, between your knees and your hips."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the top part of your leg, between your knee and your hip","cn":"大腿﹐股"},{"en":"the top part of a bird’s leg, used as food 〔","cn":"供食用的禽类的〕大腿"}]},"collocations":{"phrases":["ADJ. fat, flabby, plump | beefy, hard, huge, muscular, powerful, strong, sturdy | lean, slender, slim | bare, naked | silken | inner","THIGH + NOUN bone, muscle | injury, strain"]},"media":{"uk":"media/ldoce/hwd/bre/d/thigh0205.mp3","us":"media/ldoce/hwd/ame/d/thigh.mp3"},"examples":[{"en":"chicken thighs","cn":"鸡腿"}],"oxford":{"phon":"θaɪ","pos":"noun","senses":[{"en":"the top part of the leg between the knee and the hip (= where the leg joins the body)","cn":"大腿；股","lab":"informal"},{"en":"the top part of the leg of a chicken, etc., cooked and eaten","cn":"（食用的鸡等的）大腿"}]}},"thumbscrew":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"拇指夹(旧时的一种刑具)","en":"A thumbscrew is an object that was used in the past to torture people by crushing their thumbs."},{"pos":"N-COUNT 可数名词","cn":"极大的压力","en":"If someone puts the thumbscrews on you, they start to put you under extreme pressure in order to force you to do something."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an object that was used in the past to punish people by crushing their thumbs","cn":"拇指夹〔旧时刑具〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41thumbscrew.mp3","us":"media/ldoce/hwd/ame/9/thumbscrew.mp3"},"oxford":{"phon":"ˈθʌmskruː","pos":"noun","senses":[{"en":"an instrument that was used in the past for torturing people by pressing on and breaking their thumbs","cn":"拇指夹（旧时的一种刑具）"}]}},"thong":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"皮带;塑料带;橡胶带","en":"A thong is a long thin strip of leather, plastic, or rubber."},{"pos":"N-COUNT 可数名词","cn":"丁字裤","en":"A thong is a narrow band of cloth that is worn between a person's legs to cover up his or her sexual organs, and that is held up by a piece of string around the waist."},{"pos":"N-COUNT 可数名词","cn":"人字拖鞋","en":"Thongs are open shoes which are held on your foot by a V-shaped strap that goes between your big toe and the toe next to it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long thin piece of leather used to fasten something or as part of a whip 〔","cn":"系物用或皮鞭的〕皮条"},{"en":"a type of shoe that covers the bottom of your foot, with a strap that goes between your toes to hold it on your foot as you walk","cn":"平底人字拖鞋"},{"en":"a piece of underwear or the bottom half of a bikini that has a single string instead of the back part","cn":"丁字裤"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41thong.mp3","us":"media/ldoce/hwd/ame/2/thong.mp3"},"oxford":{"phon":"θɒŋ","pos":"noun","senses":[{"en":"a narrow piece of leather that is used to fasten something or as a whip","cn":"（用以系物或做皮鞭的）皮条"},{"en":"a pair of women’s knickers or men’s underpants that has only a very narrow piece of cloth, like a string, at the back","cn":"（背后为绳子一样窄条的）内裤；丁字内裤"},{"en":"a type of sandal (= open shoe), typically made of plastic or rubber, that has a piece that goes between the big toe and the toe next to it","cn":"人字拖鞋；夹脚趾拖鞋","lab":"North American English, Australian English, New Zealand English，，，，"}]}},"thirtieth":{"collins":{"senses":[{"pos":"ORD 序数词","cn":"第三十","en":"The thirtieth item in a series is the one that you count as number thirty."}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the number 30","cn":""},{"en":"the years from 1930 to 1939","cn":""},{"en":"to be aged between 30 and 39","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41thirty.mp3","us":"media/ldoce/hwd/ame/f/thirty.mp3"},"examples":[{"en":"In the thirties, air travel really began to take off.","cn":""},{"en":"The family sold the house in the early thirties.","cn":""}],"oxford":{"phon":"ˈθɜːtiəθ","pos":"noun","senses":[{"en":"each of thirty equal parts of something","cn":"三分之一"},{"en":"30th","cn":"第三十","pos":"ordinal number"}]}}});
